BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q104', 'システム戦略と経営戦略', '既存の業務プロセスや組織構造を前提とせず、顧客満足度やコスト・品質・スピードといった経営指標を抜本的に改善するために、業務のやり方をゼロから見直して再設計する取り組みを何と呼ぶか。', NULL::text, '["BPR(ビジネスプロセスリエンジニアリング)", "BPM(ビジネスプロセスマネジメント)", "SOA(サービス指向アーキテクチャ)", "ERP(統合基幹業務システム)"]', 0, '[0]', 'single', '{"asked": "既存の業務プロセスを前提にせず、経営指標を大きく改善するためにゼロから業務を再設計する取り組みの名称を問う設問。", "point": "「ゼロベースで一気に作り直す」なら BPR。「今のプロセスを少しずつ継続的に良くする」なら BPM。", "kid": "会社のやり方を今までの延長ではなく、まっさらな設計図から書き直すこと。", "eg": "古い家をリフォームで少しずつ直すのがBPM、更地にして新築を建て直すのがBPR。", "terms": [["BPR", "Business Process Reengineering。業務プロセスの抜本的再設計"], ["リエンジニアリング", "既存の仕組みを前提にせず作り直すこと"], ["経営指標", "コスト・品質・スピード・顧客満足度など会社の成果を測る物差し"]], "think": "なぜゼロから見直すことが必要になる場面があるのかがカギ。既存の業務プロセスは、過去の組織や技術の制約の中で少しずつ積み上がってきたものであり、部分ごとに改善を重ねても、そもそもの前提(誰がどの順番で何をするか)が古いままだと改善の効果に上限がある。そこで、経営指標(コスト・品質・スピード)を大きく跳ね上げたいときは、既存の手順を正しいと決めつけず、目的から逆算して業務のやり方自体をまっさらに設計し直す。これがBPRであり、部分最適の積み重ねでは届かない改善幅を狙う考え方である。", "vs": "BPMは今の業務プロセスを土台にして継続的に小さく改善し続ける活動。BPRは土台そのものを疑い、一度に大きく作り直す活動という点で対照的。", "why_asked": "BPRとBPMの違い(抜本的か継続的か)、BPRとERP(道具)を混同していないかを見る設問。", "opt": ["正解。既存の業務プロセスを前提とせず、経営指標を抜本的に改善するために業務をゼロから再設計する取り組みがBPRである。", "現状の業務プロセスを土台に、小さな改善を継続的に積み重ねていく活動であり、抜本的な再設計とは性格が異なる。", "業務システムの機能を独立した部品(サービス)として組み合わせるシステム設計の考え方であり、業務プロセスそのものの再設計を指す言葉ではない。", "企業の基幹業務(会計・人事・生産・販売など)のデータと業務を一つの仕組みに統合するシステムであり、業務プロセスを再設計する取り組みそのものではない。"]}'),
  ('ap-core-q105', 'システム戦略と経営戦略', 'BPR(業務プロセスリエンジニアリング)を進める際の留意点として、最も適切なものはどれか。', NULL::text, '["経営トップの主導のもと、部門を横断して業務プロセスとそれを支える情報システムを一体で見直す。", "現場の担当者だけで議論を進め、既存の業務プロセスの枠組みは変えずに細部の効率化にとどめる。", "情報システムを刷新すれば業務プロセスは自動的に最適化されるため、業務のやり方自体は検討しない。", "一度大きな改革を行った後は、環境が変化しても同じプロセスを固定して運用し続ける。"]', 0, '[0]', 'single', '{"asked": "BPRを実際に進めるときに気をつけるべきことは何かを問う設問。", "point": "「部門横断・経営トップ主導・システムと業務を一体で見直す」ならBPRの進め方として適切。", "kid": "一部門だけでなく会社全体を、経営トップの旗振りで、仕組みと働き方をセットで作り直すこと。", "eg": "一部屋だけ模様替えするのではなく、家全体の間取りを、施主(経営トップ)の判断で図面から引き直すイメージ。", "terms": [["部門横断", "特定の部署だけでなく複数の部署にまたがって業務を見ること"], ["情報システムと業務プロセスの一体的見直し", "システムだけ新しくしても、使う手順(業務プロセス)が古いままでは効果が出ないため、両方をセットで設計し直すこと"]], "think": "なぜ経営トップ主導かつ部門横断でなければいけないのかがカギ。業務プロセスは特定の部署だけで完結せず、複数の部署をまたいで受け渡しされていることが多いため、一部署だけの判断で見直すと、他部署とのつなぎ目に矛盾や手戻りが生まれる。また、既存の部門の権限や慣習を壊す変更になりやすいため、現場レベルの合意だけでは押し切れず、経営トップが旗を振ってはじめて全体最適の再設計が実現できる。さらに、情報システムだけを新しくしても、そこに乗る業務のやり方(誰が何をどの順でやるか)が古いままでは、システムの能力を活かしきれない。だから業務プロセスと情報システムは一体で見直す必要がある。", "vs": "現場担当者だけで議論し既存の枠組みを変えない進め方は、BPRではなくBPMの継続的改善に近い。情報システムを入れ替えるだけで業務のやり方を検討しない進め方は、BPRの業務プロセスを再設計するという核心が抜けている。", "why_asked": "BPRを「システム導入プロジェクト」や「現場改善」と混同していないかを見る設問。", "opt": ["正解。BPRは部門をまたぐ業務プロセスの再設計であり、経営トップの主導で、支える情報システムと業務のやり方を一体で見直す必要がある。", "現場担当者だけの議論で既存の枠組みを変えずに細部を効率化するのは、BPRではなく継続的な業務改善(BPM)に近い進め方である。", "情報システムを刷新しても、そこに乗る業務のやり方自体を見直さなければ、システムの能力を活かしきれず抜本的な改善にはつながらない。", "事業環境やビジネスモデルは変化し続けるため、一度作り直したプロセスを固定し続けることは、BPRが目指す継続的な競争力の維持にそぐわない。"]}'),
  ('ap-core-q106', 'システム戦略と経営戦略', '業務システムの機能を、独立して呼び出し可能な部品(サービス)として実装し、それらを組み合わせることでシステム全体を構築するアーキテクチャの考え方を何と呼ぶか。', NULL::text, '["SOA(サービス指向アーキテクチャ)", "BPR(ビジネスプロセスリエンジニアリング)", "ERP(統合基幹業務システム)", "SaaS(Software as a Service)"]', 0, '[0]', 'single', '{"asked": "業務機能を独立した部品(サービス)として実装し、組み合わせてシステムを作る設計の考え方の名称を問う設問。", "point": "「機能をサービス単位の部品にして組み合わせる設計思想」ならSOA。", "kid": "大きな1本のプログラムではなく、小さな機能ごとの部品を用意して、必要に応じて組み合わせて使う作り方。", "eg": "レゴブロックのように、決済・在庫確認・配送手配といった機能を独立したブロックとして作っておき、必要な組み合わせで新しいシステムを組み立てるイメージ。", "terms": [["SOA", "Service Oriented Architecture。サービス指向アーキテクチャ"], ["サービス", "呼び出せる独立した機能の単位。他のサービスから決まった手順(インタフェース)で呼び出せる"], ["疎結合", "部品同士のつながりが緩く、片方を変更してももう片方への影響が小さい状態"]], "think": "なぜ機能を独立した部品(サービス)にすると都合がよいのかがカギ。1本の大きなプログラムに全機能を詰め込むと、ある機能を直したいだけでもシステム全体を止めて修正・再テストする必要が生まれ、変更のたびにコストとリスクが大きくなる。そこで、業務機能を決済・在庫確認といった独立したサービスの単位に切り分けて作っておけば、あるサービスの中身を直しても、呼び出す側は決まった手順(インタフェース)さえ変わらなければ影響を受けない。さらに、既に作った部品を別の業務システムからも呼び出して再利用できるため、同じ機能を何度も作り直す無駄も減る。だから機能をサービス化して組み合わせる設計が、変更に強く再利用しやすいシステムにつながる。", "vs": "BPRは業務プロセスそのものの再設計であり、システムをどう組み立てるかという設計思想であるSOAとは階層が異なる。ERPは統合された業務パッケージ製品を指す言葉であり、SOAのようなシステムの設計思想を指す言葉ではない。SaaSはソフトウェアの提供形態(クラウド経由で使う)を指す言葉であり、システム内部の作り方を指すSOAとは別の話。", "why_asked": "SOAを「クラウドの一種」や「業務パッケージ」と混同していないか、システムの設計思想であることを理解しているかを見る設問。", "opt": ["正解。業務機能を独立して呼び出せる部品(サービス)として実装し、それらを組み合わせてシステム全体を構築する設計の考え方がSOAである。", "既存の業務プロセスを前提とせず、経営指標を抜本的に改善するために業務のやり方自体をゼロから再設計する取り組みであり、システムの内部設計の考え方ではない。", "会計・人事・生産・販売などの基幹業務を一つのパッケージ製品として統合的に扱う仕組みであり、機能を部品化して組み合わせる設計思想そのものを指す言葉ではない。", "ソフトウェアをインターネット経由のサービスとして利用する提供形態を指す言葉であり、システムの内部をどう部品化して作るかという設計の考え方ではない。"]}'),
  ('ap-core-q107', 'システム戦略と経営戦略', 'SOA(サービス指向アーキテクチャ)を採用したシステムにおいて、ある業務機能(サービス)の内部処理を変更する際の利点として、最も適切なものはどれか。', NULL::text, '["サービスを呼び出す側の手順(インタフェース)が変わらなければ、内部処理を変更しても呼び出す側のシステムに影響しない。", "システム全体を構成するプログラムをすべて同時に書き直す必要があるため、変更内容をまとめて一括で反映できるようになる。", "サービスごとに個別のデータベースを持つことは禁止されており、データの整合性を常に一元的に管理できるようになる。", "サービスを呼び出す側のプログラムも、内部処理の変更内容に合わせてそのつど必ず作り直す必要が生じる。"]', 0, '[0]', 'single', '{"asked": "SOAで作られたシステムで、ある機能(サービス)の中身を変更するとき、何が利点になるかを問う設問。", "point": "「呼び出し方(インタフェース)さえ変えなければ、中身を作り直しても他に影響しない」がSOAの利点。", "kid": "部品のつなぎ方を変えなければ、部品の中身だけ作り直しても他の部品は困らない。", "eg": "電源プラグの形(コンセントの規格)さえ変えなければ、家電の内部の仕組みをどう改良しても、コンセント側は何も困らないのと同じ。", "terms": [["インタフェース", "サービスを呼び出すときの決まった手順・約束事。中身を隠したまま外から使うための窓口"], ["疎結合", "部品同士のつながりが緩く、片方の変更がもう片方に及びにくい状態"]], "think": "なぜインタフェースさえ変えなければ影響が出ないのかがカギ。呼び出す側のシステムは、サービスの中身(どんな処理をどう実装しているか)を知らなくてもよく、決まった手順(インタフェース)で依頼を送り、決まった形で結果を受け取ることだけを前提に作られている。つまり呼び出す側とサービスの中身は、インタフェースという窓口を挟んで緩くつながっている(疎結合)。だから、サービスの中身を効率化したり別の技術で作り直したりしても、窓口の形(依頼の送り方・結果の返し方)さえ変わらなければ、呼び出す側は何も変更せずに使い続けられる。これが、機能ごとに独立して改良・再利用できるというSOAの利点を生む。", "vs": "全てのプログラムを同時に書き直す必要がある、呼び出す側も必ず作り直す必要がある、というのはSOAが避けたい状態そのものであり、疎結合の利点と正反対の説明になっている。", "why_asked": "SOAの疎結合という利点の中身(なぜ影響が及ばないのか)を理解しているかを見る設問。", "opt": ["正解。呼び出す側はインタフェース(決まった手順)だけを前提にサービスを利用するため、内部処理を変更してもインタフェースが変わらなければ呼び出す側に影響しない。", "システム全体を同時に書き直す必要があるのは、機能を独立した部品に分けず一体で作っている場合の話であり、疎結合であるSOAの利点とは逆の状況である。", "サービスごとにデータベースを持つかどうかは設計次第であり、SOAの定義として個別データベースが禁止されているわけではない。", "呼び出す側がインタフェースを変えずに使い続けられることがSOAの利点であり、内部処理の変更のたびに呼び出す側も作り直す必要があるなら、部品化のメリットが失われてしまう。"]}'),
  ('ap-core-q108', 'システム戦略と経営戦略', '自社で情報システムを開発・保有せず、クラウド事業者が提供するサービスを利用する形態を選ぶ経営上の理由として、最も適切なものはどれか。', NULL::text, '["自社でサーバーや開発体制を保有する初期投資を抑え、必要な分だけ利用料を支払う運用に切り替えられるため。", "自社の業務内容に完全に一致するようゼロから設計されたシステムを、必ず低コストで手に入れられるため。", "利用するサービスの内部の設計や実装をすべて自社の裁量で自由に変更できるようになるため。", "事業者が提供するサービスを使う契約を結べば、自社の情報システムに関する意思決定を今後一切行う必要がなくなるため。"]', 0, '[0]', 'single', '{"asked": "自社で開発・保有せずクラウドサービスを利用する形態を選ぶ、経営上の理由を問う設問。", "point": "「初期投資を抑えて使った分だけ払う」ならクラウド利用を選ぶ経営上の理由として適切。", "kid": "自分で工場(システム)を建てるのではなく、必要な分だけ借りて使うことでお金と手間を減らす考え方。", "eg": "自家用車を買って維持費を払い続けるのではなく、必要なときだけタクシーやカーシェアを使うことで、初期費用と管理の手間を減らすイメージ。", "terms": [["初期投資(イニシャルコスト)", "システムを導入する最初の段階でかかる費用。サーバー購入や開発費など"], ["従量課金", "使った分だけ料金を支払う課金の方式"]], "think": "なぜ自社開発・自社保有ではなく利用に切り替えることが経営判断として合理的になる場面があるのかがカギ。自社でシステムを開発・保有すると、サーバーや開発体制をあらかじめ用意する初期投資が必要になり、しかも利用量が少ない時期でもその設備を維持するコストがかかり続ける。一方、クラウド事業者が提供するサービスを利用すれば、事業者側が既に用意した設備・ソフトウェアを、使った分だけの利用料で使うことができるため、初期投資を抑えつつ、事業の立ち上がりに合わせて費用を柔軟に増減できる。だから、自社の強みではない情報システムの構築・運用に多額の投資をするより、外部のサービスを利用したほうが経営資源を事業の本業に集中できるという判断が成り立つ。", "vs": "「必ず低コスト」「内部設計を自由に変更できる」は、外部の標準化されたサービスを利用する形態の性質と食い違う。標準化されたサービスだからこそコストを抑えられる一方、内部の設計まで自社の裁量で自由に変えることはできない。", "why_asked": "クラウド利用の判断理由を「技術的にどう作られているか」ではなく「経営としてなぜ選ぶか」の視点で問う設問。", "opt": ["正解。自社でサーバーや開発体制を保有する初期投資を抑え、利用した分だけ料金を支払う運用に切り替えられることが、クラウドサービスを利用する経営上の主な理由である。", "クラウドサービスは多くの利用者に共通して提供される標準化されたサービスであり、自社の業務内容に完全一致するよう個別に設計されるものではない。", "クラウドサービスは事業者が用意した仕組みを利用する形態であり、内部の設計や実装を自社の裁量で自由に変更できるわけではない。", "サービスを利用する契約を結んでも、どのサービスを選び続けるか、契約内容をどう見直すかといった意思決定は自社に残り続ける。"]}'),
  ('ap-core-q109', 'システム戦略と経営戦略', '自社独自の要件が多く差別化の源泉となる業務システムと、多くの企業に共通する定型的な業務システムとで、クラウドサービスの利用方針を経営的に検討する際の考え方として、最も適切なものはどれか。', NULL::text, '["定型的な業務は標準化されたSaaSなどでコストと開発期間を抑え、独自性が競争力に直結する業務には開発の自由度が高いサービス形態や自社開発を検討する。", "どのような業務であっても、その業務の性格を考慮せず、価格の安さだけを基準に最も安価なサービス形態を一律に選ぶことが、経営判断として常に最も合理的である。", "独自性が競争力に直結する業務であるほど、標準化されたSaaSの機能や制約に自社の業務のやり方そのものを合わせて変えるべきである。", "他社と差がつきにくい定型的な業務であるほど、コストと開発期間をかけてでも自社専用に開発・保有するシステムを選ぶべきである。"]', 0, '[0]', 'single', '{"asked": "独自性が競争力の源泉になる業務と、多くの企業に共通する定型的な業務とで、クラウドサービスの利用方針をどう考えるべきかを問う設問。", "point": "「定型業務は標準化されたSaaS、独自性が強みの業務は自由度の高い開発」という使い分けが経営判断として適切。", "kid": "みんなと同じでよい仕事は既製品を使い、自社らしさで勝負する仕事は自分たちで作り込む、という使い分け。", "eg": "経理処理のようなどの会社もほぼ同じやり方でよい仕事は既製の会計ソフトを使い、自社の強みである独自の生産管理のような他社と同じにしたら差別化できない仕事は自社で作り込む、というイメージ。", "terms": [["差別化", "競合他社との違いを生み出し、自社の強みにすること"], ["標準化されたサービス", "多くの利用者に共通する機能をあらかじめ用意し、個別のカスタマイズをあまり前提としないサービス"]], "think": "なぜ業務の性格によってサービス形態の選び方を変える必要があるのかがカギ。標準化されたSaaSなどのサービスは、多くの企業に共通する定型的な業務を安く早く実現できる一方、あらかじめ用意された機能の範囲でしか動かせないため、自社だけの独自のやり方を反映しづらい。もし競争力の源泉となる独自業務まで標準化されたサービスに合わせてしまうと、他社と同じやり方になり差別化が失われてしまう。逆に、他社と同じでよい定型業務にまで自社独自でシステムを開発すると、開発コストと期間だけがかさみ、経営資源が本来の強みではないところに割かれてしまう。だから、定型業務は標準化されたサービスで効率化し、差別化したい業務には開発の自由度が高いサービス形態や自社開発を充てるという使い分けが合理的になる。", "vs": "一律に最も安いものを選ぶという考え方は業務の性格を無視した判断であり、差別化の観点が抜けている。独自性が強みの業務を標準化されたSaaSに合わせる、定型業務をあえて自社専用で開発する、はいずれも使い分けの向きが逆になっている。", "why_asked": "クラウド利用の判断を価格だけで決めていないか、業務の性格(差別化要因かどうか)に基づいて考えられているかを見る設問。", "opt": ["正解。定型的な業務は標準化されたSaaSなどでコストと開発期間を抑え、独自性が競争力に直結する業務には開発の自由度が高いサービス形態や自社開発を検討する、という使い分けが経営判断として適切である。", "業務の性格を考えずに一律で最も安いサービス形態を選ぶと、差別化したい独自業務まで標準化されたサービスに合わせることになり、競争力を損なうおそれがある。", "独自性が競争力に直結する業務を標準化されたSaaSに合わせてしまうと、他社と同じやり方になり、差別化の源泉そのものが失われてしまう。", "他社と差がつきにくい定型業務にまで自社専用のシステムを開発すると、開発コストと期間だけがかさみ、経営資源が本来注力すべき差別化業務に割けなくなる。"]}'),
  ('ap-core-q110', 'システム戦略と経営戦略', 'クラウドサービスを利用する経営上のメリットとして、需要の急な増減に対応するという観点から最も適切なものはどれか。', NULL::text, '["利用するコンピュータ資源の量を必要に応じて増減させ、繁忙期の一時的な需要増に合わせて費用を柔軟に変動させられる。", "契約時に確保した資源の量を一度決めると、その後は需要が増減してもサービス事業者との契約内容を変更する必要が一切ない。", "繁忙期の需要増に備えて、常に最大需要を見込んだ量の資源をあらかじめ自社で購入し保有しておく必要がある。", "クラウドサービスを利用すれば、需要の予測や資源計画を自社で検討する必要が完全になくなる。"]', 0, '[0]', 'single', '{"asked": "クラウドサービスを利用することが、需要の急な増減への対応という観点でどんな経営上のメリットになるかを問う設問。", "point": "「使う量を必要に応じて増減でき、費用も連動して変動する」がクラウド利用のメリット。", "kid": "忙しい時期だけ人手や設備を増やし、暇な時期は減らせるので、無駄な待機コストを抱えずに済むこと。", "eg": "繁忙期だけアルバイトを増やして、閑散期は人数を減らす飲食店の人員配置のように、必要な分だけ資源を借りて使うイメージ。", "terms": [["スケーラビリティ", "需要の増減に合わせて、使う資源の量を伸縮できる性質"], ["従量課金", "使った分だけ料金を支払う課金の方式"]], "think": "なぜ需要の増減に合わせて資源を伸縮できることが経営上のメリットになるのかがカギ。自社で設備を保有する場合、将来の最大需要を見込んで資源を用意しておかなければならず、繁忙期に足りなくなる事態を避けようとすると、普段は使われない余剰設備を抱えてその維持費を払い続けることになる。クラウドサービスは、多くの利用者で設備を共有し、必要な量だけを都度借りられる仕組みになっているため、需要が増えた時期だけ利用量を増やして対応し、需要が落ち着けば利用量を減らして費用も連動して下げられる。だから、最大需要に合わせた過剰投資をせずに、実際の需要に費用を近づけられることが経営上のメリットになる。", "vs": "契約内容を一切変更しない、常に最大需要分を自社購入するというのは、クラウドの柔軟な伸縮というメリットをむしろ使わない状態であり、自社保有の発想に近い。需要予測が完全に不要になるというのは誇張で、どの程度の資源が必要かという検討自体は利用側に残り続ける。", "why_asked": "クラウド利用のメリットを「柔軟に増減できること」ではなく「一度決めたら考えなくてよいこと」と誤解していないかを見る設問。", "opt": ["正解。利用するコンピュータ資源の量を需要に応じて増減させ、繁忙期の一時的な需要増に合わせて費用も柔軟に変動させられることが、クラウド利用のメリットである。", "需要は変動し続けるものであり、契約時に決めた資源量を変更せずに使い続けたのでは、需要増減への対応という柔軟性のメリットを活かせない。", "繁忙期の最大需要を見込んで自社で資源を保有し続けることは、クラウドを使わず自社設備で対応する発想であり、閑散期に余剰設備を抱えるコストが生じる。", "クラウドサービスを利用しても、どの程度の資源が必要かという需要の見積もり自体は利用側の検討が必要であり、完全に不要になるわけではない。"]}'),
  ('ap-core-q111', 'システム戦略と経営戦略', '企業の会計・人事・生産・販売といった基幹業務のデータと処理を一つの仕組みに統合し、経営資源を全体最適の視点で有効活用することを目的としたシステムを何と呼ぶか。', NULL::text, '["ERP(統合基幹業務システム)", "CRM(顧客関係管理)", "SCM(供給連鎖管理)", "BPR(ビジネスプロセスリエンジニアリング)"]', 0, '[0]', 'single', '{"asked": "企業の会計・人事・生産・販売といった基幹業務を一つの仕組みに統合し、経営資源を全体最適で活用することを目的とするシステムの名称を問う設問。", "point": "「社内の基幹業務を横断して一つに統合する」ならERP。", "kid": "会計も人事も生産も販売も、別々の帳簿ではなく一つの共通の仕組みで管理すること。", "eg": "部署ごとにバラバラの家計簿をつけていた家族が、一つの共通の家計簿アプリにまとめて、お金の出入りを全体で把握できるようにするイメージ。", "terms": [["ERP", "Enterprise Resource Planning。企業資源計画。基幹業務を統合的に管理する考え方・システム"], ["基幹業務", "会計・人事・生産・販売など、企業活動の根幹を支える業務"], ["全体最適", "部署ごとの都合ではなく、企業全体で見て最も効率がよい状態"]], "think": "なぜ基幹業務を一つに統合する必要があるのかがカギ。会計・人事・生産・販売がそれぞれ別々のシステムでデータを持っていると、部署ごとには効率的でも、例えば販売の受注状況が生産計画にすぐ反映されない、人件費の実績が会計にタイムラグをもって届くといった、部署間の連携の遅れやデータの不整合が起きやすい。基幹業務のデータと処理を一つの仕組みに統合すれば、ある部署で発生した情報が他部署からもすぐに参照でき、企業全体として資源(ヒト・モノ・カネ)をどう配分すれば最も効率がよいかを、部分ではなく全体で判断できるようになる。だから、部署ごとの部分最適ではなく企業全体の全体最適を狙う場合に、基幹業務を統合するERPが有効になる。", "vs": "CRMは顧客との関係にまつわる情報(問い合わせ・購買履歴など)の管理が対象であり、SCMは調達から販売までのモノの流れの管理が対象であるのに対し、ERPは会計・人事まで含めた社内の基幹業務全体を対象にする点が異なる。", "why_asked": "ERPを「販売管理システム」や「会計ソフト」など基幹業務の一部だけを指す言葉と混同していないかを見る設問。", "opt": ["正解。会計・人事・生産・販売といった基幹業務のデータと処理を一つの仕組みに統合し、経営資源を全体最適の視点で活用することを目的としたシステムがERPである。", "顧客との関係にまつわる情報(問い合わせ・購買履歴など)を管理し、顧客満足度の向上を目的としたシステムであり、基幹業務全体の統合を目的とするものではない。", "原材料の調達から生産・在庫・販売に至るモノと情報の流れを、取引先も含めて全体最適で管理することを目的としたシステムであり、社内の基幹業務全体の統合が主眼ではない。", "既存の業務プロセスや組織を前提とせず、経営指標を抜本的に改善するために業務のやり方自体をゼロから再設計する取り組みであり、システムの名称ではない。"]}'),
  ('ap-core-q112', 'システム戦略と経営戦略', '顧客ごとの問い合わせ履歴・購買履歴・対応状況といった情報を一元管理し、顧客との関係を深めて満足度や継続的な取引につなげることを目的とした経営手法・システムを何と呼ぶか。', NULL::text, '["CRM(顧客関係管理)", "SCM(供給連鎖管理)", "ERP(統合基幹業務システム)", "BPM(ビジネスプロセスマネジメント)"]', 0, '[0]', 'single', '{"asked": "顧客ごとの問い合わせ履歴・購買履歴などの情報を一元管理し、顧客との関係を深めて満足度や継続的な取引につなげることを目的とした経営手法・システムの名称を問う設問。", "point": "「顧客との関係を管理し満足度・継続取引を高める」ならCRM。", "kid": "お客さん一人ひとりの過去のやり取りを覚えておいて、次の対応をより良くする仕組み。", "eg": "行きつけの店の店員が自分の好みや過去の注文を覚えていて、次に来たときに声をかけてくれるような対応を、会社の規模でシステム的に行うもの。", "terms": [["CRM", "Customer Relationship Management。顧客関係管理"], ["顧客満足度", "顧客が商品やサービス、対応にどれだけ満足しているかを示す指標"], ["一元管理", "バラバラに存在する情報を一箇所にまとめて管理すること"]], "think": "なぜ顧客情報を一元管理することが顧客との関係強化につながるのかがカギ。顧客とのやり取りが部署や担当者ごとにバラバラに記録されていると、別の担当者が対応したときに過去の経緯を知らないまま同じ質問を繰り返したり、顧客の好みに合わない提案をしてしまったりする。顧客ごとの問い合わせ履歴・購買履歴・対応状況を一元管理すれば、どの担当者が対応しても顧客の過去の経緯を踏まえた対応ができ、顧客は自分のことを理解してもらえていると感じやすくなる。だから、顧客情報を一元管理して関係を深めることが、満足度の向上や継続的な取引につながる。", "vs": "SCMは原材料の調達から販売までのモノの流れの管理が対象であり、顧客一人ひとりとの関係を管理するCRMとは対象が異なる。ERPは社内の基幹業務全体の統合が対象であり、顧客との関係という対外的な観点に絞ったCRMとは範囲が異なる。", "why_asked": "CRMを単なる顧客データベースではなく、関係を深め満足度・継続取引につなげる目的の手法として理解しているかを見る設問。", "opt": ["正解。顧客ごとの問い合わせ履歴・購買履歴・対応状況を一元管理し、顧客との関係を深めて満足度や継続的な取引につなげることを目的とした経営手法・システムがCRMである。", "原材料の調達から生産・在庫・販売に至るモノと情報の流れを、取引先も含めて全体最適で管理することを目的としており、顧客一人ひとりとの関係管理が主眼ではない。", "会計・人事・生産・販売といった社内の基幹業務のデータと処理を一つの仕組みに統合することを目的としており、顧客との関係強化に絞った手法ではない。", "現状の業務プロセスを対象に、PDCAサイクルを回しながら継続的に改善していく活動であり、顧客との関係管理を目的とした手法ではない。"]}'),
  ('ap-core-q113', 'システム戦略と経営戦略', '原材料の調達から生産・在庫・販売に至るまでのモノと情報の流れを、取引先も含めて全体最適の視点で管理し、在庫の無駄や納期の遅れを減らすことを目的とした経営手法を何と呼ぶか。', NULL::text, '["SCM(供給連鎖管理)", "CRM(顧客関係管理)", "ERP(統合基幹業務システム)", "BPM(ビジネスプロセスマネジメント)"]', 0, '[0]', 'single', '{"asked": "原材料の調達から生産・在庫・販売までのモノと情報の流れを、取引先も含めて全体最適で管理し、在庫の無駄や納期の遅れを減らすことを目的とした経営手法の名称を問う設問。", "point": "「調達から販売までのモノの流れを、取引先も含めて管理する」ならSCM。", "kid": "材料を仕入れてから、作って、運んで、売るまでの一連の流れ全体を、会社の枠を超えてつなげて管理すること。", "eg": "川上の部品メーカーから川下の小売店まで水がスムーズに流れるように、途中で滞ったりあふれたりしないよう全体の流れを調整するイメージ。", "terms": [["SCM", "Supply Chain Management。供給連鎖管理"], ["サプライチェーン", "原材料の調達から生産・物流・販売に至る、モノが顧客に届くまでの一連のつながり"], ["在庫の無駄", "必要以上にモノを抱えてしまい、保管コストや廃棄のリスクが発生すること"]], "think": "なぜ自社の中だけでなく取引先まで含めて管理する必要があるのかがカギ。原材料の調達から生産・在庫・販売までは、自社だけでなく部品メーカーや物流会社、販売先といった複数の会社をまたいで進む。もし自社の中の在庫管理だけを最適化しても、取引先からの納品が遅れたり、逆に販売先の需要変化が自社に伝わるのが遅れたりすると、どこかで在庫が余ったり足りなくなったりする。取引先も含めてモノと情報の流れを見える化し調整すれば、必要な量を必要なタイミングで動かせるようになり、在庫の無駄や納期の遅れを減らせる。だから、自社単独ではなく取引先も含めた全体最適の管理がSCMの目的になる。", "vs": "CRMは顧客との関係にまつわる情報の管理が対象であり、モノの流れそのものを管理するSCMとは対象が異なる。ERPは社内の基幹業務全体の統合が対象であり、取引先も含めた社外とのモノの流れを管理するSCMとは範囲が異なる。", "why_asked": "SCMを自社内の在庫管理に矮小化していないか、取引先を含めた全体最適という点を理解しているかを見る設問。", "opt": ["正解。原材料の調達から生産・在庫・販売に至るモノと情報の流れを、取引先も含めて全体最適で管理し、在庫の無駄や納期の遅れを減らすことを目的とした経営手法がSCMである。", "顧客ごとの問い合わせ履歴・購買履歴といった情報を一元管理し、顧客との関係を深めることを目的としており、モノの流れそのものの管理が主眼ではない。", "会計・人事・生産・販売といった社内の基幹業務のデータと処理を一つの仕組みに統合することを目的としており、取引先も含めたモノの流れの管理が主眼ではない。", "現状の業務プロセスを対象に、PDCAサイクルを回しながら継続的に改善していく活動であり、取引先を含めたモノの流れの管理を目的とした手法ではない。"]}'),
  ('ap-core-q114', 'システム戦略と経営戦略', 'CRM・SCM・ERPを、それぞれが主に対象とする範囲の観点で比較した記述として、最も適切なものはどれか。', NULL::text, '["CRMは顧客との関係、SCMは調達から販売までの取引先を含めたモノの流れ、ERPは会計・人事も含めた社内の基幹業務全体を、それぞれ主な対象とする。", "CRM・SCM・ERPはいずれも、社内の基幹業務のデータをひとつの仕組みに統合することを主な目的とする点で、対象範囲に違いはない。", "CRMとSCMの対象が入れ替わっており、CRMは調達から販売までのモノの流れ、SCMは顧客との関係を、それぞれ主な対象とする。", "SCMとERPの対象が入れ替わっており、ERPは主に取引先を含めたサプライチェーン全体の最適化、SCMは社内の基幹業務の統合を、それぞれ主な目的とする。"]', 0, '[0]', 'single', '{"asked": "CRM・SCM・ERPが、それぞれ主にどの範囲を管理対象としているかを比較する設問。", "point": "「CRM=顧客との関係、SCM=取引先を含めたモノの流れ、ERP=社内の基幹業務全体」という対象範囲の違いで見分ける。", "kid": "誰(相手)を見ているかで区別すると、CRMはお客さん、SCMは仕入れ先から販売までのモノの流れ、ERPは自社の中の全部門。", "eg": "会社を家に例えると、CRMは玄関先でお客さんと交わす会話の記録、SCMは玄関の外(取引先)から品物が届いて出ていくまでの道筋、ERPは家の中の各部屋(各部署)を全部つなぐ共通の管理台帳。", "terms": [["対象範囲(スコープ)", "そのシステム・手法がどこからどこまでを管理の対象にしているかという範囲"], ["社外との連携", "取引先や顧客など、自社の外の相手とのやり取りを含めて管理すること"]], "think": "なぜ3つを対象範囲の違いで見分けるとよいのかがカギ。CRM・SCM・ERPはどれも企業の効率や競争力を高める手法・システムという点では似ているため、目的だけで覚えようとすると混同しやすい。そこで誰(何)を管理の対象にしているかに注目すると区別しやすくなる。CRMは顧客一人ひとりとの関係、SCMは調達から販売までのモノの流れを取引先も含めて、ERPは会計・人事まで含めた社内の基幹業務全体、というように対象とする相手や範囲がそれぞれ異なる。だから、目的の近さで混同せず、範囲の広さと向き(社外の顧客か、社外の取引先も含むか、社内全体か)で見分けるのがカギになる。", "vs": "SCMとERPはどちらもモノの流れ(生産・在庫・販売)に関わる部分で重なるため混同しやすいが、SCMは取引先という社外まで範囲が及ぶのに対し、ERPは会計・人事のような社内の管理業務を含む点で異なる。CRMは唯一、顧客という対外的な関係に特化しており、モノの流れそのものは主対象ではない。", "why_asked": "CRM・SCM・ERPをなんとなく似た経営システムとひとまとめにせず、対象範囲の違いで整理できているかを見る設問。", "opt": ["正解。CRMは顧客との関係、SCMは調達から販売までの取引先を含めたモノの流れ、ERPは会計・人事も含めた社内の基幹業務全体を、それぞれ主な対象とする。", "CRMは顧客との関係、SCMは取引先を含めたモノの流れ、ERPは社内の基幹業務全体というように、3つの対象範囲はそれぞれ異なっており、範囲に違いがないという説明は誤り。", "CRMとSCMの対象が逆になっている。CRMは顧客との関係、SCMは調達から販売までのモノの流れを、それぞれ主な対象とする。", "SCMとERPの対象が逆になっている。SCMは取引先を含めたサプライチェーン全体の最適化、ERPは社内の基幹業務の統合を、それぞれ主な目的とする。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"50\" y=\"14\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">調達</text>\n<text x=\"110\" y=\"14\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">生産</text>\n<text x=\"170\" y=\"14\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">在庫</text>\n<text x=\"230\" y=\"14\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">販売</text>\n<text x=\"290\" y=\"14\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">顧客関係</text>\n<line x1=\"20\" y1=\"20\" x2=\"20\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"80\" y1=\"20\" x2=\"80\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"200\" y1=\"20\" x2=\"200\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"260\" y1=\"20\" x2=\"260\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<line x1=\"320\" y1=\"20\" x2=\"320\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<rect x=\"20\" y=\"30\" width=\"240\" height=\"16\" fill=\"#3b82f6\" opacity=\"0.75\" rx=\"2\"/>\n<text x=\"140\" y=\"42\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">SCM(調達〜販売、取引先を含む)</text>\n<rect x=\"80\" y=\"60\" width=\"180\" height=\"16\" fill=\"#c9a04a\" opacity=\"0.75\" rx=\"2\"/>\n<text x=\"170\" y=\"72\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">ERP(社内の生産・在庫・販売)</text>\n<rect x=\"260\" y=\"90\" width=\"60\" height=\"16\" fill=\"#6ab08d\" opacity=\"0.85\" rx=\"2\"/>\n<text x=\"290\" y=\"102\" font-size=\"9\" fill=\"#e8eaf0\" text-anchor=\"middle\">CRM</text>\n<text x=\"20\" y=\"125\" font-size=\"8\" fill=\"#8892a4\">※ERPは会計・人事なども対象(この軸には未表示)</text>\n</svg>"}'),
  ('ap-core-q115', 'システム戦略と経営戦略', '情報システム戦略を策定する際の考え方として、最も適切なものはどれか。', NULL::text, '["経営戦略で示された事業の方向性や目標を実現する手段として、情報システムをどう整備・活用するかを検討し、経営戦略と整合させる。", "情報システム部門がその裁量だけで、経営戦略の内容とは無関係に将来必要になりそうな技術だけを選定して策定を進める。", "情報システム戦略は一度策定したら、その後に経営戦略が見直されても内容を一切変える必要はないものとして扱う。", "情報システム戦略の策定にあたっては、現場の業務担当者が日々感じている意見はいっさい考慮せず、経営層の判断のみですべてを決定するものとする。"]', 0, '[0]', 'single', '{"asked": "情報システム戦略をどのような考え方で策定すべきかを問う設問。", "point": "「経営戦略を実現する手段として位置づけ、経営戦略と整合させる」なら情報システム戦略の策定として適切。", "kid": "情報システムは会社の目標を叶えるための道具であり、その道具の使い方(戦略)は会社全体の目標に合わせて決めるということ。", "eg": "登山の目標地点(経営戦略)が決まってから、それに合った装備やルート(情報システム戦略)を選ぶのであって、装備を先に決めてから登る山を選ぶのではない。", "terms": [["経営戦略", "企業が事業でどこを目指し、どう競争していくかという全体方針"], ["情報システム戦略", "経営戦略を実現するために、情報システムをどう整備・活用するかという方針"], ["整合", "方針や内容が矛盾せず、互いにかみ合っていること"]], "think": "なぜ情報システム戦略を経営戦略と切り離さずに整合させる必要があるのかがカギ。情報システムはそれ自体が目的ではなく、企業が事業で目指す方向性(経営戦略)を実現するための手段の一つである。もし情報システム部門が経営戦略と関係なく技術選定を進めてしまうと、経営が目指す方向とは違う投資をしてしまい、せっかく整備したシステムが事業の役に立たないという事態が起きかねない。経営戦略が定める目標や事業の方向性を出発点にして、それを実現するために情報システムをどう整備・活用すべきかを検討すれば、投資したシステムが事業の成果に直結しやすくなる。だから、情報システム戦略は経営戦略と整合させて策定する必要がある。", "vs": "情報システム部門だけで経営戦略と切り離して技術を選定する、一度決めたら経営戦略が変わっても見直さない、現場の意見を考慮せず経営層だけで決める、といった進め方はいずれも、情報システムを経営戦略実現の手段として位置づける考え方から外れている。", "why_asked": "情報システム戦略を「技術部門が独自に決めるもの」と誤解していないか、経営戦略との整合という位置づけを理解しているかを見る設問。", "opt": ["正解。経営戦略で示された事業の方向性や目標を実現する手段として、情報システムをどう整備・活用するかを検討し、経営戦略と整合させることが情報システム戦略の考え方である。", "情報システムは経営戦略を実現する手段であり、経営戦略の内容と切り離して情報システム部門だけで技術選定を進めると、事業の目標に合わない投資をしてしまうおそれがある。", "経営戦略は事業環境の変化に応じて見直されるものであり、情報システム戦略もそれに合わせて見直さなければ、経営戦略との整合が保てなくなる。", "情報システムは現場の業務を支える道具でもあるため、現場の業務担当者の意見を考慮せずに経営層だけで決めると、実際の業務に合わないシステムになりかねない。"]}'),
  ('ap-core-q116', 'システム戦略と経営戦略', '情報システム戦略の内容として、一般に含まれるものはどれか。', NULL::text, '["経営戦略に基づいて、中長期的にどのような情報システムをどう整備し、そのためにどれだけの投資や体制を確保するかという方針・計画。", "個々の業務システムをどのプログラミング言語やフレームワークで開発するかという、実装レベルの技術選定にとどまる内容。", "個々のサーバーにおいて、どのような設定変更やソフトウェアのパッチ適用を行うかという、日々の運用現場レベルでの具体的な作業手順のこと。", "発生した障害やインシデントを、あらかじめ定めた手順に沿って日々処理していく運用上の細かいルールにとどまる内容。"]', 0, '[0]', 'single', '{"asked": "情報システム戦略の内容として、一般にどのようなものが含まれるかを問う設問。", "point": "「経営戦略に基づく中長期の整備方針・投資計画」なら情報システム戦略の内容として適切。個々の技術選定や日々の運用ルールは戦略ではなくその下位の実装・運用の話。", "kid": "情報システム戦略は何を目指してどう投資するかという大きな方針であり、どの言語で作るか、どう日々運用するかという細かい話ではないということ。", "eg": "会社の中期経営計画が今後3年でどの事業に投資するかという大枠を決める話であるのと同じように、情報システム戦略は今後どんなシステムにどう投資するかという大枠を決める話であり、実際のプログラムの書き方や日々の障害対応の手順とは階層が違う。", "terms": [["中長期計画", "数年単位の期間を見据えて立てる方針・計画"], ["投資・体制", "システム整備に必要な予算や、それを担う組織・人員"]], "think": "なぜ情報システム戦略には、個々の技術選定や日々の運用ルールが含まれないのかがカギ。戦略とは何を目指し、どこにどれだけの資源を投じるかという大きな方向性を定めるものであり、経営戦略と同じ抽象度で情報システムの整備方針・投資計画を扱う。一方、どのプログラミング言語で開発するか、どうサーバーを設定するか、日々の障害にどう対応するかといった話は、その戦略を実現するために現場で行う個別の実装や運用であり、扱う抽象度も時間軸(日々〜数か月)も戦略(数年単位)とは異なる。もし戦略の中に個々の技術選定や日々の運用ルールまで詰め込んでしまうと、経営環境が変わるたびに戦略そのものを書き換える羽目になり、大きな方向性を示すという戦略本来の役割を果たせなくなる。だから、情報システム戦略は中長期の方針・投資計画にとどめ、個々の実装や日々の運用は別の階層で扱う。", "vs": "個々のプログラミング言語の選定やサーバーの設定作業は、戦略を実現するための個別システムの実装レベルの話であり、戦略そのものではない。障害やインシデントへの日々の対応ルールは、情報システム戦略ではなくサービスマネジメント(運用)の領域に含まれる話であり、階層が異なる。", "why_asked": "情報システム戦略を、実装レベルの技術選定や日々の運用ルールと同じ階層のものと誤解していないかを見る設問。", "opt": ["正解。経営戦略に基づいて、中長期的にどのような情報システムをどう整備し、そのためにどれだけの投資や体制を確保するかという方針・計画が情報システム戦略の内容である。", "どのプログラミング言語やフレームワークで開発するかは、戦略を実現する個々の業務システムの実装レベルの技術選定であり、中長期の方針を示す情報システム戦略そのものではない。", "個々のサーバーの設定変更やパッチ適用の作業手順は、日々の運用・保守の話であり、中長期の投資・整備方針を示す情報システム戦略の内容ではない。", "発生した障害やインシデントへの日々の対応ルールは、サービスマネジメント(運用)の領域に含まれる話であり、中長期の方針を示す情報システム戦略とは階層が異なる。"]}'),
  ('ap-core-q117', 'システム戦略と経営戦略', '現状の業務プロセスを大きく作り替えるのではなく、計画・実行・評価・改善のサイクルを繰り返しながら、業務プロセスを継続的に改善していく活動を何と呼ぶか。', NULL::text, '["BPM(ビジネスプロセスマネジメント)", "BPR(ビジネスプロセスリエンジニアリング)", "SOA(サービス指向アーキテクチャ)", "ERP(統合基幹業務システム)"]', 0, '[0]', 'single', '{"asked": "現状の業務プロセスを土台に、計画・実行・評価・改善のサイクルを繰り返しながら継続的に改善していく活動の名称を問う設問。", "point": "「今のプロセスを土台に、サイクルを回して少しずつ改善し続ける」ならBPM。", "kid": "一気に作り直すのではなく、計画して、やってみて、振り返って、直す、を繰り返しながら少しずつ良くしていくこと。", "eg": "一度作った日課表を毎週見直して、うまくいかない部分だけ少しずつ調整していくように、業務のやり方を回しながら磨いていくイメージ。", "terms": [["BPM", "Business Process Management。ビジネスプロセスマネジメント"], ["PDCAサイクル", "計画(Plan)・実行(Do)・評価(Check)・改善(Act)を繰り返す改善の進め方"], ["継続的改善", "一度きりで終わらせず、繰り返し少しずつ改善し続けること"]], "think": "なぜ一気に作り替えず、サイクルを繰り返す進め方が有効な場面があるのかがカギ。業務プロセスを一度に大きく作り替えるBPRは、大きな効果を狙える一方、現場の混乱や失敗のリスクも大きく、頻繁に繰り返せる進め方ではない。一方、事業環境や業務の細部は日々少しずつ変化し続けるため、その変化に追従するには、計画して実行し、結果を評価し、うまくいかない点を直すというサイクルを繰り返しながら、無理のない範囲で業務プロセスを継続的に磨き続ける進め方が向いている。だから、抜本的な作り替えが必要な場面ではBPR、日々の変化に追従しながら磨き続ける場面ではBPMという使い分けが成り立つ。", "vs": "BPRは既存のプロセスを前提とせずゼロから一度に作り替える活動であるのに対し、BPMは既存のプロセスを土台にサイクルを繰り返しながら継続的に改善する活動という点で対照的。SOAはシステムの設計思想、ERPは基幹業務を統合するシステムであり、いずれも業務プロセスの改善サイクルそのものを指す言葉ではない。", "why_asked": "BPMとBPRを抜本的か継続的かで区別できているかを見る設問。", "opt": ["正解。計画・実行・評価・改善のサイクルを繰り返しながら、現状の業務プロセスを継続的に改善していく活動がBPMである。", "既存の業務プロセスを前提とせず、経営指標を抜本的に改善するために業務のやり方自体をゼロから作り替える取り組みであり、サイクルを繰り返す継続的な改善とは性格が異なる。", "業務システムの機能を独立した部品(サービス)として組み合わせるシステムの設計の考え方であり、業務プロセスの改善サイクルそのものを指す言葉ではない。", "会計・人事・生産・販売といった基幹業務を一つの仕組みに統合するシステムであり、業務プロセスの改善サイクルそのものを指す言葉ではない。"], "viz": "<svg viewBox=\"0 0 340 165\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<defs>\n<marker id=\"arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\">\n<path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#60a5fa\"/>\n</marker>\n</defs>\n<circle cx=\"170\" cy=\"25\" r=\"22\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"170\" y=\"29\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">計画</text>\n<circle cx=\"300\" cy=\"75\" r=\"22\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"300\" y=\"79\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">実行</text>\n<circle cx=\"170\" cy=\"125\" r=\"22\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"170\" y=\"129\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">評価</text>\n<circle cx=\"40\" cy=\"75\" r=\"22\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/>\n<text x=\"40\" y=\"79\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">改善</text>\n<path d=\"M188,38 L288,62\" stroke=\"#60a5fa\" stroke-width=\"1.5\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n<path d=\"M295,97 L182,116\" stroke=\"#60a5fa\" stroke-width=\"1.5\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n<path d=\"M155,118 L55,90\" stroke=\"#60a5fa\" stroke-width=\"1.5\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n<path d=\"M45,55 L155,32\" stroke=\"#60a5fa\" stroke-width=\"1.5\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n<text x=\"170\" y=\"158\" font-size=\"8\" fill=\"#8892a4\" text-anchor=\"middle\">このサイクルを繰り返し、業務プロセスを継続的に改善する(BPM)</text>\n</svg>"}'),
  ('ap-core-q118', 'システム戦略と経営戦略', 'BPM(ビジネスプロセスマネジメント)において、業務プロセスの改善を継続的に進めるために必要となる取り組みとして、最も適切なものはどれか。', NULL::text, '["業務プロセスの流れや実行結果を可視化・測定できるようにし、評価と改善のサイクルに反映できるようにする。", "一度定めた業務プロセスの手順を、以降は評価や見直しを行わずそのまま固定して運用し続けるようにする。", "業務プロセスの改善は現場の勘や経験だけに頼り、実行結果のデータは特に記録・測定しないようにする。", "経営環境が大きく変化した場合に限り、業務プロセス全体を一度だけゼロから作り替えるという進め方にとどめる。"]', 0, '[0]', 'single', '{"asked": "BPMで業務プロセスの改善を継続的に進めていくために、何をする必要があるかを問う設問。", "point": "「プロセスの流れや結果を可視化・測定し、評価に使えるようにする」ならBPMを進める上で必要な取り組み。", "kid": "改善のサイクルを回すには、今どうなっているかを見える形にして、良い悪いを測れるようにしておく必要があるということ。", "eg": "ダイエットの記録をつけずになんとなく頑張るだけでは改善点が分からないのと同じで、体重や食事を記録して初めて、次に何を直せばいいか分かるようになる。", "terms": [["可視化", "目に見えない業務の流れや状態を、図や数値で見える形にすること"], ["測定(モニタリング)", "業務プロセスの実行結果を数値などで継続的に把握すること"]], "think": "なぜ可視化・測定がなければBPMのサイクルが回らないのかがカギ。BPMは計画・実行・評価・改善のサイクルを繰り返す活動だが、評価の段階でうまくいったかどうかを判断する材料がなければ、何を改善すべきかが分からず、次の計画にもつなげられない。業務プロセスの流れや実行結果(処理件数・所要時間・エラー件数など)を可視化・測定できるようにしておけば、評価のときに具体的な数値や事実に基づいて問題点を特定でき、改善の的が絞れる。だから、可視化・測定の仕組みを整えることが、BPMのサイクルを実際に機能させるための前提になる。", "vs": "一度定めた手順を評価・見直しせず固定する、実行結果を記録・測定しないというのは、BPMが前提とする継続的な評価・改善のサイクルそのものを止めてしまう進め方であり適切ではない。経営環境の変化時にだけ一度プロセス全体をゼロから作り替えるのは、継続的な小さい改善を重ねるBPMではなく、BPRの進め方に近い。", "why_asked": "BPMを「なんとなく現場の努力で改善する活動」ではなく「可視化・測定を前提としたサイクル運用」として理解しているかを見る設問。", "opt": ["正解。業務プロセスの流れや実行結果を可視化・測定できるようにし、評価と改善のサイクルに反映できるようにすることが、BPMを継続的に進める上で必要な取り組みである。", "一度定めた手順を評価・見直しせず固定してしまうと、計画・実行・評価・改善のサイクルが回らず、継続的な改善という目的を果たせない。", "実行結果のデータを記録・測定しなければ、評価の段階で何を改善すべきかを具体的に判断する材料がなく、改善が場当たり的になってしまう。", "経営環境の変化時に一度だけプロセス全体をゼロから作り替える進め方は、継続的な小さい改善を重ねるBPMではなく、抜本的な再設計を行うBPRの進め方に近い。"]}')
) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q119', '技術戦略マネジメント',
   'MOT(Management of Technology、技術経営)の考え方の説明として、最も適切なものはどれか。',
   NULL::text,
   '["技術に立脚する事業を営む企業が、技術が持つ可能性を見極めて事業を継続的に創出し、経営に活かしていく考え方", "情報システムの開発を工程ごとに標準化した手順に沿って進め、成果物の品質のばらつきを一定の水準内に抑えるための管理手法", "工場の生産設備の稼働率を最大限に高めるため、日々の生産計画と定期的な保守点検の計画を一体的に管理していく手法", "従業員一人ひとりの技術面での習熟度を定期的に測定し、その結果を人事評価や報酬制度に直接反映させていく仕組み"]',
   0,
   '[0]',
   'single',
   '{"asked": "MOT(技術経営)という考え方が何を指すかを問う設問。", "point": "技術そのものではなく『技術を事業・経営の成果に結びつける考え方』がMOT。技術部門の作業標準化(開発工程管理)や人事制度とは別物。", "kid": "研究や開発で生まれた技術を、会社の儲けや将来につなげるための経営の考え方。", "eg": "発明家が良い技術を作っても、それを『どの製品にするか』『いつ市場に出すか』『どう資金を回すか』を考える人がいないと宝の持ち腐れになる。MOTはその『技術を経営に橋渡しする』役割を担う考え方。", "terms": [["MOT", "Management of Technology。技術を経営資源として活かし、事業の創出・成長につなげる考え方"], ["技術戦略", "MOTを実践するために、どの技術に投資しどう事業化するかを定めた方針"]], "think": "なぜ技術力があるだけでは事業として成功しないのかがカギ。優れた技術は市場に投入され、利益を生み、次の研究開発に再投資されて初めて企業の競争力になる。技術部門が良い成果を出しても、それを製品化のタイミングや投資判断、事業戦略と結びつける仕組みがなければ、技術は社内に埋もれたまま事業の成果に変わらない。MOTはこの『技術の可能性を見極め、事業として継続的に生み出し、経営に活かす』橋渡しの考え方であり、だから技術戦略マネジメントの土台に位置づけられる。", "why_asked": "MOTを単なる技術部門の効率化手法や品質管理手法と取り違えていないかを問う定番の切り口。", "vs": "開発工程の標準化(品質管理)や生産設備の稼働管理は、技術を『作る・動かす』ための個別の手法であり、技術を経営全体の成果に結びつけるMOTとは階層が異なる。", "opt": ["正解。MOTは技術の可能性を見極めて事業を継続的に創出し、経営に活かしていく考え方である。", "これは開発工程の標準化・品質管理の説明であり、MOTそのものの定義ではない。", "これは生産管理・設備保全の説明であり、MOTそのものの定義ではない。", "これは人事評価制度の説明であり、MOTそのものの定義ではない。"]}'),
  ('ap-core-q120', '技術戦略マネジメント',
   '研究開発から事業化・産業化に至る過程には、技術が乗り越えるべきいくつかの障壁があるとされる。このうち、事業化に成功した製品が、市場に投入された後に既存製品や競合他社との激しい競争にさらされる段階を表す用語はどれか。',
   NULL::text,
   '["ダーウィンの海", "魔の川", "死の谷", "ネットワーク外部性"]',
   0,
   '[0]',
   'single',
   '{"asked": "研究開発から事業化までの各障壁のうち、市場投入後の競争段階を表す用語を問う設問。", "point": "『事業化した後、市場で他社・他製品と競り合う段階』はダーウィンの海。基礎研究から応用研究への壁は魔の川、応用研究から事業化への壁は死の谷であり、段階が異なる。", "kid": "研究から商品が売れるまでには3つの関門があり、最後の関門(売り場での競争)がダーウィンの海。", "eg": "山登りに例えると、魔の川は『登る山を決める前の準備不足で諦める』段階、死の谷は『山を登り始めたが資金や体力が尽きて途中で引き返す』段階、ダーウィンの海は『山頂(市場)にたどり着いたのに、そこには先に来ていた他の登山者(競合製品)がひしめいていて、生き残り争いが始まる』段階にあたる。", "terms": [["魔の川", "基礎研究の成果が、実用化の見込みがなく応用研究に進めない障壁"], ["死の谷", "応用研究や試作はできても、資金・人員不足で量産・事業化に進めない障壁"], ["ダーウィンの海", "事業化した製品が、既存製品や競合他社との競争にさらされる障壁"]], "think": "なぜ障壁が1つではなく複数の段階に分かれているのかがカギ。研究開発は『技術が生まれる』『製品になる』『市場で売れ続ける』という性質の異なる3つの関門を順に越える必要がある。技術ができても実用化の目処が立たなければ次に進めず(魔の川)、実用化の目処が立っても量産する資金や体制がなければ商品にならず(死の谷)、商品になっても既存の製品や競合他社より選ばれなければ市場で生き残れない(ダーウィンの海)。この設問が指す『事業化に成功した後、既存製品や競合他社との競争にさらされる』段階は、まさに最後の関門であるダーウィンの海にあたる。", "why_asked": "魔の川・死の谷・ダーウィンの海という似た比喩を、どの段階の障壁かで正確に区別できるかを問う定番の切り口。", "vs": "ネットワーク外部性は、利用者数が増えるほどその製品・サービスの価値が高まるという別の経済現象を指す用語で、研究開発から事業化までの3つの障壁とは出典・文脈が異なる。", "opt": ["正解。事業化に成功した製品が、既存製品や競合他社との競争にさらされる段階をダーウィンの海と呼ぶ。", "魔の川は、基礎研究の段階で実用化の見込みが立たず応用研究に進めない障壁であり、市場投入後の競争段階ではない。", "死の谷は、応用研究や試作の段階で資金・人員が不足し量産・事業化に進めない障壁であり、市場投入後の競争段階ではない。", "ネットワーク外部性は利用者数の増加が価値を高めるという別の経済現象を指す用語であり、この3段階の障壁を表す用語ではない。"]}'),
  ('ap-core-q121', '技術戦略マネジメント',
   '技術ロードマップの説明として、最も適切なものはどれか。',
   NULL::text,
   '["横軸に時間の経過をとり、縦軸に市場・製品・技術などの要素をとって、将来の技術動向と自社の開発計画を時系列で対応づけて可視化した図", "プロジェクトで作成すべき成果物と、それに必要な作業を、管理しやすい単位まで段階的かつ階層的に分解して示した図", "システムが行う一連の処理の流れを、条件分岐や繰り返しの構造を含めながら順序立てて図式化して表した図", "開発工程の各段階であらかじめ作成すべき成果物と、それぞれを担当する要員や体制の割り当てを、組織図の形式で分かりやすく一覧化して示した図"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術ロードマップという図が何を表すものかを問う設問。", "point": "『時間軸に沿って市場・製品・技術の見通しを対応づけて可視化する』のが技術ロードマップ。作業分解(WBS)やフローチャートとは目的が異なる。", "kid": "これから何年かけてどんな技術・製品を出していくかを、時間の流れに沿って描いた地図。", "eg": "旅行の行程表に似ている。行程表は『1日目はここ、3日目はここ』と時間軸に沿って訪問先を並べるが、技術ロードマップは『今年はこの技術、3年後にこの製品、5年後にはこの市場』というように、時間軸に沿って技術・製品・市場の見通しを並べる。", "terms": [["技術ロードマップ", "時間軸に沿って技術・製品・市場の将来像を対応づけて示した図"], ["ロードマッピング", "技術ロードマップを作成・更新していく活動そのもの"]], "think": "なぜ技術ロードマップを『時間軸に沿った図』として作るのかがカギ。技術開発は数年単位の長い時間がかかるため、目先の開発だけを見ていると、将来どの技術が必要になるかの見通しを見誤り、投資のタイミングを逃してしまう。技術ロードマップは横軸に時間をとり、縦軸に市場・製品・技術の要素を並べることで、『いつまでにどの技術を確立し、それがどの製品に使われ、どの市場で必要とされるか』を関係者全員が同じ図の上で確認できるようにする。だから研究開発への投資判断や優先順位づけの共通の土台になる。", "why_asked": "技術ロードマップを、WBS(作業分解)やフローチャート(処理の流れ)、組織図など別の目的で使う図と取り違えていないかを問う。", "vs": "WBSは作業の分解、フローチャートは処理の順序、組織図は体制を表す図であり、いずれも『時間軸に沿って技術・製品・市場の将来像を示す』技術ロードマップの目的とは異なる。", "opt": ["正解。時間軸に沿って市場・製品・技術の将来像を対応づけて可視化するのが技術ロードマップである。", "これはWBS(作業分解構成図)の説明であり、技術ロードマップの説明ではない。", "これはフローチャート(流れ図)の説明であり、技術ロードマップの説明ではない。", "これは組織図の説明であり、技術ロードマップの説明ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">技術ロードマップ:3つの軸を時間で並べてすり合わせる</text>\n<line x1=\"70\" y1=\"35\" x2=\"320\" y2=\"35\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<text x=\"60\" y=\"38\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">市場</text>\n<circle cx=\"110\" cy=\"35\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"190\" cy=\"35\" r=\"4\" fill=\"#60a5fa\"/>\n<circle cx=\"270\" cy=\"35\" r=\"4\" fill=\"#60a5fa\"/>\n<line x1=\"70\" y1=\"75\" x2=\"320\" y2=\"75\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<text x=\"60\" y=\"78\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">製品</text>\n<rect x=\"100\" y=\"70\" width=\"20\" height=\"10\" fill=\"#3b82f6\"/>\n<rect x=\"180\" y=\"70\" width=\"20\" height=\"10\" fill=\"#3b82f6\"/>\n<rect x=\"260\" y=\"70\" width=\"20\" height=\"10\" fill=\"#3b82f6\"/>\n<line x1=\"70\" y1=\"115\" x2=\"320\" y2=\"115\" stroke=\"#2a2f3f\" stroke-width=\"1\"/>\n<text x=\"60\" y=\"118\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">技術</text>\n<rect x=\"95\" y=\"110\" width=\"25\" height=\"10\" fill=\"#6ab08d\"/>\n<rect x=\"175\" y=\"110\" width=\"25\" height=\"10\" fill=\"#6ab08d\"/>\n<rect x=\"255\" y=\"110\" width=\"25\" height=\"10\" fill=\"#6ab08d\"/>\n<line x1=\"110\" y1=\"35\" x2=\"110\" y2=\"115\" stroke=\"#2a2f3f\" stroke-dasharray=\"2,2\"/>\n<line x1=\"190\" y1=\"35\" x2=\"190\" y2=\"115\" stroke=\"#2a2f3f\" stroke-dasharray=\"2,2\"/>\n<line x1=\"270\" y1=\"35\" x2=\"270\" y2=\"115\" stroke=\"#2a2f3f\" stroke-dasharray=\"2,2\"/>\n<text x=\"70\" y=\"140\" font-size=\"9\" fill=\"#8892a4\">現在</text>\n<text x=\"300\" y=\"140\" font-size=\"9\" fill=\"#8892a4\">将来</text>\n</svg>"}'),
  ('ap-core-q122', '技術戦略マネジメント',
   '企業が技術ロードマップを作成し、組織内で共有する目的として、最も適切なものはどれか。',
   NULL::text,
   '["将来の技術動向の見通しと自社の技術開発計画をすり合わせ、研究開発投資の判断や優先順位づけを関係者間で共有できるようにするため", "各従業員の日々の作業スケジュールと勤務時間を詳細に記録し、勤怠状況を正確かつ継続的に把握できるようにするため", "ソースコードの変更履歴をバージョンごとに記録し、障害発生時にどこを変更したかを迅速に追跡できるようにするため", "開発したシステムの応答時間や処理件数、リソース使用率をあらかじめ定めた性能要件と突き合わせて満たしているかどうかを検証するため"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術ロードマップを作成・共有する目的そのものを問う設問。", "point": "目的は『将来の技術動向と自社の開発計画をすり合わせ、投資判断・優先順位づけを共有する』こと。勤怠管理や構成管理、性能検証とは別の話。", "kid": "この先どの技術にお金と人を割くべきかを、みんなで同じ地図を見ながら決められるようにするため。", "eg": "家族で家計簿を見ながら『来年は車の買い替え、再来年は住宅の修繕』と将来の大きな出費の計画をすり合わせるように、企業も技術ロードマップを見ながら『来年はこの技術に投資、再来年はこの製品化』という開発投資の計画を関係者ですり合わせる。", "terms": [["研究開発投資", "将来の技術や製品を生み出すために、資金や人員を研究開発に振り向けること"], ["優先順位づけ", "限られた資源をどの技術・製品に先に配分するかを決めること"]], "think": "なぜロードマップを『共有する』ことが目的の中心になるのかがカギ。技術開発には多くの部門(研究・開発・営業・経営層)が関わるが、各部門が自分の持つ情報だけで動くと、将来必要になる技術への投資判断がバラバラになったり、開発の優先順位について合意が取れなかったりする。技術ロードマップという1枚の図に将来の技術動向と自社の開発計画を並べて示すことで、関係者全員が同じ見通しの上で『何にいつ投資すべきか』を議論できるようになる。だから技術ロードマップの目的は、単に図を作ることではなく、それを使って投資判断や優先順位づけを組織全体で共有できるようにすることにある。", "why_asked": "技術ロードマップの目的を、勤怠管理やソースコード管理、性能検証といった別の管理活動の目的とすり替えていないかを問う。", "vs": "勤怠管理・構成管理・性能検証はいずれも個別の管理活動の目的であり、複数部門にまたがる技術開発計画のすり合わせを目的とする技術ロードマップとは対象も期間も異なる。", "opt": ["正解。将来の技術動向と自社の開発計画をすり合わせ、投資判断や優先順位づけを共有することが目的である。", "これは勤怠管理の目的であり、技術ロードマップの目的ではない。", "これは構成管理(バージョン管理)の目的であり、技術ロードマップの目的ではない。", "これは性能テストの目的であり、技術ロードマップの目的ではない。"]}'),
  ('ap-core-q123', '技術戦略マネジメント',
   '技術ロードマップと合わせて用いられることがある「特許ロードマップ」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["自社および競合他社の特許の出願・登録の状況を時系列に整理し、権利化や技術動向の推移を示した図", "保有する技術が、将来どの製品分野や事業領域に応用され製品化されていくかを時系列で示した図", "市場に投入した自社製品の販売実績や出荷台数を、年度ごとに棒グラフの形式で集計して示した図", "個々の技術が実用化に至るまでの研究開発の進み具合を、成熟度に応じていくつかの段階に分類して示した図"]',
   0,
   '[0]',
   'single',
   '{"asked": "特許ロードマップという図が何を示すものかを問う設問。", "point": "『自社・他社の特許の出願・登録状況を時系列で示す』のが特許ロードマップ。技術を製品分野に対応づける図(製品応用ロードマップ)とは対象が違う。", "kid": "どの会社が、いつ、どんな特許を取ってきたかを時間の流れで並べた図。", "eg": "将棋の対局を後から振り返る棋譜のように、特許ロードマップは『どの会社が、いつ、どの技術で特許を押さえたか』という権利獲得の手筋を時系列で並べたもの。これを見ると、競合がどの技術分野を先に押さえようとしているかが分かる。", "terms": [["特許ロードマップ", "自社・他社の特許の出願・登録状況を時系列に整理した図。技術動向や競合の権利化戦略を把握するのに使う"], ["製品応用ロードマップ", "保有する技術を将来どの製品・事業分野に応用していくかを時系列で示した図"]], "think": "なぜ技術ロードマップとは別に特許だけを取り出した図が要るのかがカギ。技術ロードマップは自社の技術・製品・市場の将来像を示すが、それだけでは『その技術分野を他社がどれだけ権利化しているか』は見えない。特許は一定期間、権利者に独占的な実施権を与える制度であるため、自社が有望と見込んだ技術分野を先に他社に特許で押さえられていると、その技術を自由に使えなくなるおそれがある。だから自社・他社の特許の出願・登録状況を時系列に整理した特許ロードマップを技術ロードマップと突き合わせ、権利面の空白地帯や競合の動きを把握したうえで研究開発の方向性を決める。", "why_asked": "特許ロードマップを、技術を製品分野に対応づける『製品応用ロードマップ』や、販売実績・研究進捗を示す別の図と取り違えていないかを問う。", "vs": "保有技術を将来の製品・事業分野に対応づけるのは製品応用ロードマップの役割であり、特許の出願・登録状況を時系列で示す特許ロードマップとは扱う対象が異なる。", "opt": ["正解。自社・他社の特許の出願・登録状況を時系列に整理し、権利化の推移を示すのが特許ロードマップである。", "これは製品応用ロードマップの説明であり、特許ロードマップの説明ではない。", "これは販売実績の集計グラフの説明であり、特許ロードマップの説明ではない。", "これは技術の成熟度を段階分類した図の説明であり、特許ロードマップの説明ではない。"]}'),
  ('ap-core-q124', '技術戦略マネジメント',
   '企業が技術戦略の一環として大学や公的研究機関と連携する「産学官連携」が重視される理由として、最も適切なものはどれか。',
   NULL::text,
   '["企業単独では不足しがちな基礎研究の知見や研究人材を大学・公的研究機関と補い合い、研究開発を効率的に進めて技術の実用化を早めるため", "大学が保有する特許について、企業が無償かつ独占的な形で譲り受けられるよう、手続きをあらかじめ簡略化しておくため", "企業が本来単独で担うべき量産化や生産の工程を公的研究機関にそのまま委託し、生産にかかるコストを削減するため", "政府調達の入札において自社製品や自社サービスが優先的に採用されるよう、公的機関の担当者との人的な関係をあらかじめ広く構築しておくため"]',
   0,
   '[0]',
   'single',
   '{"asked": "産学官連携が重視される理由そのものを問う設問。", "point": "産学官連携の理由は『不足する基礎研究の知見・人材を補い合い、実用化を早める』こと。特許の無償譲渡や量産委託、政府調達での優遇とは別の話。", "kid": "会社だけでは足りない研究の知恵や人手を、大学や国の研究機関と力を合わせて補うこと。", "eg": "運動会の綱引きで、自分のクラスだけでは人数が足りないときに、隣のクラスや先生にも加わってもらって一緒に綱を引くように、企業だけでは足りない基礎研究の力を大学や公的研究機関に加わってもらって補うのが産学官連携。", "terms": [["産学官連携", "企業(産)・大学(学)・公的機関(官)が協力して研究開発や実用化を進める取り組み"], ["基礎研究", "製品化を直接の目的とせず、原理や仕組みの解明を目的とする研究"]], "think": "なぜ企業単独ではなく大学・公的機関を巻き込む必要があるのかがカギ。企業の研究開発は事業化を前提とするため、すぐに製品に結びつきにくい基礎的な研究には資金や人員を割きにくい。一方で大学や公的研究機関は基礎研究の知見や専門人材を豊富に持つが、それを事業として実用化する力は弱い。双方が単独で進めるより、企業が事業化のノウハウを、大学・公的機関が基礎研究の知見を持ち寄って連携したほうが、研究開発から実用化までの過程を効率的に進められる。だから産学官連携は技術戦略の重要な選択肢として位置づけられる。", "why_asked": "産学官連携の目的を、特許の無償取得や生産委託、政府調達での優遇といった別の利害関係にすり替えていないかを問う。", "vs": "特許の無償独占譲渡や量産委託、政府調達での優遇は、産学官連携そのものの目的ではなく、連携の建前を悪用した誤った理解として誤答に用いられやすい。", "opt": ["正解。不足しがちな基礎研究の知見・人材を大学・公的研究機関と補い合い、実用化を早めることが産学官連携の目的である。", "産学官連携は特許を無償かつ独占的に譲り受けるための手続きではなく、共同での研究開発協力が目的である。", "量産化工程の委託によるコスト削減は産学官連携の目的ではない。連携の主眼は研究開発段階の協力にある。", "政府調達での優遇を目的として公的機関との関係を構築することは、産学官連携が重視される理由ではない。"]}'),
  ('ap-core-q125', '技術戦略マネジメント',
   '経営戦略における「コア技術」の考え方を説明したものとして、最も適切なものはどれか。',
   NULL::text,
   '["他社が容易に模倣できず、複数の製品・事業分野に応用でき、自社の競争優位の源泉となる技術", "製品の性能を左右する最先端の技術であれば、模倣の難しさや応用範囲を問わずすべて含まれる技術", "開発コストが最も高額な技術要素を指し、投資回収の優先度を決める基準となる技術", "特定の製品にのみ用いられる専用の技術であり、他の分野への転用は想定しない技術"]',
   0,
   '[0]',
   'single',
   '{"asked": "経営戦略上の「コア技術」が何を指すかを問う設問。", "point": "コア技術の条件は『模倣困難』かつ『複数の製品・事業分野に応用できる』こと。最先端かどうかや開発コストの大小、特定製品への専用性は条件ではない。", "kid": "自社の強みの源になっていて、他の会社が真似しにくく、いろんな製品に使い回せる技術。", "eg": "料理店の看板メニューを支える『秘伝のだし』のようなもの。だしそのものは1つでも、うどん・そば・丼物などいろいろなメニューに使い回せて、しかも他店が簡単には真似できない味を出せる。この『使い回せて、真似されにくい』土台がコア技術にあたる。", "terms": [["コア技術", "模倣困難で複数の製品・事業分野に応用でき、競争優位の源泉となる技術"], ["競争優位", "他社に対して優位に立てる、自社ならではの強み"]], "think": "なぜ『模倣困難』と『複数分野への応用可能性』の両方が条件になるのかがカギ。技術がどれだけ優れていても、他社が簡単に真似できるものであれば、その技術による優位はすぐに失われてしまう。また、1つの製品にしか使えない技術では、その製品が売れなくなった時点で技術の価値も失われ、企業全体を支える力にはならない。コア技術は、他社が真似しにくいために優位性が長く続き、かつ複数の製品・事業分野に横展開できるために企業全体の競争力を底上げする。この2つの性質がそろって初めて、単なる『良い技術』ではなく経営戦略上の『コア技術』と呼べる。", "why_asked": "コア技術の条件を、単に『最先端』『高コスト』『特定製品専用』といった別の性質にすり替えていないかを問う。", "vs": "最先端であることや開発コストの高さは、模倣困難性や応用範囲の広さとは別の性質であり、コア技術の必須条件ではない。特定製品にのみ使う専用技術は、応用範囲が狭くコア技術とは逆の性質を持つ。", "opt": ["正解。模倣困難で複数の製品・事業分野に応用でき、競争優位の源泉となる技術がコア技術である。", "最先端の技術であっても、模倣が容易であったり応用範囲が狭かったりすればコア技術とは呼べない。", "開発コストの高さはコア技術の条件ではない。コストが低くても模倣困難で応用範囲が広ければコア技術になり得る。", "特定の製品にのみ用いる専用技術は応用範囲が狭く、複数分野に応用できるというコア技術の条件を満たさない。"]}'),
  ('ap-core-q126', '技術戦略マネジメント',
   '技術獲得の方法の一つである「技術供与(ライセンシング)」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["技術を保有する企業が、対価(ロイヤリティなど)を得て他社にその技術の使用を許諾すること", "複数の企業が互いに資本や人材、設備などを出し合い、共同で新たな技術の開発に継続的に取り組むこと", "自社の研究開発部門が、既存の外部技術には頼らず、独自の発想と体制で一から技術を生み出していくこと", "他社を買収することで、その企業が保有する技術や事業、人材までを丸ごと自社のものとして取り込むこと"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術獲得の方法のうち「技術供与(ライセンシング)」が何を指すかを問う設問。", "point": "技術供与は『対価を得て技術の使用を許諾する』こと。共同開発(技術提携)、独自開発(自社開発)、買収(M&A)とは別の方法。", "kid": "技術を持っている会社が、お金をもらって他の会社にその技術を『使っていいよ』と許可すること。", "eg": "音楽の楽曲使用許諾に似ている。作曲者(技術を持つ会社)が、使用料(ロイヤリティ)をもらって、CMや店舗のBGMとして楽曲(技術)を使う権利を他社に許可する。技術そのものを譲り渡すのではなく、使う権利を対価と引き換えに貸し出す点がポイント。", "terms": [["技術供与(ライセンシング)", "対価を得て他社に技術の使用を許諾すること"], ["ロイヤリティ", "技術の使用許諾を受けた側が、供与元に支払う対価"]], "think": "なぜ技術供与という手段が使われるのかがカギ。技術を保有する企業にとって、自社だけでその技術を使う製品を作り続けるよりも、他社に使用を許諾して対価を得たほうが、開発費を回収しやすく収益源を広げられる場合がある。一方、技術を受け取る側にとっても、一から自社開発するより早く技術を使えるようになる。技術供与はこの『技術そのものの所有権は保有企業に残したまま、使用権だけを対価と引き換えに他社へ渡す』という性質を持つため、共同で開発する技術提携や、企業ごと取り込む買収(M&A)とは区別される。", "why_asked": "技術供与を、共同開発(技術提携)や自社開発、買収(M&A)といった他の技術獲得手段と取り違えていないかを問う。", "vs": "共同で技術を開発するのは技術提携、既存技術に頼らず自ら生み出すのは自社開発、企業ごと取り込むのは買収(M&A)であり、対価と引き換えに使用権のみを許諾する技術供与とはいずれも性質が異なる。", "opt": ["正解。対価を得て他社に技術の使用を許諾するのが技術供与(ライセンシング)である。", "これは技術提携(アライアンス)の説明であり、技術供与の説明ではない。", "これは自社開発の説明であり、技術供与の説明ではない。", "これは買収(M&A)による技術獲得の説明であり、技術供与の説明ではない。"]}'),
  ('ap-core-q127', '技術戦略マネジメント',
   '技術獲得の方法として、他社との技術提携(アライアンス)を選ぶことが適切な状況として、最も適切なものはどれか。',
   NULL::text,
   '["必要な技術は存在するが自社だけでは開発期間や人員などのリソースが不足しており、他社と互いの強みを補い合うことで早期に製品化したい場合", "技術の詳細な中身がブラックボックスのままでも構わず、対価さえ支払えば使用権だけをすぐに得られればよい場合", "競合他社に模倣されたくない自社の中核技術については、多少の時間や費用がかかったとしても自社の研究開発部門だけで育てていきたい場合", "他社の事業そのものを早期にまとめて取り込みたく、その企業が持つ経営資源や人材、取引先との関係までを丸ごと自社の内部に統合してしまいたい場合"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術獲得の複数の方法(技術提携・技術供与・自社開発・買収)のうち、技術提携が適する状況を問う設問。", "point": "技術提携は『必要な技術はあるが自社だけではリソースが不足し、他社と補い合いたい』場合に適する。使用権のみでよい場合は技術供与、自社で育てたい場合は自社開発、事業ごと取り込みたい場合は買収が適する。", "kid": "自分たちだけでは足りない部分を、他の会社と力を合わせて早く形にしたいときに選ぶ方法。", "eg": "引っ越しの荷物運びで、大きな家具を一人では運べないときに、友人に声をかけて一緒に運ぶようなもの。互いの足りない力(人手)を補い合って、一人で運ぶより早く目的を達成できる。技術提携もこれと同じで、互いの強みを持ち寄って早く製品化するために選ぶ。", "terms": [["技術提携(アライアンス)", "複数の企業が資本や人材を出し合い、共同で技術開発や事業に取り組むこと"], ["自社開発", "既存の外部技術に頼らず、自社の研究開発部門が独自に技術を生み出すこと"]], "think": "なぜ状況によって技術獲得の方法を使い分けるのかがカギ。技術を得る手段には、自社だけで一から作る自社開発、対価を払って使用権だけを得る技術供与、複数社で協力して開発する技術提携、相手企業ごと取り込む買収があり、それぞれ得られるものと引き換えに必要な時間・費用・関係の深さが異なる。使用権さえあればよいなら技術供与で足り、中核技術を守りたいなら時間をかけても自社開発を選ぶべきであり、事業ごと必要なら買収が適する。技術提携が適するのは、必要な技術の見通しはあるが自社単独では開発期間や人員が足りず、他社の強みと補い合うことで開発期間を短縮しつつ、技術そのものへの関与も保ちたい場合である。", "why_asked": "技術提携を、性質の異なる技術供与・自社開発・買収(M&A)と取り違えていないかを問う。", "vs": "使用権だけで足りるなら技術供与、模倣されたくない中核技術を守りたいなら自社開発、経営資源ごと取り込みたいなら買収が適し、いずれも『互いの強みを補い合って共同で開発する』技術提携とは選ぶべき状況が異なる。", "opt": ["正解。自社単独ではリソースが不足し、他社と補い合うことで早期に製品化したい場合に技術提携が適する。", "使用権だけを対価と引き換えに得たい場合は技術供与(ライセンシング)が適し、共同開発を伴う技術提携が適する状況ではない。", "中核技術を時間をかけても自社だけで育てたい場合は自社開発が適し、他社と協力する技術提携が適する状況ではない。", "他社の事業ごと経営資源を取り込みたい場合は買収(M&A)が適し、共同開発にとどまる技術提携が適する状況ではない。"]}'),
  ('ap-core-q128', '技術戦略マネジメント',
   '標準化戦略における「デジュールスタンダード」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["ISOやJISなど公的な標準化機関が、公式な手続きを経て制定する標準規格", "特定の技術に関心を持つ複数の企業が集まり、コンソーシアムを結成して策定する標準規格", "公的な策定プロセスを経ずに、市場での競争の結果として広く普及し事実上の標準となった規格", "単一の企業が自社製品だけに閉じた形で採用し、他社への開示を前提としない独自仕様"]',
   0,
   '[0]',
   'single',
   '{"asked": "標準化戦略上の「デジュールスタンダード」が何を指すかを問う設問。", "point": "デジュールスタンダードは『ISO・JISなど公的機関が公式な手続きで制定する標準』。企業連合が作るのはフォーラム標準、市場競争の結果できるのはデファクトスタンダードで、いずれも別物。", "kid": "国や国際機関が、決まった手続きを踏んで正式に定める規格。", "eg": "国会で法律が審議・可決されて正式に成立するように、デジュールスタンダードもISOやJISといった公的な機関で審議・承認の手続きを経て正式に成立する規格。手続きが公式である分、時間はかかるが誰もが従うべき権威を持つ。", "terms": [["デジュールスタンダード", "ISO・JISなど公的な標準化機関が公式な手続きを経て制定する規格"], ["フォーラム標準", "特定の技術に関心を持つ複数企業がコンソーシアムを結成して策定する規格"], ["デファクトスタンダード", "公的な手続きを経ず、市場競争の結果として広く普及した事実上の標準"]], "think": "なぜ標準化の方式がデジュール・フォーラム・デファクトの3つに分かれるのかがカギ。標準規格は『どれだけ公式な手続きを経て決まるか』と『誰が主導するか』によって性質が変わる。ISOやJISのような公的機関が審議・承認する手続きを踏めば、時間はかかるが国際的・国家的な権威を持つ規格になり、これがデジュールスタンダードである。一方、企業連合が自主的に集まって決めればフォーラム標準、公的な手続きを経ずに市場での競争の結果として広まればデファクトスタンダードとなる。この設問はそのうち『公的機関による公式な手続き』という性質を持つデジュールスタンダードを問うている。", "why_asked": "デジュールスタンダードを、フォーラム標準やデファクトスタンダード、単一企業の独自仕様と取り違えていないかを問う定番の切り口。", "vs": "企業連合が策定するのはフォーラム標準、市場競争の結果広まるのはデファクトスタンダードであり、いずれも公的機関による公式な手続きを前提とするデジュールスタンダードとは策定主体・プロセスが異なる。", "opt": ["正解。ISOやJISなど公的な標準化機関が公式な手続きを経て制定する規格がデジュールスタンダードである。", "これはフォーラム標準の説明であり、デジュールスタンダードの説明ではない。", "これはデファクトスタンダードの説明であり、デジュールスタンダードの説明ではない。", "これは単一企業の独自仕様の説明であり、デジュールスタンダードの説明ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q129', 'システム開発技術とソフトウェア開発管理技術',
   'システム要件定義とソフトウェア要件定義の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["システム要件定義は業務全体を対象に情報システムが実現すべき機能や性能を明らかにし、ソフトウェア要件定義はその中でソフトウェアが担う部分について必要な機能や仕様を明らかにする。", "システム要件定義は開発するプログラムのコーディング規約や命名規則を細かく定める工程であり、ソフトウェア要件定義は利用者が操作する画面のレイアウトや帳票の様式を具体的に定める工程である。", "システム要件定義はソフトウェアの内部構造やデータ構造を確定する工程であり、ソフトウェア要件定義は業務全体を対象とした対象範囲や利害関係者の要求を確定する工程である。", "システム要件定義とソフトウェア要件定義は実質的に同じ内容を指す別名であり、担当する範囲やまとめる成果物に違いはなく、実務上厳密に区別する必要はない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "システム要件定義とソフトウェア要件定義は何が違うかを問う設問。", "point": "『業務全体・システム全体』を主語にするか『ソフトウェア(の担当範囲)』を主語にするかで見分ける。", "kid": "システム要件定義は『家全体の間取りをどうするか』、ソフトウェア要件定義は『台所という一部屋の設備をどう作るか』を決める話。", "eg": "オーケストラの演奏会全体の構成(システム要件定義)を決めてから、各楽器のパート譜(ソフトウェア要件定義)を書くようなもの。全体の曲の構成を決めずに個々のパート譜だけ書くと、パート同士がかみ合わない。", "terms": [["システム要件定義", "情報システム全体で実現すべき機能・性能を明らかにする工程"], ["ソフトウェア要件定義", "システムを構成する個々のソフトウェアに必要な機能・仕様を明らかにする工程"], ["要件定義", "開発を始める前に「何を実現するか」を利用者と開発側で合意する工程全般"]], "think": "システム要件定義とソフトウェア要件定義を分ける理由がカギ。大規模なシステムでは複数のソフトウェアやハードウェアが組み合わさって動く。そこでまず「システム全体として何を実現するか」を決め、その上で「その一部を担う個々のソフトウェアに何をさせるか」を決めないと、担当範囲がバラバラのまま開発が進んでしまう。だから対象範囲の広さで工程を分ける。", "vs": "外部設計・内部設計との違いは、要件定義が『何を実現するか』を決める工程であるのに対し、外部設計・内部設計は要件定義で決まったことを『どう作るか』に落とし込む工程である点。", "why_asked": "応用情報技術者試験では、開発工程の各段階が何を確定させる工程かを正確に区別できるかを問う出題が定番。上流工程ほど『対象範囲(システム全体かソフトウェアか)』を意識できているかが狙われる。", "opt": ["正解。システム要件定義は業務全体・システム全体を対象に「システムが何を実現するか」を明らかにし、ソフトウェア要件定義はその中でソフトウェアが担当する部分に絞って必要な機能・仕様を明らかにする。対象の広さが違う。", "コーディング規約や画面レイアウトはどちらも実装に近い工程で扱う内容であり、システム要件定義・ソフトウェア要件定義のどちらの説明にも当たらない。", "内部構造の確定と対象範囲の確定が入れ替わっている。業務全体の対象範囲を確定するのはシステム要件定義側であり、逆になっている。", "システム要件定義とソフトウェア要件定義は対象とする範囲(システム全体かソフトウェアの担当部分か)が異なる、別の工程である。"]}'),
  ('ap-core-q130', 'システム開発技術とソフトウェア開発管理技術',
   '要件定義と、それに続く外部設計の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["要件定義は利用者が業務上何を実現したいかを明らかにする工程であり、外部設計はその要件を満たすために画面や帳票などをどのように作るかを具体化する工程である。", "要件定義はプログラムの内部で扱うデータ構造や処理手順を細かく確定する工程であり、外部設計は利用者を個別に訪問して業務上の要求をあらためて聞き取る工程である。", "要件定義はシステム全体を対象とした受け入れテストの計画を確定する工程であり、外部設計はプログラムのコーディング規約や命名規則を確定する工程である。", "要件定義と外部設計はどちらも同じ担当者が同時並行で進めるべき工程であり、内容や確認する相手による役割分担は特に存在しない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "要件定義と外部設計の役割の違いを問う設問。", "point": "『何を実現するか』を決めるのが要件定義、『どう実現するか』の入口(利用者から見える形)を決めるのが外部設計、と主語で見分ける。", "kid": "要件定義は『欲しいものリストを作る』段階、外部設計は『そのリストをもとに見た目や操作方法の設計図を描く』段階。", "eg": "注文住宅で言えば、要件定義は『家族4人で庭付き、日当たりのいいリビングが欲しい』という要望を固める段階。外部設計は、その要望をもとに『リビングをどの位置に置き、窓をどこに配置するか』という間取り図を描く段階。", "terms": [["要件定義", "利用者が業務上何を実現したいかを明らかにする工程"], ["外部設計", "要件を満たすために画面・帳票など利用者から見える部分の仕様を具体化する工程"], ["手戻り", "後工程で問題が見つかり、前の工程からやり直すこと"]], "think": "なぜ工程を分けるのかがカギ。要件定義で「何を実現したいか」を利用者と開発側が先に合意しておかないと、外部設計で画面や帳票の形を作り始めても、途中で『そもそも欲しかったのはこれじゃない』という手戻りが起きる。逆に要件定義の段階で画面の細かいレイアウトまで決めてしまうと、実現方法に開発側の工夫の余地が残らなくなる。だから『何を』と『どう見せるか』を別の段階として分ける。", "vs": "システム要件定義/ソフトウェア要件定義との違いは『対象範囲(システム全体かソフトウェアか)』の軸であるのに対し、要件定義と外部設計の違いは『工程の役割(何を実現するか、それをどう見せる形にするか)』という別の軸である点。", "why_asked": "要件定義と設計の境界を曖昧にしたまま開発を進めると仕様が二転三転する原因になるため、各工程が何を確定させる場かを正確に区別できるかが問われる。", "opt": ["正解。要件定義は『何を実現したいか』という利用者の業務要求を明らかにする工程であり、外部設計はその要件を満たすために画面・帳票など利用者から見える部分をどう作るか具体化する工程である。", "内部構造の確定と業務要求の聞き取りが入れ替わっている。業務要求を聞き取るのは要件定義側であり、逆になっている。", "テスト計画やコーディング規約は要件定義・外部設計のどちらの説明でもなく、別の工程(テスト工程・開発プロセス)の内容である。", "要件定義と外部設計は『何を』と『どう見せるか』という役割の違いがあり、順序立てて進めるべき別の工程である。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><marker id=\"ar2\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#60a5fa\"/></marker></defs>\n<g font-family=\"sans-serif\">\n<rect x=\"30\" y=\"45\" width=\"110\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/>\n<text x=\"85\" y=\"68\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e8eaf0\">要件定義</text>\n<text x=\"85\" y=\"84\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">何を実現するか</text>\n<rect x=\"200\" y=\"45\" width=\"110\" height=\"50\" rx=\"6\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"255\" y=\"68\" text-anchor=\"middle\" font-size=\"12\" fill=\"#e8eaf0\">外部設計</text>\n<text x=\"255\" y=\"84\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">どう見せるか</text>\n<line x1=\"140\" y1=\"70\" x2=\"196\" y2=\"70\" stroke=\"#60a5fa\" stroke-width=\"1.8\" marker-end=\"url(#ar2)\"/>\n</g>\n<text x=\"170\" y=\"125\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"#8892a4\" font-family=\"sans-serif\">要件定義で決めた「何を」を、外部設計で見える形に具体化する</text>\n</svg>"}'),
  ('ap-core-q131', 'システム開発技術とソフトウェア開発管理技術',
   '外部設計と内部設計の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["外部設計は利用者から見える画面や帳票、操作方法などを設計する工程であり、内部設計は外部設計の内容を実現するためのプログラム内部の処理や構造を設計する工程である。", "外部設計はプログラムの内部だけで使うアルゴリズムやデータ構造を細かく設計する工程であり、内部設計は利用者が操作する画面のレイアウトや帳票の様式を設計する工程である。", "外部設計は開発したプログラムの部品ごとに行う単体テストを実施する工程であり、内部設計はシステム全体を対象として利用者が行う受け入れテストを実施する工程である。", "外部設計はシステム開発を外部の協力会社に委託するための契約条件を取り決める工程であり、内部設計は自社内の開発要員の配置や作業分担をあらかじめ決める工程である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "外部設計と内部設計の役割の違いを問う設問。", "point": "利用者から『見える』ものを決めるのが外部設計、利用者から『見えない』プログラム内部の作りを決めるのが内部設計。", "kid": "外部設計は『お店の看板や陳列棚の見た目』を決める話。内部設計は『お店の裏側の在庫管理や仕入れの仕組み』を決める話。", "eg": "テレビで言えば、外部設計はリモコンのボタン配置や画面メニューの見た目を決める作業。内部設計は、そのボタンを押したときにテレビの中の回路がどう信号を処理するかを決める作業。視聴者はリモコンとメニューしか見ないが、中の回路設計がなければテレビは動かない。", "terms": [["外部設計", "利用者から見える画面・帳票・操作方法を設計する工程。外部仕様ともいう"], ["内部設計", "外部設計を実現するためのプログラム内部の処理・データ構造を設計する工程。内部仕様ともいう"], ["単体テスト", "内部設計で決めたプログラム部品ごとに正しく動くかを確認するテスト"]], "think": "なぜ『見える/見えない』で分けるのかがカギ。外部設計は利用者と一緒に確認しながら進める必要があるため、利用者にも理解できる画面・帳票の形で仕様を固める。一方、プログラム内部のデータの持ち方や処理の分割方法は利用者には関係がなく、開発者だけが扱えればよい。両方を1つの工程でまとめて決めようとすると、利用者を巻き込むべき確認作業と技術的な作り込み作業が混ざり合い、利用者との合意形成が遅れてしまう。だから利用者が関与する外部設計と、開発者だけで進める内部設計を分ける。", "vs": "要件定義と外部設計の違いは『何を実現するか』と『それをどう見せるか』の違いであるのに対し、外部設計と内部設計の違いは『利用者から見えるか、見えないか』という別の軸である点。", "why_asked": "外部設計と内部設計は言葉が似ていて混同しやすく、『誰が確認する設計か(利用者か開発者だけか)』を軸に区別できるかが繰り返し問われる。", "opt": ["正解。外部設計は利用者から見える画面・帳票・操作方法などを設計する工程であり、内部設計はその内容を実現するためのプログラム内部の処理・構造を設計する工程である。『利用者から見えるか、見えないか』が境目になる。", "アルゴリズム・データ構造の設計と画面レイアウトの設計が入れ替わっている。画面レイアウトは外部設計側であり、逆になっている。", "単体テスト・受け入れテストはどちらも外部設計・内部設計とは別のテスト工程の内容であり、設計工程の説明としては誤り。", "『外部』『内部』という語感から契約や社内体制の話に読み替えているが、これは開発工程における外部設計・内部設計とは無関係な話である。"]}'),
  ('ap-core-q132', 'システム開発技術とソフトウェア開発管理技術',
   'システム開発において、設計や実装に着手する前に要件定義で利用者と開発側が要求内容を明確にし、合意を得ておく最大の目的として、最も適切なものはどれか。',
   NULL::text,
   '["開発が進んでから『実現したい内容が違う』という認識のずれが判明し、大きな手戻りが発生することを防ぐため。", "開発にかかる予算をできるだけ低く抑えるために、利用者側から出された要望をあらかじめ可能な限り削減しておくため。", "プログラムのコーディング規約をあらかじめ統一しておき、複数の開発者が同じ書き方でコードを書けるようにするため。", "開発チームに参加する要員をあらかじめ確定させ、各メンバーの作業分担表を作成しておくため。"]',
   0,
   '[0]',
   'single',
   '{"asked": "要件定義で最初に合意を取っておく目的を問う設問。", "point": "要件定義の目的は『後工程での手戻り(認識のずれによるやり直し)を防ぐこと』、と覚える。", "kid": "旅行に出発する前に、みんなで行き先とやりたいことを確認しておく作業。出発してから『実は違う場所に行きたかった』と気づくと、途中で予定を大きく変えなければならなくなる。", "eg": "料理を作り始める前に、注文する人と『和食か洋食か』『苦手な食材はあるか』を確認しておくようなもの。作り終えてから『実は苦手な食材が入っていた』と分かると、作り直しになり時間も材料も無駄になる。", "terms": [["要件定義", "利用者が実現したい内容を明らかにし、開発側と合意する工程"], ["手戻り", "後工程で問題が見つかり、前の工程からやり直すこと"], ["認識のずれ", "利用者が思い描く完成形と、開発側が理解した内容が食い違っている状態"]], "think": "なぜ最初に合意を取る必要があるのかがカギ。開発は要件定義から設計、実装、テストへと進むほど、それまでの工程の成果物の上に次の成果物を積み上げていく。もし要件定義の段階でのズレに気づかず設計・実装まで進めてしまうと、直すべき箇所が後工程の成果物全体に広がり、修正の手間が要件定義段階で直すときより大きく膨らむ。だから、まだ何も作り込んでいない最初の段階で、利用者と開発側の認識を文書として合わせておき、手戻りのコストを最小限に抑える。", "vs": "プロジェクトマネジメントにおける『プロジェクト憲章』との違いは、プロジェクト憲章がプロジェクトの実施そのものを承認し体制や予算の大枠を定めるのに対し、要件定義は開発するシステムの中身(何を実現するか)を定める点。", "why_asked": "要件定義を軽視して早く設計・実装に進みたくなる現場の心理につけ込む出題であり、要件定義の目的を『手戻り防止』という視点で正確に理解しているかが問われる。", "opt": ["正解。要件定義で利用者と開発側が要求内容を明確にし合意しておくのは、開発が進んだ後に認識のずれが判明して大きな手戻りが発生することを防ぐためである。", "要件定義の目的は要望を削減することではなく、実現したい内容を正確に明らかにして認識を合わせることである。予算抑制と目的をすり替えている。", "コーディング規約の統一は実装に関わる取り決めであり、要件定義の目的(利用者との認識合わせ)とは別の話である。", "要員配置や作業分担表の作成はプロジェクトマネジメントの活動であり、要件定義そのものの目的ではない。"]}'),
  ('ap-core-q133', 'システム開発技術とソフトウェア開発管理技術',
   'ソフトウェアライフサイクルプロセス(SLCP、共通フレーム)を制定する目的として、最も適切なものはどれか。',
   NULL::text,
   '["システムの企画から開発、運用、保守に至る各工程の作業を共通の用語・区分で整理し、発注者と開発者が同じ物差しで認識を合わせられるようにするため。", "すべての情報システム開発において、使用するプログラミング言語や開発ツール、実行環境をひとつの製品に統一することを全国一律に義務づけるため。", "システム開発にかかる費用をあらかじめ全国一律の金額表として固定しておき、発注者と開発者の双方が見積もりにかける手間を丸ごと省けるようにするため。", "開発チームに参加する人数や組織の体制そのものを業界共通の標準としてひとつに定め、企業ごとに異なる体制の違いを完全になくすため。"]',
   0,
   '[0]',
   'single',
   '{"asked": "SLCP(共通フレーム)を制定する目的を問う設問。", "point": "SLCP(共通フレーム)の目的は『開発に関わる人たちが同じ言葉・同じ区分で話せるようにする、共通の物差しを作ること』と覚える。", "kid": "発注する会社と作る会社が、それぞれ違う言葉で『設計』や『テスト』を語ると話がかみ合わない。共通フレームは、その言葉と区切り方を全国共通にした辞書のようなもの。", "eg": "国や地域によってメートル法とヤード・ポンド法が違うと寸法の情報が正しく伝わらないのと同じで、開発の世界でも会社ごとに工程の呼び方や区切り方がバラバラだと、契約書や見積もりで話が食い違う。共通フレームは、開発工程における共通の単位・区分を提供する。", "terms": [["SLCP", "Software Life Cycle Process。ソフトウェアの企画から廃棄までの一連の工程を体系化した考え方"], ["共通フレーム", "SLCPを日本国内向けに整備したガイドライン"], ["ライフサイクル", "ものが生まれてから役目を終えるまでの一連の過程"]], "think": "なぜ共通の区分が必要かがカギ。情報システム開発では、発注する側(利用者)と受注する側(開発者)が別々の組織であることが多く、それぞれが工程の呼び方や範囲を独自に使っていると、契約書に『設計まで』と書かれていてもどこまでを指すのか食い違ってしまう。この食い違いは、後になって『その作業は契約に含まれているのか』というトラブルの火種になる。共通フレームは、企画・要件定義・開発・運用・保守という共通の区分と、各区分で行うべき作業を明文化することで、契約や進捗報告の際に双方が同じ物差しで話せるようにし、認識のずれによるトラブルを防ぐ。", "vs": "要件定義と外部設計の違いが個々の工程内部の役割分担であるのに対し、SLCPはそれら個々の工程を包含する『開発全体の区分と呼び方の標準』である点で扱う階層が異なる。", "why_asked": "発注者・受注者間の認識のずれによる契約トラブルを防ぐための枠組みとして、SLCP・共通フレームの目的(標準化による認識合わせ)を正確に理解しているかが問われる。", "opt": ["正解。SLCP(共通フレーム)は、企画から運用・保守に至る各工程を共通の用語・区分で整理し、発注者と開発者が同じ物差しで認識を合わせられるようにするために制定されている。", "SLCPは工程の区分と作業内容を共通化するものであり、使用するプログラミング言語や開発ツールを一つに定めるものではない。", "SLCPは開発費用の金額を固定するものではなく、費用は個々のプロジェクトの規模・内容に応じて見積もられる。", "SLCPは開発の工程区分を共通化するものであり、開発チームの人数や組織体制を一つの標準に定めるものではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><marker id=\"ar1\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#60a5fa\"/></marker></defs>\n<text x=\"170\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" fill=\"#8892a4\" font-family=\"sans-serif\">SLCP(共通フレーム)の5プロセス</text>\n<g font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#e8eaf0\">\n<rect x=\"6\" y=\"60\" width=\"58\" height=\"38\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"35\" y=\"83\" text-anchor=\"middle\">企画</text>\n<rect x=\"76\" y=\"60\" width=\"58\" height=\"38\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"105\" y=\"83\" text-anchor=\"middle\">要件定義</text>\n<rect x=\"146\" y=\"60\" width=\"58\" height=\"38\" rx=\"5\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/>\n<text x=\"175\" y=\"83\" text-anchor=\"middle\">開発</text>\n<rect x=\"216\" y=\"60\" width=\"58\" height=\"38\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"245\" y=\"83\" text-anchor=\"middle\">運用</text>\n<rect x=\"286\" y=\"60\" width=\"48\" height=\"38\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"310\" y=\"83\" text-anchor=\"middle\">保守</text>\n</g>\n<line x1=\"64\" y1=\"79\" x2=\"74\" y2=\"79\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar1)\"/>\n<line x1=\"134\" y1=\"79\" x2=\"144\" y2=\"79\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar1)\"/>\n<line x1=\"204\" y1=\"79\" x2=\"214\" y2=\"79\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar1)\"/>\n<line x1=\"274\" y1=\"79\" x2=\"284\" y2=\"79\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar1)\"/>\n<text x=\"170\" y=\"125\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">共通の区分・用語で発注者と開発者の認識を合わせる</text>\n</svg>"}'),
  ('ap-core-q134', 'システム開発技術とソフトウェア開発管理技術',
   'SLCP(共通フレーム)における『企画プロセス』で行う作業として、最も適切なものはどれか。',
   NULL::text,
   '["経営上の課題やニーズを踏まえ、どのような情報システムを構築するかという方向性を定め、システム化の対象範囲や投資対効果を検討する。", "開発する個々のプログラムに適用するコーディング規約を細部まで定め、開発担当者をあらかじめ割り当てたうえで実装作業を直ちに開始する。", "すでに稼働を開始したシステムを日々運用し、障害が発生した際には原因を詳しく調査し関係者へ連絡を取りながら丁寧に復旧対応を行う。", "利用者からその都度寄せられた個々の要望を受けてプログラムを修正し、十分なテストを行ったうえで本番環境へ反映する。"]',
   0,
   '[0]',
   'single',
   '{"asked": "SLCPの企画プロセスで行う作業を問う設問。", "point": "企画プロセスは『そもそも何のためにシステムを作るのか』という方向性と投資対効果を検討する、一番上流の工程。", "kid": "家を建てる前に『そもそもなぜ家が必要か、予算はいくらまで出せるか』を考える段階。まだ間取りも決めていない。", "eg": "新しいお店を開くとき、内装や商品構成を決める前に『そもそもこの立地で商売として成り立つか、初期投資に見合う売上が見込めるか』を検討する段階に当たる。ここで検討せずにいきなり内装工事に進むと、後から採算が合わないと気づいても後戻りしにくい。", "terms": [["企画プロセス", "経営課題を踏まえシステム化の方向性・投資対効果を検討する、SLCPで最も上流の工程"], ["投資対効果", "投じた費用に対してどれだけの効果(利益・業務改善など)が見込めるかの尺度"], ["システム化構想", "企画プロセスで作成される、システム化の目的や範囲をまとめた文書"]], "think": "なぜ要件定義より前に企画プロセスが要るのかがカギ。要件定義は『システムで何を実現するか』を具体化する工程だが、その前提として『そもそもこのシステムに投資する価値があるか』を経営の視点で判断しておかないと、実現したい機能をいくら具体化しても、投資に見合わない無駄なシステムを作り込んでしまう危険がある。だから、要件を固める前に、経営課題・投資対効果を検討する企画プロセスを独立させて置く。", "vs": "要件定義プロセスとの違いは、企画プロセスが『システムに投資する価値があるか、何を目指すか』という経営視点の検討であるのに対し、要件定義プロセスは『具体的に何を実現するか』という機能・性能の検討である点。", "why_asked": "企画プロセスと要件定義プロセスの境界(経営視点か機能視点か)を混同させる出題が定番であり、SLCPの5工程それぞれが担う役割を正確に区別できるかが問われる。", "opt": ["正解。企画プロセスは、経営上の課題やニーズを踏まえてシステム化の方向性を定め、対象範囲や投資対効果を検討する、SLCPで最も上流の工程である。", "コーディング規約を定めて実装を始めるのは開発プロセスの作業であり、企画プロセスの説明ではない。", "稼働中のシステムの日々の運用や障害復旧対応は運用プロセスの作業であり、企画プロセスの説明ではない。", "利用者要望に応じた修正・テスト・本番反映は保守プロセスの作業であり、企画プロセスの説明ではない。"]}'),
  ('ap-core-q135', 'システム開発技術とソフトウェア開発管理技術',
   'SLCP(共通フレーム)における『要件定義プロセス』で行う作業として、最も適切なものはどれか。',
   NULL::text,
   '["企画プロセスで定めたシステム化の方向性をもとに、利用者から業務上の要求を聞き取り、システムが実現すべき機能や性能を明確にする。", "開発がすべて完了したシステムを本番環境へ切り替え、利用者に対して具体的な操作方法の教育をあらためて実施する。", "すでに定められた設計をもとにプログラムの詳細な処理手順を決め、実際にコーディングを行って実装していく。", "システムに投資する価値が本当にあるかどうかをあらためて経営層に詳しく説明し、システム化に必要な予算の承認を丁寧に得る作業を行う。"]',
   0,
   '[0]',
   'single',
   '{"asked": "SLCPの要件定義プロセスで行う作業を問う設問。", "point": "要件定義プロセスは『利用者の業務要求を聞き取り、システムが実現すべきことを明確にする』工程。まだプログラムは作らない。", "kid": "企画プロセスで『家を建てよう』と決まった後、実際に住む家族から『部屋数は何室欲しいか、駐車場は必要か』という具体的な希望を聞き取る段階。", "eg": "レストランの新メニュー開発で言えば、企画プロセスが『新メニューを出そう』という経営判断だとすると、要件定義プロセスは実際に『どんな味・価格帯・ボリュームの料理を求めているか』をお客様アンケートなどで具体的に聞き取る段階に当たる。まだ調理(実装)には入っていない。", "terms": [["要件定義プロセス", "利用者の業務要求を聞き取り、システムが実現すべき機能・性能を明確にする工程"], ["業務要求", "利用者が業務を遂行する上でシステムに求める内容"], ["機能要件", "システムが備えるべき具体的な機能に関する要求"]], "think": "なぜ企画プロセスと要件定義プロセスを分けて、要件定義プロセスでは具体的な聞き取りに徹するのかがカギ。企画プロセスの『投資する価値があるか』という経営判断と、『具体的に何を作るか』という現場の要求は、判断する立場も検討する粒度もまったく違う。この2つを1つの工程でまとめると、経営層は細かい機能要求まで判断を求められて意思決定が遅れ、逆に現場の要求整理が経営判断待ちで止まってしまう。だから、まず経営視点で『やるかどうか』を決める企画プロセスと、決まった後に現場視点で『何を実現するか』を詰める要件定義プロセスを分けて進める。", "vs": "企画プロセスとの違いは、企画プロセスが『投資する価値があるか』という経営判断であるのに対し、要件定義プロセスは『投資すると決まった後に、具体的に何を実現するか』という機能・性能の明確化である点。", "why_asked": "企画・要件定義・開発という隣接するSLCPプロセスの境界を混同させる出題であり、各プロセスが『誰の視点で』『何を確定させるか』を正確に区別できるかが問われる。", "opt": ["正解。要件定義プロセスは、企画プロセスで定めた方向性をもとに、利用者から業務上の要求を聞き取り、システムが実現すべき機能や性能を明確にする工程である。", "本番環境への切り替えや操作教育は運用プロセス側の作業であり、要件定義プロセスの説明ではない。", "詳細な処理手順の設計とコーディングは開発プロセスの作業であり、要件定義プロセスの説明ではない。", "投資対効果を経営層に説明し予算承認を得るのは企画プロセスの作業であり、要件定義プロセスの説明ではない。"]}'),
  ('ap-core-q136', 'システム開発技術とソフトウェア開発管理技術',
   'ソフトウェア開発における構成管理の目的として、最も適切なものはどれか。',
   NULL::text,
   '["プログラムや文書などの成果物について、いつ、誰が、どの版をどのように変更したかを管理し、必要なときに正しい版を特定・復元できるようにする。", "開発チームに所属する各メンバーがそれぞれ休暇を取得する日程を細かく一元的に管理し、要員全体の稼働状況をいつでもすぐに随時把握できるようにする。", "システムが本番環境の中で実際に稼働している時間の割合を継続的に記録し、可用性の目標を達成できているかを確認する。", "開発プロジェクト全体で実際にかかった費用の実績を記録し、あらかじめ定めた予算と比較して超過していないかを確認する。"]',
   0,
   '[0]',
   'single',
   '{"asked": "構成管理の目的を問う設問。", "point": "構成管理は『成果物のどの版が、いつ、誰によって作られたか』を追跡・復元できるようにする管理。", "kid": "文書やプログラムの『版(バージョン)』を、いつ誰が更新したか分かる形で保管しておく仕組み。", "eg": "レポートを書くとき、書き直すたびに『下書き1』『下書き2』『最終版』とファイル名と日付を残しておけば、あとで『前のバージョンに戻したい』となっても迷わず戻せる。構成管理は、これをプログラムや設計書という開発の成果物すべてに対して組織的に行う仕組み。", "terms": [["構成管理", "成果物の版・変更履歴を管理し、必要な版を特定・復元できるようにする活動"], ["構成識別", "管理対象の成果物とその版を一意に特定できるようにすること"], ["バージョン管理", "プログラムや文書の変更履歴を版として記録・追跡する仕組み"]], "think": "なぜ構成管理が必要なのかがカギ。開発では複数の担当者が同じプログラムや文書を何度も修正していく。もし『誰が、いつ、何を変更したか』を記録せずに上書きだけしていくと、ある日不具合が発生したときに『どの変更が原因か』を突き止められず、原因追跡に膨大な時間がかかる。さらに、直したはずの変更がかえって別の不具合を生んだ場合、『変更前の状態に戻す』こともできなくなる。構成管理は、成果物の版とその変更履歴を管理することで、原因追跡と過去バージョンへの復元を可能にし、開発全体の品質と信頼性を支える。", "vs": "変更管理との違いは、構成管理が『成果物の版を記録・管理する仕組みそのもの』であるのに対し、変更管理は『その版を変更してよいかどうかを判断し承認する手続き』である点。両者は密接に関わるが、管理の対象が異なる。", "why_asked": "構成管理と変更管理、あるいはコスト管理・要員管理との境界を混同させる出題が定番であり、構成管理が『何を管理する活動か』を正確に理解しているかが問われる。", "opt": ["正解。構成管理は、成果物についていつ・誰が・どの版をどう変更したかを管理し、必要なときに正しい版を特定・復元できるようにするための活動である。", "休暇日程や要員の稼働状況の管理は要員管理の話であり、構成管理の目的ではない。", "稼働時間の割合を記録して可用性目標を確認するのはサービスマネジメントにおける可用性管理の話であり、構成管理の目的ではない。", "費用実績と予算の比較はコスト管理の話であり、構成管理の目的ではない。"]}'),
  ('ap-core-q137', 'システム開発技術とソフトウェア開発管理技術',
   '構成管理における『構成識別』の説明として、最も適切なものはどれか。',
   NULL::text,
   '["管理対象とする成果物(プログラム、設計書など)とその版を、他と混同しないように一意の名称や番号で特定できるようにすること。", "完成したプログラムを本番環境へあらためて実際に配置し、利用者が日々の業務の中で問題なく使える状態に整えること。", "開発したプログラムに欠陥がないかどうかを様々な観点から何度も繰り返しテストし、品質を確認すること。", "変更要求として社内の関係者から挙がってきた内容をあらためて慎重に審査し、実施してよいかどうかを責任者が最終的に承認すること。"]',
   0,
   '[0]',
   'single',
   '{"asked": "構成管理における構成識別の説明を問う設問。", "point": "構成識別は『どの成果物のどの版か』を一意に特定できるようにする、構成管理の土台となる作業。", "kid": "本棚の本1冊1冊に、タイトルと版数(第1版、第2版...)が書かれたラベルを貼って、他の本と取り違えないようにする作業。", "eg": "図書館で同じタイトルの本でも改訂版が何冊もあるとき、背表紙に『第3版』と明記されていなければ、借りたい版を正確に指定できない。構成識別は、開発の成果物1つ1つに『これは設計書のバージョン2.1』というラベルを貼り、後から誰でも同じものを正確に指し示せるようにする作業。", "terms": [["構成識別", "成果物とその版を一意に特定できるようにすること"], ["構成品目", "構成管理の対象として識別された成果物の単位"], ["版数(バージョン番号)", "成果物の変更履歴を示すために付ける番号"]], "think": "なぜ構成識別が構成管理の出発点になるのかがカギ。『いつ、誰が、どこを変更したか』を記録しようとしても、そもそも『どの成果物のどの版の話をしているか』を一意に特定できなければ、記録自体が何を指しているか分からなくなる。構成識別で成果物と版に一意の名前・番号を付けておくことで、初めて変更履歴の記録や、過去の版への復元が正確に行えるようになる。", "vs": "変更管理との違いは、構成識別が『成果物と版をラベル付けして特定できるようにする作業』であるのに対し、変更管理は『そのラベル付けされた成果物を変更してよいか判断・承認する手続き』である点。", "why_asked": "構成管理の下位活動である構成識別を、品質管理やリリース作業など隣接する活動と混同させる出題であり、構成管理全体の中で構成識別が担う役割(土台となる特定作業)を理解しているかが問われる。", "opt": ["正解。構成識別は、管理対象の成果物とその版を、他と混同しないように一意の名称・番号で特定できるようにする作業であり、構成管理の土台となる。", "本番環境への配置(リリース)は構成識別とは別の作業であり、成果物を一意に特定する話ではない。", "欠陥の有無をテストして品質を確認するのは品質管理の活動であり、構成識別の説明ではない。", "変更要求の審査・承認は変更管理の活動であり、構成識別の説明ではない。"]}'),
  ('ap-core-q138', 'システム開発技術とソフトウェア開発管理技術',
   'ソフトウェア開発において、成果物への変更を無秩序に許さず、変更管理のプロセスを経て承認された変更だけを反映するようにする目的として、最も適切なものはどれか。',
   NULL::text,
   '["変更が他の機能や関係者に与える影響を事前に評価し、意図しない不具合や関係者間の認識のずれを防いだ上で反映するため。", "変更作業に関わる担当者の人数をできるだけ絞り込み、開発プロジェクト全体にかかる人件費を削減するため。", "変更した内容をどの関係者にも一切秘密にしておくことで、競合他社に自社システムの仕様を絶対に知られないようにするため。", "変更履歴をすべて詳細に記録しておき、開発者一人ひとりの作業時間を正確に測定して人事評価に用いるため。"]',
   0,
   '[0]',
   'single',
   '{"asked": "変更管理のプロセスを設ける目的を問う設問。", "point": "変更管理の目的は『変更の影響を事前に評価してから反映し、不具合や認識のずれを防ぐこと』。", "kid": "誰でも自由に設計図を書き換えられる状態だと、ある人が直した内容が他の人の担当箇所と食い違って、あとで組み立てられなくなる。それを防ぐために、変更する前に『この変更は問題ないか』を確認する仕組み。", "eg": "マンションの部屋を勝手にリフォームして壁を取り払ってしまうと、その壁が実は建物全体を支える構造壁だった場合、建物全体が傾く危険がある。変更管理は、リフォームする前に『この壁は取り払っても安全か』を専門家に確認させる仕組みに当たる。", "terms": [["変更管理", "変更要求の影響を評価し、承認された変更だけを反映する手続き"], ["影響範囲", "ある変更が他の機能や成果物に及ぼす可能性のある範囲"], ["変更要求", "成果物の変更を求める依頼"]], "think": "なぜ変更を無秩序に許すと問題が起きるのかがカギ。プログラムや設計書は互いに関連し合っており、ある一箇所を直すと、それを利用している別の箇所にも影響が及ぶことがある。もし誰でも思いついたときに自由に変更を反映してよいとすると、変更した本人は気づいていない影響範囲で不具合が発生したり、他の担当者が把握していないうちに仕様が変わってしまい、関係者間で認識がずれたりする。変更管理は、変更を反映する前に影響範囲を評価し、責任者が承認したものだけを反映する手続きを設けることで、こうした意図しない不具合や認識のずれを未然に防ぐ。", "vs": "構成管理との違いは、構成管理が『成果物の版を記録・追跡する仕組み』であるのに対し、変更管理は『その版を変更してよいかどうかを事前に審査・承認する手続き』である点。", "why_asked": "なぜ変更管理という手続きが必要かという動機(無秩序な変更が引き起こす具体的な問題)を理解しているかが問われる。コスト削減やセキュリティなど別の目的にすり替えた誤答に注意。", "opt": ["正解。変更管理のプロセスを経て承認された変更だけを反映するのは、変更が他の機能や関係者に与える影響を事前に評価し、意図しない不具合や認識のずれを防ぐためである。", "変更管理の目的は影響評価と承認による不具合防止であり、担当者数の削減による人件費の抑制ではない。", "変更管理は変更内容を秘密にすることを目的とするものではなく、情報セキュリティ上の秘密保持とは別の話である。", "変更履歴の記録は変更管理の一部だが、目的は作業時間の測定・評価ではなく、影響評価と承認による不具合防止である。"]}'),
  ('ap-core-q139', 'システム開発技術とソフトウェア開発管理技術',
   '変更管理プロセスにおいて、変更要求を受け付けてから成果物に反映するまでの手順として、最も適切なものはどれか。',
   NULL::text,
   '["変更要求を受け付け、変更が及ぼす影響範囲を評価した上で、責任者の承認を得てから成果物に変更を反映する。", "変更要求を受け付けたら、影響評価や承認を経ずに直ちに成果物へ反映し、問題が起きた場合にのみ事後に評価する。", "変更要求を受け付けたら、まず新しいバージョンの成果物を作成して公開し、その後に元の変更要求の内容を関係者へ周知する。", "変更要求を受け付けたら、まず開発費用を再見積もりして予算の承認を得てから、影響評価を行う。"]',
   0,
   '[0]',
   'single',
   '{"asked": "変更管理プロセスの正しい手順を問う設問。", "point": "変更管理の手順は『要求受付→影響評価→承認→反映』の順。評価や承認を飛ばして先に反映してはいけない。", "kid": "『直したい』という声が上がったら、まず『直しても大丈夫か』を確かめてから、OKが出て初めて実際に直す、という順番を守る話。", "eg": "病院で薬を変更するとき、患者が『薬を変えたい』と言っても、医師はまず他の薬との飲み合わせ(影響)を確認し、問題なければ処方箋を出す(承認)、それから薬局で薬を渡す(反映)という順番を踏む。いきなり薬を渡してから飲み合わせを確認するようなことはしない。", "terms": [["影響評価", "変更が他の機能や関係者に及ぼす範囲をあらかじめ確認すること"], ["承認", "責任者が変更を実施してよいと判断すること"], ["反映", "承認された変更を実際に成果物へ適用すること"]], "think": "なぜこの順番でなければならないのかがカギ。影響評価を反映のあとに回してしまうと、すでに問題のある変更が成果物に取り込まれた状態になっており、評価で問題が見つかっても『なかったことにする』ための後始末が必要になる。先に影響を評価し、責任者の承認を得てから反映することで、問題のある変更が成果物に入り込む前の段階で止められる。この『取り込む前に止められるかどうか』が、事前評価と事後確認の決定的な違いであり、変更管理が手順の順序にこだわる理由である。", "vs": "構成識別との違いは、構成識別が『成果物と版を特定するための準備作業』であるのに対し、変更管理プロセスは『特定された成果物に対する変更を審査し反映するまでの一連の手続き』である点。", "why_asked": "変更管理の手順を『評価・承認が先、反映が後』という正しい順序で理解しているかが問われる。順序を入れ替えた誤答は、実務でも起きがちな危険な運用のパターンとして出題される。", "opt": ["正解。変更管理プロセスは、変更要求を受け付け、影響範囲を評価した上で責任者の承認を得てから成果物に反映する、という順序で進める。", "影響評価や承認を経ずに先に反映してしまうと、問題のある変更が既に成果物に取り込まれた状態になり、事後の評価では手遅れになりかねない。順序が逆である。", "先に新しい版を公開してから変更内容を周知するのは、影響評価・承認を飛ばして反映を先行させている点で誤りであり、順序が逆である。", "費用の再見積もりを影響評価より先に置くと、変更が及ぼす技術的な影響を確認しないまま予算判断をすることになり、順序として適切でない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><marker id=\"ar3\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\"><path d=\"M0 0L10 5L0 10z\" fill=\"#60a5fa\"/></marker></defs>\n<g font-family=\"sans-serif\" font-size=\"10.5\" fill=\"#e8eaf0\">\n<rect x=\"6\" y=\"55\" width=\"72\" height=\"42\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"42\" y=\"80\" text-anchor=\"middle\">変更要求</text>\n<rect x=\"90\" y=\"55\" width=\"72\" height=\"42\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/>\n<text x=\"126\" y=\"80\" text-anchor=\"middle\">影響評価</text>\n<rect x=\"174\" y=\"55\" width=\"72\" height=\"42\" rx=\"5\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.8\"/>\n<text x=\"210\" y=\"80\" text-anchor=\"middle\">承認</text>\n<rect x=\"258\" y=\"55\" width=\"76\" height=\"42\" rx=\"5\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.8\"/>\n<text x=\"296\" y=\"80\" text-anchor=\"middle\">反映</text>\n</g>\n<line x1=\"78\" y1=\"76\" x2=\"88\" y2=\"76\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar3)\"/>\n<line x1=\"162\" y1=\"76\" x2=\"172\" y2=\"76\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar3)\"/>\n<line x1=\"246\" y1=\"76\" x2=\"256\" y2=\"76\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#ar3)\"/>\n<text x=\"170\" y=\"125\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\" font-family=\"sans-serif\">評価・承認を経ないまま反映すると、問題を取り込んでから気づく</text>\n</svg>"}'),
  ('ap-core-q140', 'システム開発技術とソフトウェア開発管理技術',
   'プログラムの著作権に関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["プログラムの具体的なソースコードの表現は著作権法で保護されるが、プログラムが用いているアルゴリズムそのものは著作権の保護対象とならない。", "プログラムが用いているアルゴリズムは著作権法によって保護されるが、具体的なソースコードの書き方そのものは、著作権の保護対象とはならない。", "プログラムを著作権法によって保護してもらうには、あらかじめ特許庁へ出願し、専門の審査を経て登録される必要がある。", "プログラムの著作権は、公開されてから10年が経過した時点で自動的に消滅してしまい、それ以後は誰でも自由に利用できるようになる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "プログラムの著作権が何を保護するかを問う設問。", "point": "著作権が保護するのは『具体的な書き方(表現)』であって、その裏にある『考え方(アルゴリズム)』ではない、と覚える。", "kid": "同じレシピのアイデア(アルゴリズム)を使っていても、実際に書いた文章(ソースコード)が違えば、それぞれ別の著作物として保護される。", "eg": "料理のレシピで言えば、『材料をこの順番で炒める』という調理の考え方(アイデア)そのものは誰でも使えるが、そのレシピを説明する具体的な文章表現をそのまま丸ごとコピーして自分のレシピ本に載せるのは著作権侵害になる。プログラムの著作権も同じで、アルゴリズムという考え方ではなく、ソースコードという表現を保護する。", "terms": [["著作権", "文章・プログラムなどの具体的な表現を保護する権利。創作した時点で自動的に発生する"], ["アルゴリズム", "問題を解決するための手順・考え方"], ["ソースコード", "プログラムの具体的な記述(表現)"]], "think": "なぜアルゴリズムではなく表現だけを保護するのかがカギ。もしアルゴリズム(考え方)そのものを著作権で保護してしまうと、同じ目的を達成する別の書き方のプログラムまで作れなくなり、後続の開発者が同種のアイデアを使ったソフトウェアを一切作れなくなってしまう。それでは技術の発展を妨げる。著作権法は、誰でも同じアイデアを使えるようにしたまま、他人が書いた具体的な文章(コード)をそのまま盗用することだけを禁じることで、模倣は防ぎつつアイデアの自由な利用は妨げないというバランスを取っている。なお、出願や登録の手続きは不要で、プログラムを作成した時点で自動的に著作権が発生する。", "vs": "特許権との違いは、著作権が『具体的な表現』を出願・登録なしに作成時点から自動的に保護するのに対し、特許権は『発明のアイデアそのもの』を特許庁への出願・審査・登録を経て初めて保護する点。", "why_asked": "著作権と特許権のどちらが『アイデア』を保護し、どちらが『表現』を保護するかを混同させる出題が定番であり、両者の保護対象の違いを正確に理解しているかが問われる。", "opt": ["正解。著作権法が保護するのは具体的なソースコードの表現であり、プログラムが用いているアルゴリズム(考え方)そのものは保護対象とならない。", "保護対象が逆になっている。著作権法が保護するのは具体的なソースコードの表現であり、アルゴリズムそのものではない。", "著作権は特許のような出願・審査・登録の手続きを必要とせず、プログラムを創作した時点で自動的に発生する。", "著作権の保護期間は10年ではなく、より長期にわたって存続する。存続期間を短く誤って述べている。"]}'),
  ('ap-core-q141', 'システム開発技術とソフトウェア開発管理技術',
   '特許権と著作権の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["特許権は技術的なアイデア(発明)を保護し、出願と審査を経て登録されることで権利が発生するのに対し、著作権は具体的な表現を保護し、創作した時点で手続き不要に権利が発生する。", "特許権も著作権も、権利の発生にはどちらも特許庁への出願と厳格な審査が必要であり、いずれも登録が完了した時点で初めて権利が発生するという点で共通している。", "特許権は文章や絵画、音楽などの具体的な表現を保護する権利であり、著作権は自然法則を利用した技術的なアイデアそのものを保護する権利である、という実際とは逆になった関係にある。", "特許権も著作権も、権利の存続期間はどちらも出願の日から一律20年と法律で定められており、保護期間の長さという面で両者に実質的な違いは存在しない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "特許権と著作権の違いを問う設問。", "point": "特許権は『出願・審査を経て、アイデア(発明)』を保護し、著作権は『手続き不要で、表現』を保護する、という2つの軸(手続きの有無×保護対象)で見分ける。", "kid": "特許は『新しい発明のアイデア』を国に届け出て認めてもらう仕組み、著作権は『作った瞬間に自動でついてくる』表現の権利。", "eg": "新しい調理器具そのものの仕組み(発明)を独占的に使いたければ特許を出願して審査を受ける必要があるが、自分で書いたレシピ本の文章は、書き上げた瞬間から著作権で守られており、役所に届け出る必要はない。", "terms": [["特許権", "自然法則を利用した技術的な発明を保護する権利。出願・審査を経て発生"], ["著作権", "文章・プログラムなどの具体的な表現を保護する権利。創作時点で自動発生"], ["無方式主義", "著作権のように、登録などの手続きなしに権利が発生する考え方"]], "think": "なぜ特許権だけ出願・審査という手続きが必要なのかがカギ。特許権は『同じアイデアを他人が使えなくする』という強い独占権を発明者に与える制度であり、既に世の中に存在する技術と本当に違う新しいアイデアなのかを審査機関が事前に確認しないと、誰でも簡単に既存の技術を独占できてしまい、技術の発展を妨げてしまう。一方、著作権が保護する『表現』は、同じアイデアからでも人によって書き方が自然と変わるため、他人の自由な表現活動を妨げにくく、審査なしに創作時点で権利を与えても弊害が小さい。この違いが、特許権には審査という手続きがあり、著作権には無い理由になっている。", "vs": "前問の著作権との違いは、保護対象(アイデアか表現か)と、権利発生の手続き(審査が要るか要らないか)という2軸で整理できる点。", "why_asked": "特許権と著作権を『保護対象』『権利発生の手続き』という2つの軸で正確に区別できるかが問われる。存続期間や発生要件を混同した誤答に注意。", "opt": ["正解。特許権は技術的な発明を保護し出願・審査・登録を経て権利が発生するのに対し、著作権は具体的な表現を保護し、創作した時点で手続き不要に権利が発生する。", "著作権には特許のような出願・審査は不要であり、創作した時点で自動的に権利が発生する。共通しているという説明は誤り。", "保護対象が逆になっている。表現を保護するのは著作権であり、技術的なアイデアを保護するのは特許権である。", "特許権の存続期間は出願から一定期間(原則20年)だが、著作権の保護期間はそれとは異なる考え方(公表・創作を起点とした長期の期間)で定められており、一律20年で共通しているという説明は誤り。"]}'),
  ('ap-core-q142', 'システム開発技術とソフトウェア開発管理技術',
   '音楽や映像、ソフトウェアなどのコンテンツに施される、コピーガードやDRM(デジタル著作権管理)といった技術的保護手段の目的として、最も適切なものはどれか。',
   NULL::text,
   '["著作権法による権利保護を補うために、技術的な仕組みでコンテンツの無断複製や不正な利用を制限すること。", "コンテンツの著作権そのものを、法律上の権利ではなく技術的な仕組みに完全に置き換えて発生させること。", "コンテンツを強力に暗号化することで、正規に購入した利用者であっても一切再生できないようにすること。", "コンテンツの制作者を特定できないようにするため、作品に含まれる作者情報をすべて完全に匿名化すること。"]',
   0,
   '[0]',
   'single',
   '{"asked": "技術的保護手段(コピーガード・DRM)の目的を問う設問。", "point": "技術的保護手段(コピーガード・DRM)は、著作権という『法律の権利』を、技術の力で『実際に複製・利用しにくくする』ことで補う仕組み。", "kid": "法律で『無断コピーはダメ』と決まっていても、実際にコピーできてしまえば止められない人もいる。DRMは、そもそも技術的にコピーしにくくしてしまう鍵のようなもの。", "eg": "自転車に『盗まないでください』という張り紙をするだけでなく、実際に鍵をかけて物理的に持ち去りにくくするようなもの。著作権法という『張り紙(ルール)』に加えて、DRMという『鍵(技術)』で二重に守る。", "terms": [["DRM", "Digital Rights Management。デジタルコンテンツの複製・利用を技術的に制限する仕組み"], ["コピーガード", "記録媒体やデータの複製を技術的に防止する仕組み"], ["技術的保護手段", "著作権法上の権利を技術的に裏付け、無断複製・利用を制限する手段"]], "think": "なぜ法律による保護だけでなく技術的な保護手段も必要なのかがカギ。著作権法は『無断複製は違法である』というルールを定めるが、ルールがあっても複製そのものを技術的に止める力はなく、違反が起きてから権利者が訴えるという事後対応にとどまる。デジタルコンテンツは複製が容易で、いったん不正コピーが出回ってしまうと被害の回復が難しい。そこで、複製や再生を技術的に制限するコピーガードやDRMを併用することで、そもそも不正な複製が起きにくい状態を作り、法律による事後対応だけに頼らずに済むようにする。", "vs": "著作権(法律上の権利)との違いは、著作権が『無断複製を違法とするルール』であるのに対し、技術的保護手段は『そのルールを実際に複製しにくい形で技術的に裏付ける仕組み』である点。両者は補い合う関係にある。", "why_asked": "技術的保護手段が『法律上の権利発生』とどう違うか、また『正規利用者の利用まで妨げるものではない』という点を正確に理解しているかが問われる。", "opt": ["正解。コピーガードやDRMといった技術的保護手段は、著作権法による権利保護を補うために、技術的な仕組みで無断複製や不正利用を制限することを目的としている。", "著作権は創作した時点で法律上自動的に発生するものであり、技術的保護手段はその発生要件を置き換えるものではない。", "技術的保護手段は無断複製・不正利用を制限するためのものであり、正規に購入した利用者の再生まで妨げることは目的ではない。", "作者情報の匿名化は技術的保護手段の目的とは無関係であり、無断複製・不正利用の制限という本来の目的とは異なる話にすり替えている。"]}'),
  ('ap-core-q143', 'システム開発技術とソフトウェア開発管理技術',
   '自社で開発したプログラムのソースコードを、特許や著作権による保護に加えて『営業秘密』として管理することの意義として、最も適切なものはどれか。',
   NULL::text,
   '["公にしていない独自のノウハウを秘密として管理しておくことで、特許のように内容を公開せずに、不正取得や漏えいがあった場合には不正競争防止法による保護を受けられるようにする。", "営業秘密として管理を始めてしまうと、以後は著作権法や特許法による保護を一切受けられなくなってしまい、法的な保護の手段は営業秘密のみに一本化される。", "営業秘密として管理する本来の目的は、ソースコードを社内の誰もが自由に閲覧・複製できる状態にしておき、社内全体でのあらゆる情報共有を積極的かつ継続的に強く促進することにある。", "営業秘密として厳重に管理してさえいれば、プログラムを無断で使用した第三者に対しても、特許権とまったく同等の強い独占的な実施権をいつでも法的に主張できるようになる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "ソースコードを営業秘密として管理する意義を問う設問。", "point": "営業秘密は『特許のように公開せず、秘密のまま』にしておき、不正取得・漏えいがあったときに法律で守ってもらう管理の考え方。", "kid": "レシピを特許庁に届け出て公開する代わりに、『企業秘密』として社内だけで厳重に保管し、盗まれたときだけ法律で守ってもらう方法。", "eg": "有名な清涼飲料水の配合レシピは、特許を取らずに『企業秘密』として厳重に管理されていると言われる。特許を取ると内容を公開しなければならず、期限が来れば誰でも使えるようになってしまうが、秘密のまま管理すれば公開されず、盗まれない限りは半永久的に独自のノウハウを守れる。", "terms": [["営業秘密", "秘密として管理され、事業活動に有用で、公然と知られていない情報。不正競争防止法で保護される"], ["不正競争防止法", "営業秘密の不正取得・使用・開示などを禁じる法律"], ["知的財産", "発明・著作物・ノウハウなど、人間の創造的活動によって生み出された財産的価値のある情報"]], "think": "なぜ特許を取らずに営業秘密として管理するという選択肢があるのかがカギ。特許権は強力な独占権を得られる代わりに、出願時に発明の内容を特許庁に公開しなければならず、しかも保護期間が出願から一定年数と定められている。技術の中には、公開してしまうと模倣のヒントを与えてしまうものや、特許の保護期間より長く独自性を守りたいものもある。そうした場合、あえて特許を取らず、秘密として厳重に管理する道を選ぶことで、内容を公開せずに済み、保護期間の制限も受けない。ただし、この方法は『秘密として管理されている』ことが法律上の保護を受ける条件になるため、社外秘であることが分かるように管理していない情報は保護されない。", "vs": "特許権との違いは、特許権が『内容を公開する代わりに強い独占権を得る』制度であるのに対し、営業秘密は『内容を公開しない代わりに、秘密管理されていることを条件に不正取得・漏えいから保護される』という異なる考え方である点。", "why_asked": "特許・著作権・営業秘密という複数の知的財産保護の手段を、それぞれの特徴(公開するか、独占権の強さ、保護期間)で使い分けられるかが問われる。", "opt": ["正解。営業秘密として管理することの意義は、独自のノウハウを特許のように公開せずに秘密のまま保ち、不正取得や漏えいがあった場合には不正競争防止法による保護を受けられるようにすることである。", "営業秘密として管理していても、要件を満たせば著作権法・特許法による保護と併存し得る。一切受けられなくなるという説明は誤り。", "営業秘密の管理は秘密として保つことが前提であり、社内の誰もが自由に閲覧・複製できる状態にすることは、秘密管理の趣旨と正反対である。", "営業秘密として管理しても、特許権のような独占的な実施権(誰にも使わせない権利)を第三者に主張できるわけではなく、不正競争防止法による不正取得・使用への対応にとどまる。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q144', '通信に関する理論', 'なぜツイストペアケーブルは、2本の銅線をらせん状に撚り合わせた構造になっているか。その理由として最も適切なものはどれか。', NULL::text, '["2本の線に外から同じように乗る電磁ノイズを、受信側で2本の信号の差を取ることによって打ち消しやすくするため", "2本の銅線をそれぞれ別の被覆で包むことで銅の使用量を減らし、ケーブル1本あたりの重さを軽くするため", "銅線どうしの間隔を一定に保つことで、信号が伝わる速さを光ファイバーケーブルと同じ速さまで引き上げるため", "2本の銅線をそれぞれ別の周波数帯に対応させ、1本のケーブルの中で複数の通信を分けて流せるようにするため"]'::jsonb, 0, '[0]', 'single', '{"asked": "ツイストペアケーブルを2本の線が撚り合わさった構造にしている理由を問う設問。", "point": "2本を撚ることで外来ノイズを両方の線にほぼ同じ量だけ乗せ、差を取って打ち消せる。これが「撚る」ことの目的。", "kid": "2本の線を編んでおくと、外から入ってくるノイズが両方の線にほぼ同じだけ乗る。受信側は「2本の差」だけを見るので、同じ分だけ乗ったノイズは差し引きゼロになって消える。", "eg": "2人の証言を突き合わせて共通の勘違いを取り除くようなもの。2人が同じ思い込みで同じ間違いをしていれば、その部分は「共通の誤り」として見抜いて除ける。", "terms": [["ツイストペアケーブル", "2本の銅線を撚り合わせた通信ケーブル。LANケーブルなどに使われる"], ["電磁ノイズ", "近くの電気機器や電線から漏れて信号に混じる、不要な電気的な乱れ"], ["差動伝送", "2本の線の電圧の「差」を信号として使う伝送方式"]], "think": "なぜ撚ることでノイズを打ち消せるのかがカギ。電磁ノイズは空間を伝わって近くの導線に等しく影響を与える。2本の線をまっすぐ並べただけだと、ノイズ源からの距離がわずかに違うため乗るノイズの量も微妙にずれてしまう。撚り合わせることで2本の線がノイズ源からの距離を交互に入れ替わりながら進むため、区間ごとに乗るノイズの平均量がほぼ等しくなる。受信側は2本の電圧の「差」だけを信号として読み取るので、両方の線にほぼ同じ量だけ乗ったノイズは差し引きゼロになって消え、信号本体だけが残る。", "why_asked": "「撚ってあるから曲げやすい」のような構造上の副次効果と、本来の電気的な目的(ノイズ打ち消し)を混同させる出題が多い。", "vs": "光ファイバーケーブルは光信号を使うため、そもそも電磁ノイズの影響を受けにくい。ツイストペアの撚り構造は電気信号ならではの対策である点が異なる。", "opt": ["正解。2本の線に外から同じように乗る電磁ノイズを、受信側で2本の信号の差を取ることによって打ち消しやすくするため。", "撚り合わせても銅線の使用量そのものは変わらず、軽量化が目的ではない。", "撚り合わせる構造は伝送速度を光の速さに近づける効果を持たない。", "複数の通信を周波数ごとに分けて流すのは多重化の役割であり、撚り構造とは別の技術である。"]}'),
  ('ap-core-q145', '通信に関する理論', 'ツイストペアケーブルと比較した光ファイバーケーブルの特徴として、最も適切なものはどれか。', NULL::text, '["電気信号ではなく光信号で伝送するため電磁ノイズの影響を受けにくく、長距離・大容量の伝送に向く", "電気を通す金属を使わないため、ケーブル自体の製造コストが常にツイストペアケーブルより安くなる", "信号を光に変換する処理が不要なため、送受信の仕組みがツイストペアケーブルより単純になる", "電波を使って通信する無線伝送路の一種であり、ケーブルの敷設工事が不要になる"]'::jsonb, 0, '[0]', 'single', '{"asked": "ツイストペアケーブルとの比較で、光ファイバーケーブルの技術的な特徴を問う設問。", "point": "「光信号だから電磁ノイズに強い」「だから長距離・大容量に向く」という因果が光ファイバーの核心。", "kid": "光ファイバーは電気ではなく光の点滅で0と1を表す。光は電気と違って周りの電磁ノイズに反応しないので、遠くまで乱れずに届けやすい。", "eg": "懐中電灯の光で合図を送るようなもの。近くで携帯電話やモーターが動いていても、光の点滅そのものが電気的な影響を受けて乱れることはない。", "terms": [["光ファイバーケーブル", "ガラスやプラスチックの繊維の中に光を通して信号を伝えるケーブル"], ["電磁ノイズ", "電気機器や電線から漏れて信号に混じる電気的な乱れ"]], "think": "なぜ光信号は電磁ノイズの影響を受けにくいのかがカギ。電磁ノイズは電気的な乱れであり、金属の導線を伝わる電気信号にはそのまま混じり込みやすい。光ファイバーは情報を電気ではなく光の点滅として伝えるため、周囲の電磁的な乱れが信号そのものに直接影響することがない。この性質のおかげで、長い距離を伝送しても信号が乱れにくく、高速で大量のデータを安定して送る長距離・大容量伝送に向いている。", "why_asked": "「ケーブルの値段」や「工事の要不要」など、電磁ノイズ耐性とは無関係な副次的な話とすり替えて誤答に誘導する出題が多い。", "vs": "ツイストペアケーブルは電気信号を撚り構造でノイズ対策するのに対し、光ファイバーケーブルはそもそも電気を使わないためノイズの影響を受けにくいという、対策の次元そのものが異なる。", "opt": ["正解。電気信号ではなく光信号で伝送するため電磁ノイズの影響を受けにくく、長距離・大容量の伝送に向く。", "光ファイバーは素材や加工の面でツイストペアケーブルより製造コストが高くなりやすく、「常に安い」とはいえない。", "光ファイバーは電気信号を光信号に変換する送受信機器が必要であり、仕組みが単純になるわけではない。", "光ファイバーケーブルは有線伝送路であり、電波を使う無線伝送路ではない。敷設工事も必要になる。"]}'),
  ('ap-core-q146', '通信に関する理論', 'コンピュータが扱うデジタル信号(0と1)を、電話回線のようなアナログの伝送路にそのまま送るのではなく、搬送波と呼ばれるアナログの波に乗せる「変調」という処理を行うのはなぜか。最も適切なものはどれか。', NULL::text, '["電話回線のような伝送路は特定の周波数帯域の連続的な波を伝えるように作られており、方形波のままのデジタル信号は減衰やひずみが大きく長距離を安定して伝わりにくいため", "デジタル信号は0と1の2値でしか状態を表現できず、そのままでは電話回線が伝送できる情報の種類として不足してしまうため、より多くの状態を表現できるアナログ信号に変換する必要があるため", "アナログ信号のほうがデジタル信号より常に高速に伝送でき、同じ伝送路であればアナログ方式に変換したほうが単位時間あたりに送れる情報量が必ず増えるため", "変調しない信号は伝送路上で誰でも内容を読み取れてしまうおそれがあるため、変調によって信号の内容そのものを秘匿し、第三者に読み取られないようにする必要があるため"]'::jsonb, 0, '[0]', 'single', '{"asked": "デジタル信号を搬送波に乗せて送る「変調」という処理がなぜ必要になるのかを問う設問。", "point": "「伝送路が伝えられるのは決まった周波数帯の連続的な波」「デジタルの方形波はそのままだと伝わりにくい」の2つがつながれば、変調の必要性が見える。", "kid": "電話回線などの伝送路は、声のようになだらかに変化する波を伝えるように作られている。0と1がカクカク切り替わるデジタル信号をそのまま流すと、波形が崩れて遠くまで正しく届かない。そこで、伝送路が得意な滑らかな波(搬送波)を用意し、その波の性質を変化させることで0と1を表現する。", "eg": "和太鼓の連打(デジタルの方形波)をそのまま電話越しに伝えようとすると音が割れて聞き取れないので、いったんメロディ(搬送波)に乗せて届けるようなもの。", "terms": [["変調", "デジタル信号の情報を、搬送波というアナログの波の性質(振幅・周波数・位相)を変化させて表現すること"], ["搬送波", "情報を乗せる元になる、一定の周波数を持つアナログの波"], ["方形波", "0と1が瞬時に切り替わる、角ばった形のデジタル信号の波形"]], "think": "なぜ方形波のままでは伝わりにくいのかがカギ。方形波は角ばった形をしており、これを周波数の成分に分解すると非常に広い範囲の周波数を含んでしまう。ところが電話回線のような伝送路は、決まった狭い周波数帯域しか通さないように作られている。帯域からはみ出した周波数成分は伝送路の途中で減衰してしまい、受信側に届くころには波形が崩れて0と1を正しく区別できなくなる。そこで、伝送路の帯域内に収まる一定周波数の搬送波を用意し、その振幅・周波数・位相のいずれかを0と1に応じて変化させることで、帯域内に収まる形で情報を送る。これが変調である。", "why_asked": "「デジタルのほうが優れているのになぜわざわざアナログに戻すのか」という直感的な疑問を突き、伝送路側の制約という前提を見落とさせる出題が多い。", "opt": ["正解。電話回線のような伝送路は特定の周波数帯域の連続的な波を伝えるように作られており、方形波のままのデジタル信号は減衰やひずみが大きく長距離を安定して伝わりにくいため。", "0と1の2値で表せる情報量そのものは変調の有無と無関係であり、情報量不足が変調の理由ではない。", "アナログ信号がデジタル信号より常に高速というわけではなく、速度の優劣が変調の理由ではない。", "変調は伝送路の周波数特性に合わせて信号を伝えやすくする処理であり、内容を秘匿する暗号化とは目的が異なる。"]}'),
  ('ap-core-q147', '通信に関する理論', '変調において、0と1のデジタル情報を運ぶために使われる、一定の周波数を持つアナログの波を何と呼ぶか。', NULL::text, '["搬送波", "基底帯域信号", "クロック信号", "標本化パルス"]'::jsonb, 0, '[0]', 'single', '{"asked": "変調で情報を乗せる元になる、一定周波数のアナログの波の名称を問う設問。", "point": "情報を「乗せる」土台になる波が搬送波。乗せる側の0/1データそのものではない点に注意。", "kid": "搬送波は、まだ何の情報も乗っていない「ただの一定の波」。この波の振幅や周波数や位相を変化させることで、初めて0と1の情報が乗る。", "eg": "何も書いていない白紙のレコード盤のようなもの。そこに音(情報)を刻んで初めて意味のある信号になる。搬送波はその「白紙」にあたる。", "terms": [["搬送波", "情報を乗せる元になる、一定の周波数を持つアナログの波"], ["変調", "搬送波の振幅・周波数・位相のいずれかを変化させて情報を表現すること"]], "think": "見分け方は、情報を乗せる土台の波か、タイミングを合わせるための信号かに着目することにある。搬送波は情報が乗る前の一定周波数の波そのものであり、変調によって振幅・周波数・位相のいずれかが変化して初めて情報を運ぶ。一方クロック信号や標本化パルスは、情報を乗せる波ではなく、送受信のタイミングを合わせたりアナログ信号を区切ったりするための信号であり、役割が異なる。", "why_asked": "「搬送波」と、時刻合わせに使う「クロック信号」や標本化(サンプリング)で使う「標本化パルス」を混同させる出題が多い。", "vs": "クロック信号は送受信のタイミングを合わせるための信号であり、搬送波は情報そのものを乗せる波である点で役割が異なる。", "opt": ["正解。搬送波は、情報を乗せる元になる一定の周波数を持つアナログの波である。", "基底帯域信号は変調される前の、そのままの周波数帯で送るデジタル信号を指し、搬送波とは別のものである。", "クロック信号は送受信のタイミングを合わせるための信号であり、情報を乗せる波ではない。", "標本化パルスはアナログ信号を一定間隔で区切って読み取る(標本化する)ときに使うものであり、変調の搬送波とは異なる。"]}'),
  ('ap-core-q148', '通信に関する理論', 'デジタル信号の0と1を、搬送波の周波数を切り替えることによって表現する変調方式はどれか。', NULL::text, '["周波数偏移変調(FSK)", "振幅偏移変調(ASK)", "位相偏移変調(PSK)", "直交振幅変調(QAM)"]'::jsonb, 0, '[0]', 'single', '{"asked": "搬送波の「周波数」を変化させて0と1を表す変調方式の名称を問う設問。", "point": "ASKは振幅、FSKは周波数、PSKは位相――変化させる搬送波の性質の名前がそのまま方式名になっている。", "kid": "搬送波には「振幅(波の大きさ)」「周波数(波の細かさ)」「位相(波の始まるタイミング)」という3つの性質がある。FSKはこのうち周波数を、0のときと1のときで切り替えることで情報を表す。", "eg": "モールス信号の音の高さを、短音のときは低い音、長音のときは高い音に変えて送るようなもの。音の高さ(周波数)そのものを切り替えて意味を伝えている。", "terms": [["FSK(周波数偏移変調)", "搬送波の周波数を0と1で切り替えて情報を表す変調方式"], ["ASK(振幅偏移変調)", "搬送波の振幅(波の大きさ)を0と1で切り替えて情報を表す変調方式"], ["PSK(位相偏移変調)", "搬送波の位相(波の始まるタイミングのずれ)を0と1で切り替えて情報を表す変調方式"]], "think": "見分け方は、搬送波のどの性質(振幅・周波数・位相)を切り替えているかに着目することにある。ASKは振幅、FSKは周波数、PSKは位相を0と1に応じて切り替える。FSKは周波数を切り替える方式なので、0のときと1のときで搬送波の周波数が高低に変わる。QAMは振幅と位相を組み合わせて一度に多くの値を表現する、より発展した方式である。", "why_asked": "ASK・FSK・PSKの名称と、それぞれが変化させる搬送波の性質(振幅・周波数・位相)の対応を正しく覚えているかを問う典型パターン。", "vs": "ASKは振幅、PSKは位相を切り替える点でFSKと異なる。QAMは振幅と位相を組み合わせて多くの値を一度に表現する、より高度な方式である。", "opt": ["正解。周波数偏移変調(FSK)は、搬送波の周波数を0と1で切り替えて情報を表す方式である。", "振幅偏移変調(ASK)は周波数ではなく搬送波の振幅(波の大きさ)を切り替える方式である。", "位相偏移変調(PSK)は周波数ではなく搬送波の位相(波の始まるタイミングのずれ)を切り替える方式である。", "直交振幅変調(QAM)は振幅と位相を組み合わせて表現する方式であり、周波数のみを切り替える方式ではない。"]}'),
  ('ap-core-q149', '通信に関する理論', '1本の通信回線を複数の通信で共有し、同時に多くのデータをやり取りできるようにする技術を総称して何と呼ぶか。', NULL::text, '["多重化", "パケット交換", "フロー制御", "誤り訂正"]'::jsonb, 0, '[0]', 'single', '{"asked": "1本の回線を複数の通信で共有できるようにする技術の総称を問う設問。", "point": "「1本の回線」を「複数の通信」で分け合う仕組みの名前が多重化。分け方(時間か周波数か)は多重化の中の方式の違い。", "kid": "回線を1本敷設するにはコストがかかる。そこで1本の回線を工夫して分割し、あたかも複数本あるかのように複数の通信を同時に流せるようにするのが多重化。", "eg": "1本の道路を、時間帯で区切って別々の車列を通したり、車線を分けて別々の車列を通したりして、道路自体を増やさずに多くの車を流すようなもの。", "terms": [["多重化", "1本の伝送路を複数の通信で共有し、同時に多くのデータを流せるようにする技術"], ["チャネル", "多重化された回線の中で、1つの通信に割り当てられる区分"]], "think": "なぜ多重化が必要なのかがカギ。通信回線を1本敷設・維持するにはコストと手間がかかるため、利用者や通信の数だけ回線を増やすのは現実的でない。そこで、時間や周波数といった伝送路の使い方を工夫して区分けし、1本の物理的な回線の中に複数の通信の入る余地を作る。これによって回線の本数を増やさずに、より多くの通信を同時にさばけるようになる。", "why_asked": "多重化(回線の共有技術)と、パケット交換やフロー制御といった別のネットワーク技術を混同させる出題が多い。", "vs": "パケット交換はデータを小さく区切って送る通信方式、フロー制御は送受信の速度差を調整する仕組みであり、いずれも「1本の回線を複数の通信で共有する」ことそのものを指す多重化とは異なる。", "opt": ["正解。多重化は、1本の通信回線を複数の通信で共有し、同時に多くのデータをやり取りできるようにする技術の総称である。", "パケット交換はデータを小さな単位(パケット)に分割して送る通信方式であり、回線の共有そのものを指す言葉ではない。", "フロー制御は送信側と受信側の処理速度の差を調整する仕組みであり、回線を複数の通信で共有する技術ではない。", "誤り訂正は伝送中に生じた誤りを検出・修復する仕組みであり、回線の共有技術ではない。"]}'),
  ('ap-core-q150', '通信に関する理論', '通信回線の使用時間を細かい時間枠(タイムスロット)に分割し、各利用者の通信を順番に割り当てることで、1本の回線に複数の通信を多重化する方式はどれか。', NULL::text, '["時分割多重(TDM)", "周波数分割多重(FDM)", "符号分割多重(CDM)", "空間分割多重(SDM)"]'::jsonb, 0, '[0]', 'single', '{"asked": "回線の「使用時間」を分割して複数の通信に割り当てる多重化方式の名称を問う設問。", "point": "「時間を区切って順番に使う」＝TDM。周波数を区切るFDMと対になる名前で覚える。", "kid": "TDMは、1本の回線を通信A・B・Cが順番に少しずつ使う方式。ごく短い時間ごとに使う人を入れ替えるので、それぞれの利用者からは自分専用の回線があるように見える。", "eg": "1つの会議室を、A社が9時台、B社が9時台の次の数分、C社がさらにその次の数分…というように、短い時間ごとに順番に使い回すようなもの。", "terms": [["タイムスロット", "TDMで1つの通信に割り当てられる、細かく区切られた時間の枠"]], "think": "なぜ短い時間枠で交代するだけで、複数の通信を同時に扱えるように感じられるのかがカギ。TDMでは回線の使用時間をごく短いタイムスロットに分割し、通信ごとに順番にそのスロットを割り当てる。1つの通信が使える時間はごく短いが、次に自分の順番が回ってくるまでの間隔も同じくらい短いため、利用者からは途切れなく自分の通信が流れているように感じられる。こうして1本の回線の中に、時間という軸で複数の通信の入る余地を作り出している。", "why_asked": "TDM(時間で分ける)とFDM(周波数で分ける)を、名前だけで逆に覚えて取り違えるパターンが多い。", "vs": "FDMは周波数帯域を分けて同時に流すのに対し、TDMは同じ周波数帯を、短い時間ごとに交代で使う点が異なる。", "opt": ["正解。時分割多重(TDM)は、回線の使用時間を細かい時間枠に分割し、各利用者の通信を順番に割り当てる方式である。", "周波数分割多重(FDM)は時間ではなく周波数帯域を分割する方式であり、時間で分ける方式ではない。", "符号分割多重(CDM)は利用者ごとに異なる符号(データの区別に使うパターン)を割り当てて同じ時間・周波数を共有する方式であり、時間枠で区切る方式ではない。", "空間分割多重(SDM)はアンテナの空間的な配置を利用して複数の通信を分ける方式であり、時間枠で区切る方式ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">時分割多重(TDM): 回線の使用時間を分けて割り当てる</text>\n<g font-size=\"10\">\n<rect x=\"20\" y=\"45\" width=\"33\" height=\"30\" fill=\"#3b82f6\"/><text x=\"36\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">A</text>\n<rect x=\"53\" y=\"45\" width=\"33\" height=\"30\" fill=\"#6ab08d\"/><text x=\"69\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">B</text>\n<rect x=\"86\" y=\"45\" width=\"33\" height=\"30\" fill=\"#c9a04a\"/><text x=\"102\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">C</text>\n<rect x=\"119\" y=\"45\" width=\"33\" height=\"30\" fill=\"#3b82f6\"/><text x=\"135\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">A</text>\n<rect x=\"152\" y=\"45\" width=\"33\" height=\"30\" fill=\"#6ab08d\"/><text x=\"168\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">B</text>\n<rect x=\"185\" y=\"45\" width=\"33\" height=\"30\" fill=\"#c9a04a\"/><text x=\"201\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">C</text>\n<rect x=\"218\" y=\"45\" width=\"33\" height=\"30\" fill=\"#3b82f6\"/><text x=\"234\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">A</text>\n<rect x=\"251\" y=\"45\" width=\"33\" height=\"30\" fill=\"#6ab08d\"/><text x=\"267\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">B</text>\n<rect x=\"284\" y=\"45\" width=\"33\" height=\"30\" fill=\"#c9a04a\"/><text x=\"300\" y=\"65\" text-anchor=\"middle\" fill=\"#e8eaf0\">C</text>\n</g>\n<line x1=\"20\" y1=\"95\" x2=\"317\" y2=\"95\" stroke=\"#2a2f3f\" stroke-width=\"1.5\" marker-end=\"url(#arrow1)\"/>\n<text x=\"170\" y=\"112\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">時間 →(1本の回線をA,B,Cが順番に使う)</text>\n<text x=\"170\" y=\"132\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">同じ周波数帯を、短い時間枠(タイムスロット)で分け合う</text>\n<defs><marker id=\"arrow1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#2a2f3f\"/></marker></defs>\n</svg>"}'),
  ('ap-core-q151', '通信に関する理論', '通信回線が使える周波数帯域をいくつかの帯域に分割し、各利用者に別々の周波数帯域を割り当てることで、1本の回線に複数の通信を多重化する方式はどれか。', NULL::text, '["周波数分割多重(FDM)", "時分割多重(TDM)", "符号分割多重(CDM)", "空間分割多重(SDM)"]'::jsonb, 0, '[0]', 'single', '{"asked": "回線の「周波数帯域」を分割して複数の通信に割り当てる多重化方式の名称を問う設問。", "point": "「周波数帯を区切って同時に使う」＝FDM。時間を区切るTDMと対になる名前で覚える。", "kid": "FDMは、1本の回線が使える周波数の範囲をいくつかの帯域に分け、通信A・B・Cにそれぞれ別々の帯域を割り当てる方式。各利用者は同じ時間帯にずっと自分の帯域を使い続けられる。", "eg": "1本の道路を車線ごとに分け、A社の車はいつでも1車線目、B社の車はいつでも2車線目、というように専用の車線を割り当てるようなもの。", "terms": [["周波数帯域", "通信に使うことのできる、周波数の範囲"]], "think": "なぜ周波数帯域を分けるだけで、複数の通信を同時に流せるのかがカギ。FDMでは回線が使える周波数の範囲をいくつかの帯域に分割し、通信ごとに別々の帯域を割り当てる。それぞれの帯域は互いに重ならないため、同じ時間に複数の帯域の信号を同時に流しても、受信側は自分に割り当てられた帯域だけを取り出せば、他の通信と混ざらずに元の信号を取り出せる。こうして1本の回線の中に、周波数という軸で複数の通信の入る余地を作り出している。", "why_asked": "FDM(周波数で分ける)とTDM(時間で分ける)の取り違えのほか、光ファイバーで使われる波長分割多重(WDM)と混同させる出題もある。", "vs": "TDMは同じ周波数帯を短い時間ごとに交代で使うのに対し、FDMは同じ時間帯に、別々の周波数帯を同時に使い続ける点が異なる。", "opt": ["正解。周波数分割多重(FDM)は、回線の周波数帯域をいくつかに分割し、各利用者に別々の帯域を割り当てる方式である。", "時分割多重(TDM)は周波数ではなく使用時間を分割する方式であり、周波数帯域で分ける方式ではない。", "符号分割多重(CDM)は周波数帯域ではなく符号(データの区別に使うパターン)によって通信を区別する方式である。", "空間分割多重(SDM)はアンテナの空間的な配置を利用して複数の通信を分ける方式であり、周波数帯域で区切る方式ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">周波数分割多重(FDM): 回線の周波数帯域を分けて割り当てる</text>\n<g font-size=\"10\">\n<rect x=\"45\" y=\"30\" width=\"270\" height=\"24\" fill=\"#c9a04a\"/><text x=\"180\" y=\"46\" text-anchor=\"middle\" fill=\"#e8eaf0\">チャネルC(高い周波数帯)</text>\n<rect x=\"45\" y=\"58\" width=\"270\" height=\"24\" fill=\"#6ab08d\"/><text x=\"180\" y=\"74\" text-anchor=\"middle\" fill=\"#e8eaf0\">チャネルB(中間の周波数帯)</text>\n<rect x=\"45\" y=\"86\" width=\"270\" height=\"24\" fill=\"#3b82f6\"/><text x=\"180\" y=\"102\" text-anchor=\"middle\" fill=\"#e8eaf0\">チャネルA(低い周波数帯)</text>\n</g>\n<line x1=\"30\" y1=\"118\" x2=\"30\" y2=\"22\" stroke=\"#2a2f3f\" stroke-width=\"1.5\" marker-end=\"url(#arrow2)\"/>\n<text x=\"18\" y=\"70\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\" transform=\"rotate(-90 18 70)\">周波数</text>\n<line x1=\"45\" y1=\"120\" x2=\"315\" y2=\"120\" stroke=\"#2a2f3f\" stroke-width=\"1.5\" marker-end=\"url(#arrow2)\"/>\n<text x=\"180\" y=\"136\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8892a4\">時間 →(A,B,Cは同時に、別々の周波数帯で流れ続ける)</text>\n<defs><marker id=\"arrow2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#2a2f3f\"/></marker></defs>\n</svg>"}'),
  ('ap-core-q152', '通信に関する理論', '時分割多重(TDM)と周波数分割多重(FDM)の違いを説明したものとして、最も適切なものはどれか。', NULL::text, '["TDMは同じ周波数帯域を使い、送信するタイミング(時間)を利用者ごとに分けるのに対し、FDMは同じ時間帯に、使う周波数帯域を利用者ごとに分ける", "TDMは回線の敷設方式が単純なことから有線回線でのみ使われる方式であり、FDMは電波の性質を利用することから無線回線でのみ使われる方式である", "TDMは信号がとぎれとぎれに送られることからアナログ回線向けの多重化方式であり、FDMは信号が連続して送られることからデジタル回線向けの多重化方式である", "TDMは1利用者につき1本の物理回線をまるごと専有する方式であるのに対し、FDMは全利用者が1本の回線をまったく区別なく同時に共有する方式である"]'::jsonb, 0, '[0]', 'single', '{"asked": "TDMとFDMという2つの多重化方式の違いを問う設問。", "point": "「何を区切って利用者ごとに分けているか」で見分ける。TDMは時間、FDMは周波数を区切っている。", "kid": "TDMは、1本の道を時間帯で区切って車列に順番に使わせる方式。FDMは、1本の道を車線で区切って車列に同時に使わせる方式。どちらも「1本を分けて共有する」点は同じだが、分け方の軸が時間か周波数かで違う。", "eg": "TDMは「同じ電話回線を、Aさんが1分間、次にBさんが1分間…」と時間で順番を回す使い方。FDMは「同じ回線の中でAさん用の音域、Bさん用の音域…」と周波数帯で住み分ける使い方。", "terms": [["TDM", "回線の使用時間を分割し、利用者ごとに順番に割り当てる多重化方式"], ["FDM", "回線の周波数帯域を分割し、利用者ごとに別々の帯域を割り当てる多重化方式"]], "think": "見分け方は、利用者ごとに分けている軸が時間か周波数かに着目することにある。TDMは同じ周波数帯を使い続けながら、通信ごとに使う「時間」をずらすことで衝突を避ける。FDMは同じ時間帯を使い続けながら、通信ごとに使う「周波数」をずらすことで混信を避ける。どちらも1本の回線を複数の通信で分け合うという目的は同じだが、何を軸にして分けているかが異なる。", "why_asked": "TDMとFDMの違いを、「有線か無線か」「アナログかデジタルか」といった実際には無関係な軸にすり替えて誤答へ誘導する出題が多い。", "vs": "TDMとFDMはどちらも「1本の回線を複数の通信で分け合う」という目的は同じだが、分ける軸が時間か周波数かという点だけが異なる。", "opt": ["正解。TDMは同じ周波数帯域を使い、送信するタイミング(時間)を利用者ごとに分けるのに対し、FDMは同じ時間帯に、使う周波数帯域を利用者ごとに分ける。", "TDM・FDMのどちらも有線・無線のいずれの回線でも使われており、使われる回線の種類で区別されるわけではない。", "TDM・FDMのどちらもアナログ・デジタルいずれの回線でも利用でき、対応する回線の種類で区別されるわけではない。", "TDMは短い時間枠を交代で使う方式であって回線を専有するわけではなく、FDMは周波数帯域ごとに区別して共有する方式であり「まったく区別なく」共有するわけではない。"]}'),
  ('ap-core-q153', '通信に関する理論', '送信するデータをあらかじめ決めておいた生成多項式で割った余りを検査用のビット列として付加し、受信側でも同じ計算を行って余りが一致するかどうかで誤りを検出する方式はどれか。', NULL::text, '["CRC(巡回冗長検査)", "パリティチェック", "ハミング符号", "チェックサム"]'::jsonb, 0, '[0]', 'single', '{"asked": "生成多項式による割り算の余りを検査ビットとして使う誤り検出方式の名称を問う設問。", "point": "「生成多項式で割った余り」を検査に使う、という仕組みの特徴だけでCRCだと判断できる。", "kid": "CRCは、送るデータをある決まった数(生成多項式)で割り算し、その余りをデータの後ろにくっつけて送る。受信側も同じ割り算をして、送られてきた余りと自分で計算した余りが一致するかを見れば、伝送中に誤りが混ざったかどうかがわかる。", "eg": "荷物の重さの下2桁を送り状に書いておき、受け取った側が実際に量った重さの下2桁と照合するようなもの。数字が合わなければ、途中で荷物の中身が変わった(誤りが起きた)とわかる。", "terms": [["CRC(巡回冗長検査)", "生成多項式で割った余りを検査ビットとして付加し、誤りを検出する方式"], ["生成多項式", "CRCの計算で送信データを割るために、送受信側であらかじめ決めておく式"]], "think": "見分け方は、検査値の作り方に着目することにある。パリティチェックは1の個数の偶奇という単純な情報だけを使い、ハミング符号は複数のパリティビットの組み合わせで誤りのビット位置まで特定できるようにする。CRCはデータ全体を生成多項式で割った余りという、ビットの並び方まで反映した値を検査に使うため、単純なパリティチェックより多くの誤りパターンを検出できる。", "why_asked": "CRCの仕組みを、1ビットのパリティチェックや、位置特定までできるハミング符号と混同させる出題が多い。", "vs": "パリティチェックは1の個数の偶奇だけを見る単純な検査であり、ハミング符号は誤りのビット位置まで特定して訂正できる方式である。CRCは生成多項式の余りという、より多くの情報を使って誤りの有無を検出する点で異なる。", "opt": ["正解。CRC(巡回冗長検査)は、生成多項式で割った余りを検査ビットとして付加し、受信側でも同じ計算をして誤りを検出する方式である。", "パリティチェックはデータ中の1の個数の偶奇をそろえる1ビットの検査であり、生成多項式による割り算は使わない。", "ハミング符号は複数のパリティビットの組み合わせで誤りのビット位置まで特定し訂正できる符号であり、生成多項式による割り算とは仕組みが異なる。", "チェックサムはデータを一定単位ごとに区切って足し合わせた値を検査に使う方式であり、生成多項式による割り算は使わない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<g font-size=\"9\" fill=\"#e8eaf0\">\n<rect x=\"8\" y=\"10\" width=\"66\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"41\" y=\"27\" text-anchor=\"middle\">送信データ</text>\n<rect x=\"90\" y=\"10\" width=\"86\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"133\" y=\"27\" text-anchor=\"middle\">生成多項式で割る</text>\n<rect x=\"192\" y=\"10\" width=\"140\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\"/><text x=\"262\" y=\"27\" text-anchor=\"middle\" fill=\"#60a5fa\">余りを検査符号として付加</text>\n</g>\n<line x1=\"74\" y1=\"23\" x2=\"88\" y2=\"23\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<line x1=\"176\" y1=\"23\" x2=\"190\" y2=\"23\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<text x=\"262\" y=\"52\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8892a4\">↓ 回線へ送信</text>\n<rect x=\"80\" y=\"60\" width=\"180\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/>\n<text x=\"170\" y=\"77\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">受信側が同じ式でもう一度割る</text>\n<line x1=\"262\" y1=\"58\" x2=\"200\" y2=\"60\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<line x1=\"170\" y1=\"86\" x2=\"170\" y2=\"98\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<rect x=\"120\" y=\"98\" width=\"100\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#c9a04a\"/>\n<text x=\"170\" y=\"114\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">余りは0か?</text>\n<line x1=\"120\" y1=\"110\" x2=\"70\" y2=\"128\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<line x1=\"220\" y1=\"110\" x2=\"270\" y2=\"128\" stroke=\"#2a2f3f\" marker-end=\"url(#arrow3)\"/>\n<rect x=\"15\" y=\"128\" width=\"100\" height=\"20\" rx=\"3\" fill=\"#6ab08d\"/><text x=\"65\" y=\"142\" text-anchor=\"middle\" font-size=\"9\" fill=\"#12261d\">0: 誤りなし</text>\n<rect x=\"225\" y=\"128\" width=\"100\" height=\"20\" rx=\"3\" fill=\"#c47070\"/><text x=\"275\" y=\"142\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2a1010\">0以外: 誤りあり</text>\n<defs><marker id=\"arrow3\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#2a2f3f\"/></marker></defs>\n</svg>"}'),
  ('ap-core-q154', '通信に関する理論', 'CRC(巡回冗長検査)が、雑音などによって連続した複数ビットが同時に反転する「バースト誤り」の検出において、単純な1ビットのパリティチェックより強いとされる理由として、最も適切なものはどれか。', NULL::text, '["パリティチェックは1の個数の偶奇という1つの情報しか検査しないため偶数個のビットが同時に反転すると見逃すが、CRCはビットの並び方まで反映した割り算の余りを使うため連続した誤りも検出しやすいから", "CRCは検査用に付加するビット数がパリティチェックより常に少なく済むため伝送時間そのものが短縮され、その結果として雑音の影響を受ける時間も短くなり誤りの発生自体が減るから", "CRCは誤りを検出するだけでなく、生成多項式を使った計算によって反転したビットの位置まで特定し、自動的に元の値へ訂正する機能まで備えているから", "CRCは送信のたびに使用する生成多項式を通信の状況に応じてランダムに変更する仕組みを持つため、雑音によって生じる決まったパターンの誤りをより見つけやすくなるから"]'::jsonb, 0, '[0]', 'single', '{"asked": "CRCがパリティチェックよりバースト誤りの検出に強いとされる理由を問う設問。", "point": "「パリティは1の個数の偶奇という1つの情報しか見ない」「CRCはビットの並び方まで反映した余りを見る」の対比がカギ。", "kid": "パリティチェックは「1がいくつあるか」しか見ていないので、たまたま2個(偶数個)のビットが同時に反転すると、個数の偶奇は変わらず見逃してしまう。CRCはビットの並び方まで巻き込んだ計算をするので、連続した誤りにも気づきやすい。", "eg": "パリティチェックは「参加人数が合っているか」だけを数える点呼のようなもの。人数さえ合っていれば、別人にすり替わっていても気づけない。CRCは「誰が何番目に並んでいるか」まで確認する点呼に近く、順番の入れ替わりにも気づきやすい。", "terms": [["バースト誤り", "雑音などによって連続した複数ビットがまとめて反転してしまう誤り"], ["偶奇", "個数が偶数か奇数かということ"]], "think": "なぜパリティチェックはバースト誤りを見逃すのかがカギ。パリティチェックは、送信データ中の1の個数を数え、その個数が偶数になる(または奇数になる)ようにパリティビットを1つ付けるだけの検査である。この検査で分かるのは「1の個数の偶奇」というただ1つの情報にすぎない。もし雑音でたまたま2個のビットが同時に0↔1反転すると、1の個数の偶奇は変化しないため、パリティチェックはこの誤りに気づけない。一方CRCは、データ全体を1つの大きな2進数とみなし、決められた生成多項式で割った余りを検査値として使う。この余りはデータの並び方(どのビットがどこにあるか)まで反映して変化するため、連続した複数ビットの反転(バースト誤り)が起きると余りも高い確率で変化し、誤りとして検出しやすい。だからCRCはバースト誤りの検出でパリティチェックより強いとされる。", "why_asked": "「検査ビットの数が多い＝優れている」という表面的な理由や、CRCに誤り訂正の機能があるという誤解に誘導する出題が多い。", "vs": "パリティチェックは1の個数という1種類の情報しか使わないのに対し、CRCはビットの並び方まで反映した余りを使う点が、検出力の差の本質である。", "opt": ["正解。パリティチェックは1の個数の偶奇という1つの情報しか検査しないため偶数個のビットが同時に反転すると見逃すが、CRCはビットの並び方まで反映した割り算の余りを使うため連続した誤りも検出しやすいから。", "CRCの検査ビット数がパリティチェックより常に少ないとは限らず、また検査ビット数の多寡は誤りの発生自体を減らす要因ではない。", "CRCは誤りの有無を検出する仕組みであり、反転したビットを自動的に元の値へ訂正する機能は持たない。", "CRCで使う生成多項式は送受信側であらかじめ取り決めて固定しておく値であり、送信のたびにランダムに変更するものではない。"]}'),
  ('ap-core-q155', '通信に関する理論', 'パリティビットやCRCの検査用ビット列を付加すると、本来送りたいデータ以外の余分なビット(冗長ビット)を一緒に送ることになる。それでもなお誤り検出符号を付加する理由として、最も適切なものはどれか。', NULL::text, '["伝送路には雑音などによる誤りが避けられないため、冗長ビットを付加してでも受信側で誤りの有無を確認できるようにし、誤りがあれば再送などの対処につなげる必要があるから", "冗長ビットを付加すると検査符号の分だけ回線上でデータが優先的に扱われるようになり、伝送速度そのものが上がって通信全体の所要時間が短くなるから", "冗長ビットを付加すると、その分だけ搬送波が使う周波数帯域を節約できるようになり、結果として多重化できるチャネルの数が増えるから", "冗長ビットを付加すると、その並び方自体が一種の暗号のように働くため、あらためて暗号化を行わなくてもデータの盗聴を防げるから"]'::jsonb, 0, '[0]', 'single', '{"asked": "データ量が増えるという代償を払ってまで誤り検出符号を付加する理由を問う設問。", "point": "「伝送路の誤りはゼロにできない」「だから誤りに気づく仕組みが要る」という因果がカギ。", "kid": "どんなに丁寧に作った回線でも、雑音などでビットが反転してしまうことをゼロにはできない。だから、多少データ量が増えてでも「誤りに気づける仕組み」を付けておき、誤りに気づいたら送り直す、という対処につなげる。", "eg": "大事な手紙に念のため控えを1通添えて送るようなもの。控えの分だけ荷物は増えるが、本紙が読めなくなっていたときに気づける安心感には代えられない。", "terms": [["冗長ビット", "誤り検出のために本来のデータへ付け加える、検査専用の余分なビット"], ["再送", "誤りが検出されたデータを、送信側からもう一度送り直すこと"]], "think": "なぜ余分なビットを送ってでも誤り検出を行う価値があるのかがカギ。通信回線には雑音や信号の減衰といった要因が必ず存在し、伝送中に一部のビットが反転してしまう可能性をゼロにはできない。もし誤り検出の仕組みが無ければ、受信側は届いたデータをそのまま正しいものとして扱うしかなく、誤ったデータに気づかないまま処理を進めてしまう。パリティビットやCRCの検査符号を付加しておけば、受信側は届いたデータが正しいかどうかを自分で確認でき、誤りを検出した場合は送信側に再送を要求するなどの対処につなげられる。つまり冗長ビットのコストは、誤りに気づける安心と引き換えの投資である。", "why_asked": "冗長ビットのコストにばかり注目させ、「それでも付加する理由」という本質的な動機を見落とさせる出題が多い。", "opt": ["正解。伝送路には雑音などによる誤りが避けられないため、冗長ビットを付加してでも受信側で誤りの有無を確認できるようにし、誤りがあれば再送などの対処につなげる必要があるから。", "冗長ビットの付加はデータ量を増やす処理であり、伝送速度を上げたり所要時間を短縮したりする効果はない。", "冗長ビットの付加と、多重化で使える周波数帯域やチャネル数とは関係がない。", "誤り検出符号は誤りの有無を確認するための仕組みであり、データの内容を秘匿する暗号化とは目的が異なる。"]}')
) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q156', 'ヒューマンインタフェースとマルチメディア',
   'ISO 9241-11などで定義される「ユーザビリティ」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["特定の利用者が、特定の利用状況において、指定された目標を達成するための有効さ、効率、利用者の満足度の度合い", "利用者から見た画面配色や書体、レイアウトなど、視覚的な見た目の美しさやデザイン性の高さの度合いを表す言葉", "あらかじめ定めた仕様書や設計書の記載どおりに、システムが誤りなく正しく動作し続けることができる度合い", "利用者が操作してから画面に応答が返るまでの時間が短く、処理や応答の速度が速いことを表す度合い"]',
   0,
   '[0]',
   'single',
   '{"asked": "ユーザビリティという言葉が何を測る指標なのかを問う設問。", "point": "「特定の利用者・特定の状況で・目標をどれだけ楽に達成できるか」を測る言葉だと押さえれば見分けられる。", "kid": "ユーザビリティとは「使いやすさ」のこと。誰が、どんな場面で使っても、やりたいことにたどり着きやすいかを表す。", "eg": "駅の券売機にたとえると、初めて使う人でも迷わず切符を買えるなら使いやすさ(ユーザビリティ)が高いと言える。逆にボタンの配置が分かりにくく何度もやり直すなら低い。", "terms": [["有効さ", "目標をきちんと達成できるかどうか"], ["効率", "目標達成までに使う手間や時間の少なさ"], ["満足度", "使っていて不快でないか、また使いたいと思えるか"]], "think": "なぜ「使いやすさ」を一言でなく3つの物差しに分けるのかがカギ。見た目が整っていても操作が複雑なら目標に届かない、これは有効さが低い状態である。目標に届いても手順が多すぎれば疲れる、これは効率が低い状態である。効率よく目標に届いても操作中に苛立つなら次も使いたいと思えない、これは満足度が低い状態である。この3つがそろって初めて「使いやすい」と言えるため、ユーザビリティの定義には3つの要素が含まれている。", "vs": "「性能(処理速度)」や「信頼性(正しく動くか)」と混同しやすいが、これらはユーザビリティとは別の品質特性として扱われる。", "why_asked": "「デザインが良い」「速い」といった感覚的な言葉とユーザビリティの定義を混同していないかを問う出題が定番。", "opt": ["正解。ISO 9241-11(JIS Z 8521)の定義そのもの。「誰が」「どんな場面で」「何を達成するか」を明確にした上で、うまく到達できるか(有効さ)、無駄なく到達できるか(効率)、使っていて気持ちよいか(満足度)の3つの物差しで測る考え方である。", "不正解。見た目の美しさは大切な要素だが、ユーザビリティそのものの定義ではない。デザイン性は別の評価軸として語られることが多い。", "不正解。これは信頼性(動作の正しさ)に関する説明であり、使いやすさの度合いを指すユーザビリティとは別の観点である。", "不正解。処理速度は性能(パフォーマンス)の指標であり、利用者が目標を達成できるかというユーザビリティの定義には含まれない。"]}'),

  ('ap-core-q157', 'ヒューマンインタフェースとマルチメディア',
   'ユニバーサルデザインの考え方の説明として、最も適切なものはどれか。',
   NULL::text,
   '["障害の有無、年齢、言語などの違いにかかわらず、できるだけ多くの人が利用できるように製品や環境をはじめから設計すること", "障害のある利用者や高齢者など特定の対象者に向けて、標準の製品とは別に専用の製品をあとから新たに開発して提供すること", "利用者ごとに個別の設定画面や操作方法を用意し、各自の好みに合わせて自由に細かくカスタマイズできるようにすること", "既存の操作方法にとらわれず、最新の技術を積極的に採用して先進的で目新しい操作方法を追求し続けること"]',
   0,
   '[0]',
   'single',
   '{"asked": "ユニバーサルデザインという考え方が何を目指しているかを問う設問。", "point": "「後から専用対応を足す」のではなく「はじめから誰もが使えるように作る」と言っていれば正解と見分けられる。", "kid": "ユニバーサルデザインとは、体の状態や年齢、言語が違ってもできるだけ多くの人が最初から使えるように、製品や建物を作る考え方。", "eg": "自動ドアにたとえると、車椅子の人のためだけに別の入口を作るのではなく、そもそも全員が通る入口を自動ドアにしてしまえば、誰も特別扱いせずに済む。これがユニバーサルデザインの発想。", "terms": [["バリアフリー", "既にある障壁(バリア)を、あとから取り除く考え方"], ["アクセシビリティ", "特定の利用者が製品や情報にどれだけ到達・利用できるかの度合い"]], "think": "なぜ「特定のユーザーだけ」ではなく「誰もが」を最初から目指すのかがカギ。あとから専用の対応、たとえば改修や専用製品を追加するやり方は、対象をそのつど狭く区切ってしまい、想定していなかった人を毎回取りこぼしてしまう。また改修のたびにコストもかかる。はじめから多様な利用者を想定して1つの設計にまとめれば、取りこぼしが減り、結果として専用の作り直しも減らせる。だから「誰もが使える」ことを設計の出発点に置く。", "vs": "あとから障害者向けに障壁を取り除く「バリアフリー」との違いが問われやすい。ユニバーサルデザインは最初から誰もが使える設計を目指す点が異なる。", "why_asked": "バリアフリーとの違いを問う出題が定番。「専用対応」と「最初から誰もが使える設計」を取り違えないかがポイント。", "opt": ["正解。ユニバーサルデザインは、特別な改造や専用設計をあとから追加するのではなく、年齢・障害の有無・言語などの違いを問わず、はじめからできるだけ多くの人が使えるように製品や環境を設計する考え方である。", "不正解。これは特定の利用者向けにあとから別途専用の製品を用意する考え方であり、ユニバーサルデザインが目指す「はじめから誰もが使える設計」とは方向性が異なる。", "不正解。個別カスタマイズを前提にする点が、はじめから誰もが使えることを目指すユニバーサルデザインの考え方とは異なる。", "不正解。先進的な操作方法の追求自体はユニバーサルデザインの定義とは無関係であり、むしろ不慣れな利用者を置き去りにする恐れがある。"]}'),

  ('ap-core-q158', 'ヒューマンインタフェースとマルチメディア',
   'ユーザビリティ評価手法のうち、複数の専門家が経験則(チェックリスト)に照らして画面や操作の問題点を指摘する手法はどれか。',
   NULL::text,
   '["ヒューリスティック評価", "ユーザビリティテスト", "アンケート調査", "思考発話法"]',
   0,
   '[0]',
   'single',
   '{"asked": "専門家が経験則をもとに問題点を指摘するユーザビリティ評価手法の名称を問う設問。", "point": "「専門家が」「経験則(チェックリスト)に照らして」問題点を指摘する、という2点がそろえばヒューリスティック評価だと見分けられる。", "kid": "ヒューリスティック評価とは、使いやすさの専門家が数人で、過去の経験からできたチェックリストを手がかりに、画面を見て「ここが分かりにくい」と指摘していく方法。", "eg": "料理のプロが、実際に味見をせずにレシピと盛り付けを見ただけで「この工程は失敗しやすい」と経験から指摘するようなもの。実際に食べる人(利用者)を呼ばなくても、専門知識だけである程度の問題点を洗い出せる。", "terms": [["ユーザビリティテスト", "実際の利用者にタスクを行ってもらい、行動や発話を観察して問題点を見つける手法"], ["思考発話法", "利用者に操作しながら考えていることを声に出してもらい、つまずきを把握する手法"]], "think": "なぜ利用者を集めなくても専門家だけで評価できるのかがカギ。使いやすさの問題には「ボタンの意味が想像しにくい」「戻る手段がない」など、過去の多くの製品で繰り返し起きるパターンがある。専門家はそのパターンを経験則としてチェックリストにまとめているため、実際に人を集めて観察しなくても、画面や仕様書をそのチェックリストに照らし合わせるだけで多くの問題を先回りして見つけられる。その分、期間もコストも短く済む。", "vs": "実際の利用者を集めて行動を観察する「ユーザビリティテスト」と混同しやすいが、あちらは利用者本人の行動が対象、ヒューリスティック評価は専門家の経験則が対象という点で異なる。", "why_asked": "「誰が」「何を手がかりに」評価するかで手法名を取り違えさせる出題が多い。", "opt": ["正解。専門家が複数人で、経験則をまとめたチェックリストに照らして画面や仕様書を検討し、問題点を指摘していく手法である。", "不正解。これは実際の利用者にタスクを実行してもらい、その行動や発言を観察して問題点を見つける手法であり、経験則に照らす専門家評価とは主体が異なる。", "不正解。これは利用者の主観的な満足度や印象を尋ねて把握する手法であり、専門家が経験則で問題点を指摘する手法とは異なる。", "不正解。これは利用者に操作しながら考えていることを声に出してもらう手法であり、専門家の経験則をもとに評価するヒューリスティック評価とは異なる。"]}'),

  ('ap-core-q159', 'ヒューマンインタフェースとマルチメディア',
   'ユーザビリティ評価手法のうち、数名の被験者に実際の画面でタスクを実行してもらい、その行動や発言を観察して問題点を発見する手法はどれか。',
   NULL::text,
   '["ユーザビリティテスト", "ヒューリスティック評価", "認知的ウォークスルー", "アンケート調査"]',
   0,
   '[0]',
   'single',
   '{"asked": "実際の被験者を集めて行動を観察するユーザビリティ評価手法の名称を問う設問。", "point": "「実際の被験者」を集めて「行動や発言を観察する」なら、専門家だけで完結する手法とは別物と見分けられる。", "kid": "ユーザビリティテストとは、実際に使う人を何人か連れてきて、目の前で操作してもらい、迷った様子や言葉から使いにくい点を見つける方法。", "eg": "新しい家電の取扱説明書を作るとき、実際に家族に渡して使ってもらい、どこで手が止まるかを横で見て記録するようなもの。作った本人には気づけない引っかかりが見える。", "terms": [["ヒューリスティック評価", "専門家が経験則(チェックリスト)に照らして画面を評価する手法"], ["認知的ウォークスルー", "専門家が想定利用者になりきって、目標設定から操作までの過程を1つずつ追体験し問題点を洗い出す手法"]], "think": "なぜ専門家の評価だけでなく実際の被験者による観察が必要なのかがカギ。専門家は知識があるぶん、初めて使う利用者が感じる戸惑いを想像しきれないことがある。実際の被験者に操作してもらうと、専門家が想定していなかった勘違いや操作ミスがそのまま観察できる。だから、専門家中心の評価とは別に、生の利用者行動を観察する手法が使い分けられる。", "vs": "専門家が想定利用者になりきって操作を追体験する「認知的ウォークスルー」と混同しやすいが、あちらは実際の被験者を集めない点が異なる。", "why_asked": "「誰が操作するか(専門家か実際の利用者か)」の違いで手法名を選ばせる出題が定番。", "opt": ["正解。数名の被験者に実際の画面でタスクを実行してもらい、その行動や発話を観察して問題点を発見する手法である。", "不正解。これは専門家が経験則(チェックリスト)に照らして問題点を指摘する手法であり、実際の被験者を集めるユーザビリティテストとは主体が異なる。", "不正解。これは専門家が想定利用者になりきって操作の過程を追体験する手法であり、実際の被験者を集めない点でユーザビリティテストとは異なる。", "不正解。これは利用者に主観的な評価を尋ねる手法であり、実際の操作行動をその場で観察するユーザビリティテストとは異なる。"]}'),

  ('ap-core-q160', 'ヒューマンインタフェースとマルチメディア',
   'アナログの音声信号をデジタルデータに変換する方式であるPCM(パルス符号変調)における処理の順序として、適切なものはどれか。',
   NULL::text,
   '["標本化 → 量子化 → 符号化", "量子化 → 標本化 → 符号化", "符号化 → 標本化 → 量子化", "標本化 → 符号化 → 量子化"]',
   0,
   '[0]',
   'single',
   '{"asked": "音声をデジタル化するPCMの3つの処理を、正しい順序に並べる設問。", "point": "「一定間隔で値を取り出す(標本化)」「その値を段階に丸める(量子化)」「2進数に変換する(符号化)」の順だと押さえれば並べ替えられる。", "kid": "PCMとは、なめらかなアナログの音を、一定の間隔で区切って数値の列に変換する方式。", "eg": "坂道の高さを測るとき、一定間隔ごとに定規を当てて高さを読み取り(標本化)、読み取った高さを一番近いキリのよい目盛りに丸め(量子化)、最後にその数字を0と1の並びで書き記す(符号化)、という3段階の作業にたとえられる。", "terms": [["標本化(サンプリング)", "一定の時間間隔でアナログ信号の値を取り出すこと"], ["量子化", "取り出した値を、あらかじめ決めた段階(目盛り)のどれかに丸めること"], ["符号化", "量子化した値を2進数のビット列に変換すること"]], "think": "なぜこの順番でなければならないのかがカギ。連続的に変化するアナログの波は、そのままではコンピュータが扱える飛び飛びの数値になっていない。まず時間軸を一定間隔で区切って値を取り出さないと、その値をどの段階に丸めるかを決めようがない。そして段階に丸めた値が決まって初めて、それを2進数の符号に変換できる。前の工程の出力が次の工程の入力になっているため、順序を入れ替えることはできない。", "vs": "順序を入れ替えた選択肢は、標本化する前の値をいきなり量子化・符号化しようとする点で矛盾する。", "why_asked": "PCMの3工程の名前と順序を入れ替えて出題されることが多い。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">PCM：アナログ音声をデジタルデータへ</text><path d=\"M30 50 Q45 30 60 50 T90 50 T120 50\" stroke=\"#60a5fa\" fill=\"none\" stroke-width=\"2\"/><text x=\"75\" y=\"70\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">アナログ波形</text><rect x=\"14\" y=\"90\" width=\"86\" height=\"36\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"57\" y=\"112\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"12\">標本化</text><path d=\"M104 108 L122 108\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow1)\"/><rect x=\"127\" y=\"90\" width=\"86\" height=\"36\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"170\" y=\"112\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"12\">量子化</text><path d=\"M217 108 L235 108\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow1)\"/><rect x=\"240\" y=\"90\" width=\"86\" height=\"36\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"283\" y=\"112\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"12\">符号化</text><text x=\"170\" y=\"142\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">値を取り出す → 段階に丸める → 2進数にする</text><defs><marker id=\"arrow1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs></svg>", "opt": ["正解。アナログ波形から一定間隔で値を取り出す標本化、取り出した値を段階に丸める量子化、その値を2進数に変換する符号化の順に処理する。", "不正解。量子化は標本化で取り出した値を丸める処理であり、値を取り出す前に丸めることはできない。", "不正解。符号化は量子化した値を2進数に変換する仕上げの処理であり、最初に行うことはできない。", "不正解。符号化は量子化のあとに行う処理であり、量子化より先に符号化することはできない。"]}'),

  ('ap-core-q161', 'ヒューマンインタフェースとマルチメディア',
   'データ圧縮に関する説明のうち、可逆圧縮と非可逆圧縮の違いとして、最も適切なものはどれか。',
   NULL::text,
   '["可逆圧縮は圧縮前のデータを完全に復元できるのに対し、非可逆圧縮は一部の情報を復元できない", "可逆圧縮は音声データに、非可逆圧縮は文書データに、それぞれ用途があらかじめ固定されている", "可逆圧縮のほうが圧縮率が高く、非可逆圧縮のほうが圧縮率が低い", "可逆圧縮と非可逆圧縮は、どちらも人間の感覚では気づけない情報を間引く点で同じ仕組みである"]',
   0,
   '[0]',
   'single',
   '{"asked": "可逆圧縮と非可逆圧縮の性質の違いを問う設問。", "point": "「元に戻せるか戻せないか」で見分ける。戻せるものが可逆、戻せず近似にとどまるものが非可逆。", "kid": "可逆圧縮は圧縮しても後で完全に元通りに戻せる方式、非可逆圧縮は多少情報を捨てて小さくする代わりに完全には元に戻せない方式。", "eg": "衣類の圧縮袋にたとえると、可逆圧縮は空気を抜いてかさを減らすだけなので袋を開ければ元の服にちゃんと戻る。非可逆圧縮は服の一部の繊維を思い切って間引いてさらに小さくするようなもので、間引いた分は元には戻せない。", "terms": [["可逆圧縮", "圧縮前のデータを完全に復元できる圧縮方式。文書やプログラムなど1ビットの欠落も許されないデータに使う"], ["非可逆圧縮", "一部の情報を切り捨てて高い圧縮率を得る方式。人間の目や耳が気づきにくい情報を優先して間引く"]], "think": "なぜ圧縮という工夫が必要なのかがカギ。画像や音声、動画はそのままでは容量がとても大きく、保存や通信に時間もコストもかかる。文書やプログラムは1ビットでも欠けると意味が変わってしまうため、完全に戻せる可逆圧縮でなければ困る。一方、写真や音声は多少の情報が失われても人間の目や耳では気づきにくいことが多いため、思い切って情報を間引く非可逆圧縮を使うことで、可逆圧縮よりずっと高い圧縮率を実現できる。用途によって「完全に戻せることを優先するか」「小ささを優先するか」を使い分けている。", "vs": "非可逆圧縮のほうが一般に高い圧縮率を得られる。可逆圧縮のほうが高圧縮率だと逆に覚えないよう注意。", "why_asked": "「戻せるかどうか」と「圧縮率の高低」を取り違えさせる出題が多い。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">可逆圧縮と非可逆圧縮のちがい</text><text x=\"10\" y=\"46\" fill=\"#6ab08d\" font-size=\"10\" font-weight=\"600\">可逆圧縮</text><rect x=\"60\" y=\"32\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"83\" y=\"49\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">元データ</text><path d=\"M108 45 L128 45\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"132\" y=\"32\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><text x=\"155\" y=\"49\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">圧縮</text><path d=\"M180 45 L200 45\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"204\" y=\"32\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"227\" y=\"49\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">復元</text><text x=\"260\" y=\"49\" fill=\"#6ab08d\" font-size=\"14\">✓</text><text x=\"278\" y=\"49\" fill=\"#8892a4\" font-size=\"8.5\">元データと完全一致</text><text x=\"10\" y=\"96\" fill=\"#c47070\" font-size=\"10\" font-weight=\"600\">非可逆圧縮</text><rect x=\"60\" y=\"82\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"83\" y=\"99\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">元データ</text><path d=\"M108 95 L128 95\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"132\" y=\"82\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.3\"/><text x=\"155\" y=\"94\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">圧縮</text><text x=\"155\" y=\"104\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"7\">(一部間引く)</text><path d=\"M180 95 L200 95\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arrow2)\"/><rect x=\"204\" y=\"82\" width=\"46\" height=\"26\" rx=\"3\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.3\"/><text x=\"227\" y=\"99\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">復元</text><text x=\"260\" y=\"99\" fill=\"#c47070\" font-size=\"14\">≈</text><text x=\"278\" y=\"99\" fill=\"#8892a4\" font-size=\"8.5\">近似（完全には戻らない）</text><text x=\"170\" y=\"138\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">写真や音声は非可逆で高圧縮率、文書やプログラムは可逆が必須</text><defs><marker id=\"arrow2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs></svg>", "opt": ["正解。可逆圧縮は圧縮前のデータを完全に復元できる方式であり、非可逆圧縮は一部の情報を切り捨てて高い圧縮率を得るため完全には復元できない方式である。", "不正解。可逆圧縮・非可逆圧縮とも用途は固定されておらず、文書や音声、画像など扱うデータの性質に応じてどちらを使うかが選ばれる。", "不正解。一般に非可逆圧縮のほうが情報を間引く分、可逆圧縮より高い圧縮率を得やすい。説明が逆になっている。", "不正解。可逆圧縮は情報を間引かずに完全復元できるように圧縮する方式であり、人間の感覚をもとに情報を間引くのは非可逆圧縮の特徴である。"]}'),

  ('ap-core-q162', 'ヒューマンインタフェースとマルチメディア',
   '静止画像のファイル形式に関する説明のうち、適切なものはどれか。',
   NULL::text,
   '["JPEGは、写真などの自然画像を対象に非可逆圧縮を用いる形式であり、圧縮率を高めるほど画質が劣化する", "GIFは、圧縮方式に非可逆圧縮を採用しており、写真のような自然画像でも色数を無制限に保持できる形式である", "PNGは、圧縮方式に可逆圧縮を用いる形式だが、ファイルを保存し直すたびに画質が少しずつ劣化していく形式である", "JPEGは、圧縮方式に可逆圧縮を用いる形式であるため、ファイルを何度保存し直しても画質はまったく劣化しない"]',
   0,
   '[0]',
   'single',
   '{"asked": "JPEG・PNG・GIFといった静止画形式の圧縮方式に関する正しい理解を問う設問。", "point": "「JPEG=非可逆・写真向け」「PNG/GIF=可逆」という対応を押さえれば見分けられる。", "kid": "JPEGは写真をぎゅっと小さくする代わりに画質が少し落ちる形式、PNGは画質を落とさずに圧縮する形式。", "eg": "JPEGはジュースを凝縮還元するようなもので、体積は小さくなるが元の風味の一部は失われる。PNGは真空パックのように、体積は小さくしても中身の風味はそのまま保たれる。", "terms": [["JPEG", "写真など自然画像向けの非可逆圧縮形式。圧縮率を上げるほど画質が劣化する"], ["PNG", "可逆圧縮で画質を落とさない形式。イラストや文字を含む画像に向く"], ["GIF", "可逆圧縮だが色数が最大256色に制限される形式"]], "think": "なぜ画像形式によって可逆・非可逆を使い分けるのかがカギ。写真のような自然画像は色の階調が非常に多く、そのまま保存すると容量が大きい。人間の目は色のわずかな違いに気づきにくいため、JPEGは非可逆圧縮で情報を間引き大幅に容量を減らす。一方、文字やイラスト、図表は輪郭のにじみや色の変化が目立ちやすいため、PNGのように可逆圧縮で画質を保つ形式が向く。目的が写真か図表かによって適した圧縮方式が変わる。", "vs": "「可逆圧縮だから画質は劣化しない」PNGと、「非可逆圧縮だから圧縮するほど劣化する」JPEGの取り違えに注意。", "why_asked": "各形式の圧縮方式(可逆/非可逆)と特徴を入れ替えて出題されやすい。", "opt": ["正解。JPEGは写真などの自然画像を対象とした非可逆圧縮形式であり、圧縮率を高める(ファイルを小さくする)ほど画質が劣化する。", "不正解。GIFは可逆圧縮の形式だが、扱える色数は最大256色に制限されており、写真の色数を無制限に保持できるわけではない。", "不正解。PNGは可逆圧縮の形式であり、保存し直しても情報が失われないため画質は劣化しない。", "不正解。JPEGは非可逆圧縮の形式であり、保存し直すたびに圧縮処理が重なって画質が劣化していく。"]}'),

  ('ap-core-q163', 'ヒューマンインタフェースとマルチメディア',
   '動画データの圧縮において、直前や直後のフレームとの差分だけを符号化することで、フレームごとに全ての画素情報を記録するより大幅にデータ量を減らす技術を何というか。',
   NULL::text,
   '["フレーム間予測(差分符号化)", "標本化", "量子化", "ハミング符号化"]',
   0,
   '[0]',
   'single',
   '{"asked": "動画圧縮において、前後のフレームとの差分だけを記録する技術の名称を問う設問。", "point": "「前後のフレームとの差分だけを記録する」という説明があれば、フレーム間予測(差分符号化)だと見分けられる。", "kid": "動画は1秒間に何十枚もの画像(フレーム)の集まり。フレーム間予測は、前のフレームと変わっていない部分は記録せず、変化した部分だけを記録して容量を減らす工夫。", "eg": "パラパラ漫画で、背景がほとんど同じページが続くなら、毎回背景を描き直さず「前のページと同じ」とだけ書いて、動いた人物の部分だけ描き直すようなもの。", "terms": [["フレーム", "動画を構成する1枚1枚の静止画"], ["動き補償", "前のフレームのどの部分がどちらに動いたかを推定し、差分をさらに小さくする技術"]], "think": "なぜ動画はフレームごとに全部を記録せず差分だけを記録するのかがカギ。動画は静止画を高速に切り替えて見せているだけなので、隣り合うフレームどうしは背景など変化しない部分が多い。フレームごとに画素をすべて記録すると同じ情報を何度も繰り返し記録することになり、データ量が膨大になる。変化した部分だけを記録すれば、繰り返しの記録を省ける分、大幅にデータ量を減らせる。これが動画圧縮でフレーム間の差分に注目する理由。", "vs": "1枚の静止画の中の情報を間引く静止画圧縮と、フレームとフレームの間の変化に注目するフレーム間予測を混同しないこと。", "why_asked": "動画圧縮がなぜ静止画の圧縮より高い圧縮率を出せるのか、その仕組みを問う出題の基礎になる。", "opt": ["正解。直前や直後のフレームと比べて変化した部分だけを記録することで、フレームごとに全画素を記録するより大幅にデータ量を減らす技術である。", "不正解。標本化はアナログ信号を一定間隔で値として取り出す処理であり、フレーム間の差分を記録する動画圧縮の技術とは異なる。", "不正解。量子化は取り出した値を段階に丸める処理であり、フレーム間の差分を記録する動画圧縮の技術とは異なる。", "不正解。ハミング符号化はデータの誤りを検出・訂正するための符号化技術であり、動画のデータ量を減らす圧縮技術とは目的が異なる。"]}'),

  ('ap-core-q164', 'ヒューマンインタフェースとマルチメディア',
   '動画像圧縮に関する国際標準規格群であるMPEGの説明として、適切なものはどれか。',
   NULL::text,
   '["MPEG-1やMPEG-2など、用途や目的ごとに複数の規格が存在し、蓄積メディア向けやデジタル放送向けなど対象が異なる", "MPEGは特定の1つの圧縮アルゴリズムのみを指す名称であり、用途や目的によって規格が複数に分かれることはない", "MPEGは静止画像の圧縮を目的として策定された規格の名称であり、動画像の圧縮には一切利用されていない", "MPEGは可逆圧縮の技術のみを対象とした規格であり、動画圧縮に非可逆圧縮の技術が含まれることはない"]',
   0,
   '[0]',
   'single',
   '{"asked": "動画圧縮の国際標準規格であるMPEGの位置づけを問う設問。", "point": "MPEGは1つの規格ではなく、目的別に複数の規格が並ぶ「規格群」だと押さえれば見分けられる。", "kid": "MPEGとは、動画や音声を圧縮するための国際規格のシリーズ名。CD向け、DVD向け、ネット配信向けなど、目的ごとに番号違いの規格がいくつも存在する。", "eg": "MPEGは1つの道具ではなく、用途別に作られた工具セットのようなもの。CD-ROM向けの小さな動画にはMPEG-1、DVDや地上デジタル放送のような高画質にはMPEG-2、スマートフォンやインターネット配信のような低いビットレート向けにはMPEG-4というように、用途に応じて選ぶ規格が違う。", "terms": [["MPEG-1", "CD-ROMなど蓄積メディア向けの規格。ビデオCDなどで使われた"], ["MPEG-2", "DVDやデジタル放送向けの、より高画質・高ビットレートの規格"], ["MPEG-4", "携帯端末やインターネット配信など、低いビットレートでの伝送を目的とした規格"]], "think": "なぜMPEGが単一の規格でなく複数に分かれているのかがカギ。CD-ROMの再生、DVDやテレビ放送、スマートフォンでのネット動画視聴では、扱える通信速度や求められる画質がまったく異なる。1つの圧縮方式ですべての用途に最適な結果を出すことは難しいため、蓄積メディア向けのMPEG-1、放送向けのMPEG-2、低ビットレート配信向けのMPEG-4というように、用途ごとに規格を分けて最適化している。そのためMPEGは単一規格ではなく規格群として理解する必要がある。", "vs": "静止画像の圧縮規格であるJPEGと、動画像圧縮の規格群であるMPEGを混同しないこと。", "why_asked": "MPEGを単一の圧縮方式だと誤解していないか、規格群であることを理解しているかを問う定番の出題。", "opt": ["正解。MPEGは単一の規格ではなく、蓄積メディア向けのMPEG-1、デジタル放送向けのMPEG-2など、用途や目的ごとに複数の規格が並ぶ規格群である。", "不正解。MPEGは単一のアルゴリズムではなく、用途ごとに最適化された複数の規格からなる規格群である。", "不正解。MPEGは動画像圧縮の規格群であり、静止画像の圧縮を目的とした規格はJPEGなど別に存在する。", "不正解。MPEGの動画圧縮には非可逆圧縮の技術が用いられており、可逆圧縮のみを対象とした規格ではない。"]}'),

  ('ap-core-q165', 'ヒューマンインタフェースとマルチメディア',
   '色を「色相」「彩度」「明度」の3要素で表す方式に関する説明のうち、適切なものはどれか。',
   NULL::text,
   '["色相は赤や青といった色合いの種類、彩度は色の鮮やかさの度合い、明度は色の明るさの度合いを表す", "色相は色の明るさの度合い、彩度は色合いの種類、明度は色の鮮やかさの度合いを表す", "彩度は色合いの種類、明度は色の鮮やかさの度合い、色相は色の明るさの度合いを表す", "色相・彩度・明度はいずれも色の明るさを異なる尺度で表したものであり、実質的に同じ情報を表す"]',
   0,
   '[0]',
   'single',
   '{"asked": "色相・彩度・明度という3つの用語がそれぞれ何を表すかを問う設問。", "point": "「色相=色合い」「彩度=鮮やかさ」「明度=明るさ」の対応をセットで覚えれば、入れ替え選択肢に引っかからない。", "kid": "色相・彩度・明度は、色を3つの物差しで表す考え方。何色か(色相)、どれくらい鮮やかか(彩度)、どれくらい明るいか(明度)を別々に指定する。", "eg": "絵の具にたとえると、色相は「赤」「青」といった絵の具の種類、彩度はその絵の具に混ぜる灰色の少なさ(混ぜるほど鮮やかさが落ちる)、明度は照明を当てたときの明るさに近い。同じ「赤」でも、鮮やかな赤とくすんだ赤、明るい赤と暗い赤は別物として表せる。", "terms": [["色相(Hue)", "赤・青・緑といった色合いの種類。環状に並べて色相環として表すことが多い"], ["彩度(Saturation)", "色の鮮やかさの度合い。低いほど灰色に近づく"], ["明度(Value/Brightness)", "色の明るさの度合い。低いほど黒に近づく"]], "think": "なぜ色を3つの要素に分けて表すのかがカギ。色を「何色か」だけで表すと、鮮やかな赤とくすんだ赤、明るい赤と暗い赤を区別できない。色合い(色相)と鮮やかさ(彩度)と明るさ(明度)を別の軸として独立に指定できるようにすることで、無数にある色のバリエーションを漏れなく言い表せる。3つの物差しが独立しているからこそ、色相を変えずに彩度だけ落とす、といった調整も自在にできる。", "vs": "RGB(赤緑青の光の三原色を混ぜて色を作る方式)と混同しないこと。色相・彩度・明度は人の感覚に近い形で色を表す方式である。", "why_asked": "3つの用語の意味を入れ替えて出題されることが多い。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">色相・彩度・明度の3要素</text><path d=\"M105,78 L105.0,26.0 A52,52 0 0,1 141.8,41.2 Z\" fill=\"#c0392b\" opacity=\"0.85\"/><path d=\"M105,78 L141.8,41.2 A52,52 0 0,1 157.0,78.0 Z\" fill=\"#c9a04a\" opacity=\"0.85\"/><path d=\"M105,78 L157.0,78.0 A52,52 0 0,1 141.8,114.8 Z\" fill=\"#8aa04a\" opacity=\"0.85\"/><path d=\"M105,78 L141.8,114.8 A52,52 0 0,1 105.0,130.0 Z\" fill=\"#4aa088\" opacity=\"0.85\"/><path d=\"M105,78 L105.0,130.0 A52,52 0 0,1 68.2,114.8 Z\" fill=\"#4a80c9\" opacity=\"0.85\"/><path d=\"M105,78 L68.2,114.8 A52,52 0 0,1 53.0,78.0 Z\" fill=\"#5a5ac9\" opacity=\"0.85\"/><path d=\"M105,78 L53.0,78.0 A52,52 0 0,1 68.2,41.2 Z\" fill=\"#8a4ac0\" opacity=\"0.85\"/><path d=\"M105,78 L68.2,41.2 A52,52 0 0,1 105.0,26.0 Z\" fill=\"#c04a8a\" opacity=\"0.85\"/><circle cx=\"105\" cy=\"78\" r=\"52\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><path d=\"M105 78 L105 26\" stroke=\"#e8eaf0\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><text x=\"105\" y=\"144\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">色相（環状に配置）</text><text x=\"105\" y=\"82\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"8\">彩度：中心→外側</text><rect x=\"205\" y=\"30\" width=\"18\" height=\"96\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"206\" y=\"31\" width=\"16\" height=\"30\" fill=\"#e8eaf0\"/><rect x=\"206\" y=\"61\" width=\"16\" height=\"34\" fill=\"#8892a4\"/><rect x=\"206\" y=\"95\" width=\"16\" height=\"30\" fill=\"#2a2f3f\"/><text x=\"214\" y=\"140\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">明度</text><text x=\"214\" y=\"24\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"8\">明るい</text><text x=\"290\" y=\"60\" fill=\"#8892a4\" font-size=\"8.5\">色相＝色合い</text><text x=\"290\" y=\"76\" fill=\"#8892a4\" font-size=\"8.5\">彩度＝鮮やかさ</text><text x=\"290\" y=\"92\" fill=\"#8892a4\" font-size=\"8.5\">明度＝明るさ</text></svg>", "opt": ["正解。色相は色合いの種類、彩度は色の鮮やかさの度合い、明度は色の明るさの度合いをそれぞれ表す。", "不正解。色相と彩度と明度の説明が入れ替わっている。色相は色合いの種類、明度は明るさの度合いを表す。", "不正解。彩度と明度と色相の説明が入れ替わっている。彩度は鮮やかさの度合い、色相は色合いの種類を表す。", "不正解。色相・彩度・明度はそれぞれ別の情報(色合い・鮮やかさ・明るさ)を独立に表す3つの物差しであり、同じ情報の言い換えではない。"]}'),

  ('ap-core-q166', 'ヒューマンインタフェースとマルチメディア',
   'デジタル画像における「画素」と「解像度」に関する説明のうち、適切なものはどれか。',
   NULL::text,
   '["画素は画像を構成する最小単位であり、解像度は単位長さあたりの画素の密度を表す", "画素は単位長さあたりの画素の密度を表し、解像度は画像を構成する最小単位を表す", "解像度が高いほど、同じ画素数の画像でもファイルサイズは必ず小さくなる", "画素数が同じであれば、印刷するサイズを変えても見た目の精細さは常に同じである"]',
   0,
   '[0]',
   'single',
   '{"asked": "「画素」と「解像度」という2つの用語がそれぞれ何を表すかを問う設問。", "point": "「画素=最小単位のマス目」「解像度=そのマス目の密度」という対応を押さえれば見分けられる。", "kid": "画素とは画像を作っている小さな四角い点1つ1つのこと。解像度は、その点が単位長さあたりにどれくらい細かく詰まっているかを表す指標。", "eg": "モザイクアートにたとえると、1枚1枚のタイルが画素、同じ大きさの壁にタイルをどれだけ細かく敷き詰めるかが解像度にあたる。タイルを細かく敷き詰めるほど、遠目に見たときの絵がなめらかに見える。", "terms": [["画素(ピクセル)", "デジタル画像を構成する最小単位の点"], ["解像度", "単位長さあたりに画素がどれだけ密に並んでいるかを表す指標。dpiやppiという単位で表すことが多い"]], "think": "なぜ画素数だけでなく解像度という指標も必要なのかがカギ。同じ画素数の画像でも、小さいサイズに印刷するか大きいサイズに引き伸ばして印刷するかで、単位長さあたりに詰まる画素の密度は変わる。密度が高いほど点と点の継ぎ目が見えにくくなめらかに見え、密度が低いほど1つ1つの点(モザイク)が目立ってしまう。画素数という総量の情報だけでは「どれだけ精細に見えるか」までは分からないため、密度を表す解像度という指標を別に使う。", "vs": "画素数(総数)と解像度(密度)は別の指標であり、画素数が同じでも印刷サイズを変えれば解像度、つまり見た目の精細さは変わる。", "why_asked": "画素数と解像度を同じ意味だと取り違えていないかを問う出題が多い。", "opt": ["正解。画素は画像を構成する最小単位の点であり、解像度は単位長さあたりに画素がどれだけ密に並んでいるかを表す。", "不正解。画素と解像度の説明が入れ替わっている。画素は最小単位の点そのものであり、密度を表す指標ではない。", "不正解。解像度とファイルサイズの関係は一概には決まらず、解像度が高いほど記録する情報量が増えファイルサイズが大きくなる場合が多い。", "不正解。画素数が同じでも印刷するサイズを大きくすれば単位長さあたりの画素の密度が下がり、見た目の精細さは低下する。"]}'),

  ('ap-core-q167', 'ヒューマンインタフェースとマルチメディア',
   'コンピュータグラフィックス(CG)における画像の表現方式に関する説明のうち、適切なものはどれか。',
   NULL::text,
   '["ラスタ形式は画素の集まりで画像を表現するのに対し、ベクタ形式は図形を数式や座標などの情報で表現する", "ラスタ形式は図形を数式や座標で表現するのに対し、ベクタ形式は画素の集まりで画像を表現する", "ラスタ形式・ベクタ形式のどちらも、拡大しても画質が劣化しない点で共通している", "ベクタ形式は写真のような自然画像を扱うのに適しており、ラスタ形式はイラストや図形を扱うのに適している"]',
   0,
   '[0]',
   'single',
   '{"asked": "ラスタ形式とベクタ形式という2つの画像表現方式の違いを問う設問。", "point": "「画素の集まり=ラスタ」「数式・座標=ベクタ」という対応と、「ベクタは拡大しても輪郭が劣化しない」という性質を押さえれば見分けられる。", "kid": "ラスタ形式は小さな点(画素)を並べて絵を表す方式、ベクタ形式は「ここからここまで直線」「中心と半径でこの円」のように図形を数式で表す方式。", "eg": "ラスタ形式は方眼紙のマス目を1つずつ塗って絵を描くようなもので、拡大するとマス目のギザギザが目立つ。ベクタ形式は「半径3cmの円をここに描け」という指示書のようなもので、どれだけ拡大してもその指示に従って描き直すだけなので輪郭がなめらかなまま保たれる。", "terms": [["ラスタ形式", "画素(点)の集まりで画像を表現する方式。写真の表現に向く"], ["ベクタ形式", "図形を座標や数式(直線・曲線・円など)で表現する方式。拡大縮小してもなめらかさを保てるためロゴや図形の表現に向く"]], "think": "なぜ拡大したときの劣化のしかたが方式によって違うのかがカギ。ラスタ形式は決まった数の画素をあらかじめ並べて絵を作っているため、拡大すると1つ1つの画素が大きく引き伸ばされ、輪郭がギザギザに見えてしまう。ベクタ形式は画素をあらかじめ並べるのではなく「この座標からこの座標まで線を引け」という指示を保持しているため、拡大するときはその指示をもとに改めて描き直すだけで済み、輪郭のなめらかさが保たれる。この仕組みの違いが、拡大耐性の違いを生む。", "vs": "写真のような自然画像はラスタ形式、ロゴや図形のようなくっきりした輪郭が必要なものはベクタ形式が向くという使い分けを取り違えないこと。", "why_asked": "ラスタとベクタの特徴を入れ替えて出題されることが多い。", "opt": ["正解。ラスタ形式は画素の集まりで画像を表現し、ベクタ形式は図形を座標や数式などの情報で表現する。", "不正解。ラスタ形式とベクタ形式の説明が入れ替わっている。数式や座標で図形を表現するのはベクタ形式である。", "不正解。ラスタ形式は拡大すると画素が引き伸ばされて輪郭がギザギザに見えるため、拡大しても劣化しないのはベクタ形式の特徴である。", "不正解。写真のような自然画像を扱うのに適しているのはラスタ形式であり、イラストや図形に適しているのはベクタ形式であるため、説明が逆になっている。"]}'),

  ('ap-core-q168', 'ヒューマンインタフェースとマルチメディア',
   'XR(クロスリアリティ)に含まれるVR・AR・MRに関する説明のうち、適切なものはどれか。',
   NULL::text,
   '["VRは利用者を現実から切り離し仮想空間に没入させる技術であり、ARは現実の映像に仮想の情報を重ねて表示する技術である", "VRは現実の映像に仮想の情報を重ねて表示する技術であり、ARは利用者を現実から切り離し仮想空間に没入させる技術である", "MRは仮想空間のみで構成され、現実の映像を一切含まない技術である", "VR・AR・MRはいずれも同じ技術を指す別名であり、実質的な違いはない"]',
   0,
   '[0]',
   'single',
   '{"asked": "VR・AR・MRという3つの技術の違いを問う設問。", "point": "「現実を遮断して仮想に入り込む=VR」「現実に情報を重ねる=AR」という対応で見分けられる。", "kid": "VRはゴーグルなどで視界を仮想世界に置き換えてしまう技術、ARはスマホのカメラ越しの現実の映像に、仮想のキャラクターなどの情報を重ねて表示する技術。", "eg": "VRは目隠しをして完全に別の部屋(仮想空間)に入り込むようなもの。ARは今いる部屋はそのままに、メガネの表面にだけ付箋(仮想の情報)を貼り付けて見せるようなもの。", "terms": [["VR(仮想現実)", "利用者の視界を仮想空間の映像に置き換え、現実から切り離して没入させる技術"], ["AR(拡張現実)", "現実の映像はそのままに、仮想の情報を重ねて表示する技術"], ["MR(複合現実)", "現実の空間と仮想の物体が、位置関係を保ちながら互いに影響し合う技術"]], "think": "なぜVR・AR・MRを分けて呼ぶのかがカギ。それぞれ「現実をどれだけ残すか」が異なる。VRは現実の視界を完全に仮想映像へ置き換えるので、利用者は仮想空間だけに没入する。ARは現実の映像を土台にしたまま、その上に仮想の情報を追加で重ねるだけなので、現実と情報が別々のレイヤーとして存在する。MRはさらに進んで、仮想の物体が現実の机や壁の位置を認識し、あたかもそこに実在するかのように現実と干渉し合う。現実をどれだけ残し、仮想とどう関わらせるかという度合いの違いが、3つの呼び名を分ける理由になっている。", "vs": "ARは現実に情報を重ねるだけで仮想物体は現実と干渉しないのに対し、MRは仮想物体が現実の物体の位置や動きを認識して干渉する点で異なる。", "why_asked": "VR・AR・MRの定義を入れ替えて出題されることが多く、現実をどの程度残すかという軸で整理できているかが問われる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">現実と仮想の関係で見るVR・AR・MR</text><line x1=\"30\" y1=\"75\" x2=\"310\" y2=\"75\" stroke=\"#2a2f3f\" stroke-width=\"2\"/><circle cx=\"30\" cy=\"75\" r=\"4\" fill=\"#6ab08d\"/><text x=\"30\" y=\"98\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">現実</text><text x=\"30\" y=\"110\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"7.5\">(現実の空間のみ)</text><circle cx=\"130\" cy=\"75\" r=\"4\" fill=\"#60a5fa\"/><text x=\"130\" y=\"98\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">AR</text><text x=\"130\" y=\"110\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"7.5\">(現実に情報を重ねる)</text><circle cx=\"215\" cy=\"75\" r=\"4\" fill=\"#3b82f6\"/><text x=\"215\" y=\"98\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">MR</text><text x=\"215\" y=\"110\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"7.5\">(現実と仮想が影響し合う)</text><circle cx=\"310\" cy=\"75\" r=\"4\" fill=\"#c9a04a\"/><text x=\"310\" y=\"98\" text-anchor=\"middle\" fill=\"#e8eaf0\" font-size=\"9\">VR</text><text x=\"310\" y=\"110\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"7.5\">(仮想空間に没入)</text><text x=\"170\" y=\"135\" text-anchor=\"middle\" fill=\"#8892a4\" font-size=\"9\">右へ行くほど現実が占める割合が減り、仮想の割合が増える</text></svg>", "opt": ["正解。VRは利用者を現実から切り離し仮想空間に没入させる技術であり、ARは現実の映像に仮想の情報を重ねて表示する技術である。", "不正解。VRとARの説明が入れ替わっている。現実の映像に情報を重ねるのはAR、仮想空間に没入させるのはVRである。", "不正解。MRは現実の空間と仮想の物体が位置関係を保ちながら互いに影響し合う技術であり、現実の映像を含まないわけではない。", "不正解。VR・AR・MRは、現実をどれだけ残し仮想とどう関わらせるかという度合いがそれぞれ異なる別の技術であり、同じ技術の別名ではない。"]}'),

  ('ap-core-q169', 'ヒューマンインタフェースとマルチメディア',
   'XR(クロスリアリティ)という用語の説明として、適切なものはどれか。',
   NULL::text,
   '["VR・AR・MRなど、現実と仮想を融合させる技術群を包括的に指す総称である", "XRは、VR・AR・MRのいずれとも異なる、第4の独立した技術を指す固有の名称である", "XRは、仮想現実(VR)のみを指す別の呼び方であり、ARやMRは含まない", "XRは、メタバースと同じ意味を持つ言葉であり、3次元の仮想空間そのものを指す"]',
   0,
   '[0]',
   'single',
   '{"asked": "XR(クロスリアリティ)という用語が何を指すかを問う設問。", "point": "XRは新しい別技術ではなく、VR・AR・MRなどをまとめて呼ぶ「総称」だと押さえれば見分けられる。", "kid": "XRとは、VRやAR、MRといった、現実と仮想を組み合わせるいろいろな技術をまとめて呼ぶときの総称。", "eg": "「乗り物」という言葉が自動車・電車・自転車をまとめて指す総称であるのと同じように、XRはVR・AR・MRをまとめて指す総称であり、それ自体が個別の1つの技術というわけではない。", "terms": [["VR", "現実から切り離し仮想空間に没入させる技術"], ["AR", "現実に仮想の情報を重ねる技術"], ["MR", "現実と仮想の物体が互いに影響し合う技術"]], "think": "なぜVR・AR・MRとは別にXRという言葉が使われるのかがカギ。VR・AR・MRはそれぞれ現実をどれだけ残すかという度合いが異なる別々の技術だが、いずれも現実の世界と仮想の情報や空間を組み合わせて体験を作るという点では共通している。技術ごとに個別に説明するのではなく、この共通点をまとめて呼びたいときに使う総称がXRである。新しい第4の技術が存在するわけではなく、あくまで呼び方の整理のための言葉である。", "vs": "3次元の仮想空間で人がアバターを介して交流する概念である「メタバース」と、技術の総称である「XR」を混同しないこと。", "why_asked": "XRを独立した1つの技術だと誤解していないかを問う出題。", "opt": ["正解。XRは、VR・AR・MRなど、現実と仮想を融合させる技術群をまとめて指す総称である。", "不正解。XRはVR・AR・MRとは別の第4の技術ではなく、それらをまとめて呼ぶための総称である。", "不正解。XRはVRだけでなくAR・MRも含む総称であり、VRのみを指す別名ではない。", "不正解。XRは技術の総称であり、3次元の仮想空間内での交流や活動という考え方を指すメタバースとは意味が異なる。"]}'),

  ('ap-core-q170', 'ヒューマンインタフェースとマルチメディア',
   '「メタバース」の考え方に関する説明として、適切なものはどれか。',
   NULL::text,
   '["インターネット上に構築された3次元の仮想空間で、利用者がアバターを介して他の利用者と交流したり活動したりする概念", "スマートフォンのカメラなどを通して見た現実の映像に、仮想の情報をリアルタイムに重ねて表示する技術そのものを指す言葉である", "従来より高精細な2次元の画像や動画をインターネット経由で配信する技術そのものを指す言葉である", "ある特定の1つのオンラインゲームだけに使われる固有名詞であり、他のサービスや分野では用いられない言葉である"]',
   0,
   '[0]',
   'single',
   '{"asked": "「メタバース」という言葉が何を指す考え方かを問う設問。", "point": "「3次元の仮想空間」「アバターを介した交流・活動」の2点がそろっていればメタバースだと見分けられる。", "kid": "メタバースとは、インターネットの中にある3次元の仮想の世界で、自分の分身(アバター)を使って他の人と会話したり活動したりできる、という考え方。", "eg": "テレビ電話が「画面越しに顔を見て話す」ものだとすると、メタバースは「3次元の街に自分のアバターで実際に足を運び、そこにいる他の人のアバターと隣り合って会話する」ようなもの。単に映像を見るのではなく、仮想空間の中に自分がいる感覚を伴う。", "terms": [["アバター", "仮想空間の中で利用者の分身として動くキャラクターや姿"], ["VR", "メタバースに没入するための代表的な入り口の1つとなる技術。ゴーグルなどで視界を仮想空間に置き換える"]], "think": "なぜメタバースはVRなどの技術そのものとは別の概念として説明されるのかがカギ。VRやARは仮想空間や情報を「どう表示するか」という技術の話であるのに対し、メタバースは「その仮想空間の中で人々がどう交流し活動するか」という空間や社会の在り方についての話である。VRゴーグルを使わずパソコンの画面越しにアバターを操作してメタバースに参加することもできるため、メタバースは特定の表示技術に縛られる概念ではなく、3次元の仮想空間とそこでの活動という考え方そのものを指す。", "vs": "表示の仕組みを指すVR・ARと、仮想空間内での交流・活動という考え方を指すメタバースを混同しないこと。", "why_asked": "メタバースをVRやARと同じ「技術」だと取り違えていないかを問う出題。", "opt": ["正解。インターネット上に構築された3次元の仮想空間で、利用者がアバターを介して他の利用者と交流したり活動したりする概念である。", "不正解。これは拡張現実(AR)の説明であり、仮想空間内での交流・活動という考え方を指すメタバースとは異なる。", "不正解。メタバースは3次元の仮想空間という考え方を指す言葉であり、2次元の画像や動画配信の技術を指す言葉ではない。", "不正解。メタバースは特定の1つのサービスの固有名詞ではなく、3次元の仮想空間で交流・活動するという考え方を指す一般的な概念である。"]}')
) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q171', 'セキュリティ実装技術',
   'Webアプリケーションがデータベースへ問い合わせを行う際、SQL文の雛形とパラメータ(バインド変数)を分けてデータベースに渡す方式が、入力値をそのままSQL文の文字列につなぎ合わせる方式に比べてSQLインジェクション対策として優れている理由として、最も適切なものはどれか。',
   NULL::text,
   '["SQL文の構文が先に確定してから値が当てはめられるため、入力された文字列がSQL文の一部(命令)として解釈されることがなくなるから", "パラメータの値をあらかじめ暗号化したうえでデータベースへ送信する仕組みになっているため、通信経路上での盗聴を防げるから", "データベースサーバーへの問い合わせにかかる処理時間がその分だけ短縮されることで、攻撃者が付け入るすきそのものが少なくなっていくから", "パラメータに使える文字の種類をあらかじめ英数字のみに制限する仕組みが、データベース側で自動的に働くようになるから"]',
   0,
   '[0]',
   'single',
   '{"asked": "バインド変数を使う方式が文字列連結よりSQLインジェクション対策として優れている理由を問う設問。", "point": "値の中身が何であっても、SQL文の『構造』は先に確定していて、入力は最後まで『値』としてしか扱われない、がバインド変数の効くしくみ。", "kid": "バインド変数は『命令の雛形』と『そこに入れる値』を最初から別々にデータベースへ渡す方法。値の中に変な文字が混じっていても、それは値としてしか扱われない。", "eg": "銀行の振込用紙にたとえられる。用紙には『金額』『振込先』という欄があらかじめ印刷されていて、記入者がそこに何を書いても、用紙そのものの意味(振込の指示という構造)は変わらない。文字列連結は、白紙に自由に文章を書かせて、その中から機械が『命令』を読み取ろうとするようなもの。書き方次第で命令の意味が変わってしまう。", "terms": [["SQLインジェクション", "入力欄に不正なSQLの断片を混ぜ込み、データベースに想定外の命令を実行させる攻撃"], ["バインド変数(プレースホルダ)", "SQL文の中で値が入る場所を記号で仮に空けておき、後から実際の値を安全に当てはめる仕組み"], ["文字列連結", "入力値をそのままSQL文の文字列につなぎ合わせて組み立てる、危険な実装方法"]], "think": "なぜ雛形と値を分けて渡すだけで攻撃を防げるのかがカギ。文字列連結では、入力値がSQL文というひとつながりの文章の一部になってしまうため、入力値の中にクォート記号など特別な意味を持つ文字が含まれていると、データベースはそれをSQL文の『構造』の一部と誤って読み取ってしまう。ここに攻撃者が『元の命令を書き換える文字列』を仕込むのがSQLインジェクションである。一方バインド変数は、SQL文の構造(どのテーブルの何を検索するか)を先にデータベースへ渡して確定させ、値はその後から別経路で渡す。データベース側は『ここは値が入る場所』とすでに認識しているため、値の中にどんな文字が混じっていても、それをSQL文の構造として解釈し直すことはない。だから値がそのまま命令に化けることがなくなる。", "why_asked": "バインド変数の効果を『処理が速いから』『暗号化しているから』といった見当違いの理由と混同していないかを問う定番の切り口。", "vs": "エスケープ処理(特殊文字を別の表現に置き換える対症療法)と違い、バインド変数はSQL文の構造と値を最初から分離するという、より構造的な対策である点が異なる。", "opt": ["正解。SQL文の構造が先に確定し、入力値は最後まで値として扱われるため、値の中身がSQL文の命令として解釈されることがなくなる。", "バインド変数の目的は通信の暗号化ではない。値をSQL文の構造から分離することが目的であり、盗聴対策とは別の話である。", "バインド変数を使う主な動機は同じ雛形のSQL文を繰り返し使う際の処理効率化にも触れられることがあるが、SQLインジェクション対策としての本質は処理速度ではなく値と構造の分離にある。", "バインド変数は値に使える文字種を制限する仕組みではない。どんな文字が入っていても、それを構造として解釈しないという点が対策の核心である。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">文字列連結とバインド変数の違い</text>\n<text x=\"12\" y=\"34\" fill=\"#c47070\" font-size=\"8.5\" font-weight=\"600\">文字列連結(危険)</text>\n<rect x=\"10\" y=\"40\" width=\"88\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#c47070\"/>\n<text x=\"54\" y=\"55\" fill=\"#e8eaf0\" font-size=\"7.8\" text-anchor=\"middle\">SQL文の雛形</text>\n<text x=\"102\" y=\"56\" fill=\"#c47070\" font-size=\"12\" text-anchor=\"middle\">+</text>\n<rect x=\"108\" y=\"40\" width=\"90\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#c47070\"/>\n<text x=\"153\" y=\"55\" fill=\"#e8eaf0\" font-size=\"7.8\" text-anchor=\"middle\">入力値(そのまま)</text>\n<text x=\"203\" y=\"56\" fill=\"#c47070\" font-size=\"11\" text-anchor=\"middle\">&#8594;</text>\n<rect x=\"210\" y=\"40\" width=\"120\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#c47070\"/>\n<text x=\"270\" y=\"50\" fill=\"#c47070\" font-size=\"7.5\" text-anchor=\"middle\">1本のSQL文として</text>\n<text x=\"270\" y=\"60\" fill=\"#c47070\" font-size=\"7.5\" text-anchor=\"middle\">そのまま実行(命令化)</text>\n<text x=\"12\" y=\"86\" fill=\"#6ab08d\" font-size=\"8.5\" font-weight=\"600\">バインド変数(安全)</text>\n<rect x=\"10\" y=\"92\" width=\"88\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#3b82f6\"/>\n<text x=\"54\" y=\"107\" fill=\"#e8eaf0\" font-size=\"7.8\" text-anchor=\"middle\">SQL文の雛形</text>\n<text x=\"102\" y=\"103\" fill=\"#3b82f6\" font-size=\"7\" text-anchor=\"middle\">先に</text>\n<text x=\"102\" y=\"112\" fill=\"#3b82f6\" font-size=\"7\" text-anchor=\"middle\">確定</text>\n<rect x=\"108\" y=\"92\" width=\"90\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#3b82f6\"/>\n<text x=\"153\" y=\"107\" fill=\"#e8eaf0\" font-size=\"7.8\" text-anchor=\"middle\">入力値(値のまま)</text>\n<text x=\"203\" y=\"108\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\">&#8594;</text>\n<rect x=\"210\" y=\"92\" width=\"120\" height=\"24\" rx=\"3\" fill=\"#2a2f3f\" stroke=\"#6ab08d\"/>\n<text x=\"270\" y=\"102\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">構造は確定済み</text>\n<text x=\"270\" y=\"112\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">値は値のまま扱う</text>\n<text x=\"170\" y=\"136\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">雛形と値を最初から分けて渡すため、値がどんな文字でも命令にはならない</text>\n</svg>"}'),
  ('ap-core-q172', 'セキュリティ実装技術',
   '業務システムのアプリケーションがデータベースに接続する際に使うデータベースアカウントの権限設定として、最も適切なものはどれか。',
   NULL::text,
   '["そのアプリケーションが実際に使うテーブルに対し、必要な操作(参照・追加・更新など)だけを許可し、テーブルの削除やアカウント管理などの権限は与えない", "運用中に発生しうるトラブルへ素早く対応できるようにするため、データベース管理者と同じ全テーブル・全操作の権限をアプリケーション用アカウントにもあらかじめ与えておく", "パスワードを十分に複雑なものにしておく代わりとして、権限の範囲は特に絞り込まずデータベース内の全テーブルへのアクセスを一律に許可しておく", "アプリケーションのソースコードにアカウント情報を直接書き込まないようにする工夫の代わりに、権限そのものはデータベース管理者と同等の水準にしておく"]',
   0,
   '[0]',
   'single',
   '{"asked": "アプリケーション用のデータベースアカウントに、どこまでの権限を与えるべきかを問う設問。", "point": "そのアプリケーションが業務上実際に必要とする最小限の操作だけを許可する『最小権限の原則』が決め手。管理者相当の権限は与えない。", "kid": "アプリ用のアカウントには、そのアプリが本当に使う分だけの権限を与える。何でもできる万能アカウントにはしない。", "eg": "アルバイトスタッフに渡す鍵にたとえられる。レジと在庫室の鍵だけ渡せば業務は回るのに、店の金庫や本部の鍵まで渡してしまうと、そのスタッフの鍵が盗まれたときに店全体が危険にさらされる。渡す鍵は業務に必要な分だけにする。", "terms": [["最小権限の原則", "利用者やプログラムには、業務に必要な最小限の権限だけを与えるという考え方"], ["DBA(データベース管理者)権限", "テーブルの作成・削除やアカウント管理など、データベース全体を操作できる強い権限"]], "think": "なぜ権限を絞り込む必要があるのかがカギ。アプリケーションには脆弱性が見つかることがあり、攻撃者に侵入された場合、攻撃者はそのアプリケーションが使っているデータベースアカウントの権限をそのまま引き継いで悪用できる。もしそのアカウントがデータベース管理者と同等の強い権限を持っていたら、攻撃者は本来のアプリケーションが触れる範囲を超えて、他の業務のテーブルを削除したり、新しい管理者アカウントを作って居座ったりできてしまう。逆に権限が参照・追加・更新など必要最小限に絞られていれば、たとえ侵入されても被害はその範囲にとどまる。だから、実際に使う操作だけを許可し、それ以外の権限は最初から与えない。", "why_asked": "『運用の利便性』や『パスワードの強度』を理由に権限を絞らない発想が誤りであることを問う。", "vs": "パスワードを強くすることと権限を絞ることは別の対策であり、どちらか一方で足りるものではない。パスワードが破られた場合の被害を抑えるためにも権限の絞り込みは必要。", "opt": ["正解。実際に使う操作だけを許可し、テーブル削除やアカウント管理のような不要な強い権限は与えないのが最小権限の原則にかなう。", "運用の利便性を理由に管理者相当の権限を与えると、アプリケーションが侵害された際の被害がデータベース全体に及んでしまう。", "パスワードの強度と権限の範囲は別の対策であり、権限を絞らない理由にはならない。侵害の起点はパスワード漏えいに限らない。", "アカウント情報を直接書き込まないことは別の良い実践だが、それと権限の強さは無関係であり、管理者と同等の権限を正当化する理由にはならない。"]}'),
  ('ap-core-q173', 'セキュリティ実装技術',
   'SQLインジェクション対策として、入力値中の特殊文字を別の表現に置き換える「エスケープ処理」と、SQL文の雛形とパラメータを分離する「バインド変数」を比較した記述として、最も適切なものはどれか。',
   NULL::text,
   '["エスケープ処理は文字種の見落としや実装差によって防御漏れが起こり得るが、バインド変数は値とSQL文の構造を最初から分離するため安全性を確保しやすい", "エスケープ処理は処理速度が遅く古くから使われなくなった技術であるため、現在ではバインド変数だけがSQLインジェクション対策として広く認められている", "バインド変数は文字コードの変換にのみ有効に働く仕組みにすぎず、SQLインジェクションのような命令の書き換えそのものには効果を持たない", "エスケープ処理とバインド変数はどちらも通信経路そのものを暗号化するための仕組みであり、対策としての効果に本質的な違いは存在しない"]',
   0,
   '[0]',
   'single',
   '{"asked": "エスケープ処理とバインド変数、どちらがSQLインジェクション対策として安全性の面で優れているかを問う設問。", "point": "エスケープ処理は『対象文字を漏れなく置き換えられているか』に安全性が依存する対症療法。バインド変数は値とSQL文の構造を最初から分けるので、対象文字の見落とし自体が起こりにくい。", "kid": "エスケープ処理は危険な文字を後から無害な形に書き換える作業。バインド変数はそもそも値を命令の中に混ぜない仕組み。", "eg": "エスケープ処理は、危険物を紙に包んでから箱に入れるようなもの。包み方(対象文字の変換ルール)に漏れがあれば中身が箱の外に影響してしまう。バインド変数は、そもそも危険物と箱を別の経路で運び、現場で初めて組み合わせるようなもの。", "terms": [["エスケープ処理", "SQL文の中で特別な意味を持つ文字を、別の無害な表現に置き換える処理"], ["対象文字の見落とし", "データベース製品や文字コードの違いにより、本来変換すべき文字を変換し損ねてしまうこと"]], "think": "なぜバインド変数のほうが安全性を確保しやすいのかがカギ。エスケープ処理は『危険な文字をあらかじめ列挙し、漏れなく変換できていれば安全』という前提の上に成り立つ対策である。ところがデータベース製品や文字コードの組み合わせによって『特別な意味を持つ文字』の範囲が微妙に異なることがあり、実装者がその違いを見落とすと、変換されなかった文字がそのままSQL文の構造として読み取られてしまう。一方バインド変数は、変換すべき文字を列挙する必要がそもそもない。SQL文の構造をあらかじめ確定させ、値は後から別経路で渡すため、値の中にどんな文字があっても構造として読み取られることがない。だから、対象文字の見落としという弱点そのものを持たないバインド変数のほうが、より安全性を確保しやすい。", "why_asked": "どちらも『SQLインジェクション対策』という括りで語られがちなため、安全性の質に差があることを取り違えていないかを問う。", "vs": "どちらもSQLインジェクション対策として使われることがあるが、エスケープ処理は対象文字の変換漏れという弱点を抱えた対症療法である点がバインド変数と異なる。", "opt": ["正解。エスケープ処理は変換対象の見落としで防御が破られ得るが、バインド変数は値とSQL文の構造を最初から分離するため、より安全性を確保しやすい。", "エスケープ処理が『古い技術で使われなくなった』というのは誤り。バインド変数が使えない箇所で補助的に使われることもある。優劣は処理速度の話ではない。", "バインド変数はSQL文の構造そのものと値を分離する仕組みであり、文字コード変換に限定された機能ではない。SQLインジェクション対策そのものである。", "エスケープ処理もバインド変数も通信経路の暗号化を行う仕組みではない。どちらもSQL文の組み立て方に関する対策である。"]}'),
  ('ap-core-q174', 'セキュリティ実装技術',
   'Webアプリケーションで利用者からの入力値を検証する方式として、あらかじめ許可するパターンを定義しそれ以外を拒否する「ホワイトリスト方式」が、禁止するパターンを列挙する「ブラックリスト方式」より一般に安全とされる理由として、最も適切なものはどれか。',
   NULL::text,
   '["攻撃者が使う可能性のある危険な入力パターンをすべて事前に列挙することは難しいが、正常な入力の形式は業務上あらかじめ定義しやすいから", "ホワイトリスト方式を採用すると入力値の文字数が常に短くなる傾向があり、処理速度がブラックリスト方式より高速になりやすいから", "ブラックリスト方式は暗号化されていない通信のときにしか機能しない仕組みになっており、HTTPS通信では利用すること自体ができないから", "ホワイトリスト方式を導入すると、アプリケーションからデータベースへの問い合わせ回数そのものを減らすことができるようになるから"]',
   0,
   '[0]',
   'single',
   '{"asked": "入力値検証において、ホワイトリスト方式がブラックリスト方式より安全とされる理由を問う設問。", "point": "『危険なパターンを全部挙げる』のは事実上不可能に近いが、『正しい形式を挙げる』のは業務上できることが多い、という非対称性が決め手。", "kid": "ダメなものを全部挙げるのは大変だけど、正しいものを全部挙げるのはできることが多い、という違い。", "eg": "遊園地の入場ゲートにたとえられる。『持ち込み禁止物』を全部リストアップしようとすると新しい危険物が出るたびに追加が必要でキリがないが、『チケットを持っている人だけ通す』というルールなら、それだけで確実に線引きできる。", "terms": [["ホワイトリスト方式", "あらかじめ許可する正常なパターンを定義し、それ以外はすべて拒否する検証方式"], ["ブラックリスト方式", "危険とわかっているパターンを列挙し、それに一致するものだけを拒否する検証方式"]], "think": "なぜホワイトリスト方式のほうが安全なのかがカギ。ブラックリスト方式は『攻撃者がどんな入力を送ってくるか』を事前にすべて予測し、列挙できていることが前提になる。しかし攻撃の手口は日々工夫され、表記のゆらぎや新しい記法によって、列挙したパターンをすり抜ける入力が次々に生まれる。列挙が1つでも漏れれば、そこが突破口になる。一方ホワイトリスト方式は、正常な入力とはどういう形式か(例えば郵便番号は数字7桁、メールアドレスは決まった構造を持つ)を業務要件から先に定義できる場合が多く、その形式に一致しないものはすべて拒否すればよい。攻撃者側の手口を予測する必要がないため、未知の攻撃パターンにも自然に耐えられる。", "why_asked": "『禁止すべきものを列挙すればよい』という直感的だが漏れの起きやすい発想を選んでしまわないかを問う。", "vs": "処理速度や通信の暗号化とは無関係な話で、両方式の違いは『何を基準に許可・拒否を判定するか』という検証ロジックの組み立て方にある。", "opt": ["正解。危険なパターンを漏れなく列挙するのは難しいが、正常な形式は業務上定義しやすいため、ホワイトリスト方式のほうが未知の攻撃にも耐えやすい。", "文字数の長短や処理速度の話ではない。両方式の違いは、許可か拒否かをどちらの基準で判定するかという検証ロジックの組み立て方にある。", "ブラックリスト方式は通信の暗号化方式とは無関係であり、HTTPS通信でも問題なく使われる(ただし安全性はホワイトリスト方式に劣る)。", "ホワイトリスト方式はデータベースへの問い合わせ回数を減らす仕組みではない。入力値の形式を検証する仕組みである。"]}'),
  ('ap-core-q175', 'セキュリティ実装技術',
   'Webアプリケーションのセッション管理におけるセキュリティ上の注意点として、最も適切なものはどれか。',
   NULL::text,
   '["ログイン前に発行されていたセッションIDを認証成功後も使い続けないよう、ログイン成功の時点で新しいセッションIDを発行し直す", "セッションIDを利用者が推測しやすい連番にしておくことで、サポート窓口が電話口で本人確認をする際に照合しやすいようにしておく", "セッションIDをURLのパラメータに含めて画面遷移のたびに引き回すようにし、Cookieという仕組みを使わずに済むようにしておく", "一度発行したセッションIDは、利用者が自分でログアウトする操作をするまで、同じ値をずっと使い続けることが望ましいとされている"]',
   0,
   '[0]',
   'single',
   '{"asked": "セッション管理において、なぜログイン成功時にセッションIDを発行し直す必要があるのかを問う設問。", "point": "ログイン前後で同じセッションIDを使い続けない、ログイン成功時にセッションIDを発行し直すのが決め手(セッション固定化攻撃対策)。", "kid": "ログインする前に使っていた『整理券』を、ログインした後もそのまま使い続けさせない。ログインに成功した瞬間、新しい整理券に交換する。", "eg": "遊園地の整理券にたとえられる。攻撃者が先に整理券を取っておき、その番号を利用者に渡して『これで並んでおいて』と仕向け、利用者がその整理券のままログイン(本人確認)を済ませてしまうと、攻撃者は同じ番号の整理券を使って本人になりすませてしまう。ログイン成功のたびに整理券を新しいものに交換すれば、攻撃者が事前に用意した番号は無効になる。", "terms": [["セッションID", "ログイン中の利用者を識別するために、サーバーが発行する一時的な番号"], ["セッション固定化攻撃", "攻撃者が事前に用意したセッションIDを利用者に使わせ、ログイン後にそのIDを悪用してなりすます攻撃"]], "think": "なぜログイン成功時にセッションIDを発行し直す必要があるのかがカギ。セッション固定化攻撃では、攻撃者があらかじめ自分でセッションIDを取得しておき、何らかの方法(不正なリンクなど)でそのIDを利用者に押し付ける。利用者がそのセッションIDを使ったままログインに成功すると、サーバーは『そのセッションIDはログイン済みの利用者のもの』として扱うようになる。ここでセッションIDが発行し直されなければ、攻撃者は自分が最初から知っているそのセッションIDを使って、利用者になりすましてアクセスできてしまう。ログイン成功の時点で新しいセッションIDに切り替えれば、攻撃者が事前に知っていた古いIDはログイン後の状態と結び付かなくなり、なりすましが成立しなくなる。", "why_asked": "『セッションIDは一度発行したら変えないほうが安定する』という直感的だが誤った発想を問う。", "vs": "推測しやすい連番のセッションIDや、URLに含めて引き回す方式は、いずれもセッションIDの漏えい・推測のリスクを高める点で、発行し直しとは別の観点の不備である。", "opt": ["正解。ログイン前後で同じセッションIDを使い続けると、攻撃者が事前に用意したIDでなりすませてしまうため、ログイン成功時に発行し直す。", "セッションIDを推測しやすくすることは、他人によるなりすましのリスクを高めるだけであり、本人確認の効率化を理由に採用してよい設計ではない。", "セッションIDをURLに含めると、閲覧履歴やアクセスログ、リンク共有などを通じて第三者に漏れる経路が増えてしまう。Cookieを避ける理由にはならない。", "同じセッションIDを使い続けることは、セッション固定化攻撃を成立させやすくする。ログイン成功時に発行し直すことが望ましい。"]}'),
  ('ap-core-q176', 'セキュリティ実装技術',
   'Webアプリケーションがログインセッションを維持するために発行するCookieの属性に関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["HttpOnly属性を付けると、JavaScriptからCookieの値を読み取れなくなり、XSSによるセッションID窃取のリスクを減らせる", "Secure属性を付けると、Cookieの値そのものが常に暗号化された状態でブラウザ側に保存されるようになる仕組みがそこで働き出す仕様である", "SameSite属性を付けると、Cookieの有効期限がそのぶん自動的に延長されるようになり、利用者が再ログインする手間がその分だけ省ける", "HttpOnly属性を付けると、Cookieに設定できるサイズの上限そのものがなくなり、より多くの情報をセッションに持たせられるようになる"]',
   0,
   '[0]',
   'single',
   '{"asked": "ログインセッション用Cookieに設定するHttpOnly・Secure・SameSiteの各属性が、それぞれ何を防ぐための仕組みかを問う設問。", "point": "HttpOnlyは『JavaScriptからCookieを読めなくする』。Secureは『HTTPS通信でしか送らない』。SameSiteは『別サイトからの送信を制限する』。Cookieの値自体を暗号化したり、有効期限を延ばしたりする属性ではない。", "kid": "HttpOnlyは、Cookieの中身をページ上のプログラム(JavaScript)からは見えなくする鍵。", "eg": "HttpOnlyは、宅配ボックスの暗証番号を『配達員には知らせるが、通りすがりの人が押しても開かない』ようにする仕組みにたとえられる。ページ上で動くJavaScriptが通りすがりの人にあたり、暗証番号(セッションID)を勝手に読み出せないようにする。", "terms": [["HttpOnly属性", "JavaScriptなどページ上のスクリプトからCookieの値を読み取れなくする属性"], ["Secure属性", "HTTPSなど暗号化された通信のときだけCookieを送信するようにする属性"], ["SameSite属性", "別のWebサイトからのリクエストにCookieを自動的に付けて送らないよう制限する属性"]], "think": "なぜHttpOnly属性がクロスサイトスクリプティング(XSS)対策として意味を持つのかがカギ。XSSは攻撃者が仕込んだスクリプトが被害者のブラウザ上で動いてしまう攻撃であり、そのスクリプトがログインセッションのCookieを読み取れれば、攻撃者はそのセッションIDを盗んでなりすましに使える。HttpOnly属性を付けたCookieは、ページ上で動くJavaScriptからは値を取得する手段そのものが用意されていないため、たとえXSSでスクリプトを実行されても、そのスクリプトはCookieの値に手を出せない。つまりHttpOnlyは『XSSを起こさせない対策』ではなく、『XSSが起きてしまった場合の被害(セッションID窃取)を減らす対策』として働く。", "why_asked": "Secure属性を『値の暗号化』、SameSite属性を『有効期限の延長』と取り違える、名前から連想しやすい誤解を問う。", "vs": "Secure属性は通信経路(HTTPSかどうか)を条件にする属性であり、Cookieの値そのものを暗号化するものではない点がHttpOnlyと異なる。", "opt": ["正解。HttpOnly属性を付けるとJavaScriptからCookieの値を読み取れなくなり、XSSが起きた場合のセッションID窃取のリスクを減らせる。", "Secure属性はHTTPSなど暗号化された通信のときだけCookieを送信する条件を付ける属性であり、値そのものを暗号化して保存するわけではない。", "SameSite属性は別サイトからのリクエストにCookieを自動送信することを制限する属性であり、有効期限の延長とは無関係である。", "HttpOnly属性はJavaScriptからの読み取りを制限する属性であり、Cookieのサイズ上限を変更する仕組みではない。"]}'),
  ('ap-core-q177', 'セキュリティ実装技術',
   'コンテナを本番環境にデプロイする前に、コンテナイメージに含まれるOSパッケージやライブラリの脆弱性をスキャンし、CI/CDパイプラインの一部に組み込んでおくことの主な目的として、最も適切なものはどれか。',
   NULL::text,
   '["既知の脆弱性を持つコンポーネントを本番環境に配置する前の段階で検出し、より早い工程で修正できるようにするため", "コンテナイメージのファイルサイズをできるだけ小さく圧縮しておき、レジストリへのアップロードにかかる時間を短縮するため", "コンテナ起動時に割り当てるCPUやメモリの量を、そのときどきの負荷に応じて自動的に最適化するため", "コンテナ間で行われる通信を暗号化するための証明書を、スキャンの過程を通じて自動的に発行するため"]',
   0,
   '[0]',
   'single',
   '{"asked": "コンテナイメージの脆弱性スキャンをCI/CDパイプラインに組み込む目的を問う設問。", "point": "『本番に置く前に、既知の脆弱性を早期に検出する』が目的の核心。圧縮・リソース最適化・証明書発行とは無関係。", "kid": "コンテナの中身(OSやライブラリ)に、もう知られている弱点がないかを、本番で動かす前にチェックしておく仕組み。", "eg": "新しく仕入れた食材を、店で調理して客に出す前に検品するようなものにたとえられる。すでに『傷んでいる』とわかっている食材を、客に届く前の検品段階で見つけて弾ければ、食中毒(本番障害・侵害)を未然に防げる。届けてから気づくのでは手遅れになりやすい。", "terms": [["脆弱性スキャン", "ソフトウェアの構成要素に、既に知られている弱点(CVEなど)が含まれていないかを自動的に調べること"], ["CI/CDパイプライン", "コードの変更からビルド・テスト・デプロイまでを自動化して流す一連の仕組み"], ["シフトレフト", "不具合や脆弱性への対応を、開発工程のより早い段階(左側)で行おうとする考え方"]], "think": "なぜデプロイ前の段階でスキャンする必要があるのかがカギ。コンテナイメージにはOSのパッケージやアプリケーションが使うライブラリが含まれており、そのどれかに既知の脆弱性が見つかることがある。もし本番環境で動き始めた後にその脆弱性が発覚すると、既に外部から攻撃を受けられる状態でしばらく稼働していたことになり、影響範囲の調査や緊急の差し替え作業が必要になって対応コストが大きくなる。CI/CDパイプラインの中でイメージをビルドした直後にスキャンし、既知の脆弱性が見つかったらその時点でデプロイを止めるようにしておけば、脆弱性を持ったイメージがそもそも本番に到達しない。問題をより早い工程で見つけるほど、修正にかかる手間と被害の両方を小さく抑えられる。", "why_asked": "脆弱性スキャンの目的を、性能最適化やファイルサイズ削減といった無関係な効率化の話とすり替えていないかを問う。", "vs": "イメージの軽量化やリソース割り当ての最適化は別の運用上の工夫であり、脆弱性スキャンが直接目指す目的ではない。", "opt": ["正解。既知の脆弱性を持つコンポーネントを、本番に配置する前のより早い工程で検出し、被害と修正コストの両方を抑えるために行う。", "ファイルサイズの圧縮やアップロード時間の短縮は、イメージの軽量化に関する別の工夫であり、脆弱性スキャンの目的ではない。", "CPU・メモリの割り当て最適化はリソース管理の話であり、脆弱性スキャンとは別の仕組み(オートスケーリングなど)が担う役割である。", "脆弱性スキャンは既知の脆弱性の有無を調べる仕組みであり、通信の暗号化に使う証明書を発行する機能は持たない。"]}'),
  ('ap-core-q178', 'セキュリティ実装技術',
   'コンテナを実行する際のセキュリティ対策として、コンテナ内のプロセスをroot(特権)ユーザーではなく一般ユーザーの権限で動かすことが推奨される理由として、最も適切なものはどれか。',
   NULL::text,
   '["コンテナ内のプロセスが侵害された場合に、攻撃者がそのコンテナ内で行える操作の範囲を狭め、ホスト側への影響も抑えやすくなるから", "一般ユーザー権限で動かすようにすると、コンテナの起動速度がroot権限で動かす場合と比べてはっきりと速くなるから", "一般ユーザー権限で動かすようにすると、コンテナイメージのビルドにかかる時間がroot権限で動かす場合より短くなるから", "root権限を使うと課金体系そのものが変わってしまうクラウドサービスも存在するため、コストを抑える目的で一般ユーザー権限を使うから"]',
   0,
   '[0]',
   'single',
   '{"asked": "コンテナ内のプロセスを一般ユーザー権限で動かすことが推奨される理由を問う設問。", "point": "侵害されたときに攻撃者が『できること』の範囲を狭める、というのが決め手。速度やコストの話ではない。", "kid": "コンテナの中を動かすプログラムに、なんでもできる強い権限を持たせない。もし乗っ取られても、できることを少なくしておく。", "eg": "貸し会議室の鍵にたとえられる。利用者にビル全体の鍵(root権限)を渡してしまうと、その利用者になりすました人が現れたときにビル全体に入られてしまう。会議室の鍵(一般ユーザー権限)だけ渡しておけば、なりすまされても被害はその会議室にとどまる。", "terms": [["root(特権)ユーザー", "OS上でほぼすべての操作が許可されている、最も強い権限を持つユーザー"], ["コンテナブレイクアウト", "コンテナ内から、本来隔離されているはずのホストOS側へ影響を及ぼしてしまうこと"]], "think": "なぜroot権限で動かすことがリスクになるのかがカギ。コンテナは通常、ホストOSのカーネルを他のコンテナと共有しながら動いている。もしコンテナ内で動くアプリケーションに脆弱性があり、そこを突かれてプロセスを乗っ取られた場合、攻撃者はそのプロセスが持っていた権限をそのまま引き継ぐ。プロセスがroot権限で動いていれば、コンテナ内のファイルやプロセスを自由に操作できるだけでなく、設定によってはホスト側のリソースにまで影響を及ぼす経路(コンテナブレイクアウト)が使われる懸念も高まる。プロセスを一般ユーザー権限に絞っておけば、たとえ乗っ取られても、そのユーザーに許可されている範囲を超えた操作はできず、被害をコンテナ内の限られた範囲にとどめやすくなる。", "why_asked": "『動作を安定させるために強い権限を持たせておく』という運用上の直感と、セキュリティ上望ましい設定が逆になっていないかを問う。", "vs": "起動速度やビルド時間、課金体系はいずれも実行ユーザーの権限とは別の要因で決まり、一般ユーザー権限を推奨する理由ではない。", "opt": ["正解。プロセスが侵害された際に攻撃者ができる操作の範囲を狭め、ホスト側への影響も抑えやすくなるため、一般ユーザー権限での実行が推奨される。", "起動速度は実行ユーザーの権限ではなく、イメージの構成やリソース割り当てなど別の要因で決まる。権限を絞ることが速度向上の理由ではない。", "ビルド時間はイメージの構築工程で決まるものであり、コンテナ実行時のユーザー権限とは無関係である。", "実行ユーザーの権限とクラウドサービスの課金体系は無関係である。一般ユーザー権限を使う目的はコスト削減ではなくセキュリティである。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">実行ユーザーと、侵害されたときの影響範囲</text>\n<rect x=\"8\" y=\"24\" width=\"324\" height=\"112\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"20\" y=\"38\" fill=\"#8892a4\" font-size=\"7.5\">ホストOS(カーネルを共有する土台)</text>\n<circle cx=\"95\" cy=\"92\" r=\"52\" fill=\"#2a2f3f\" stroke=\"#c47070\" stroke-width=\"1.5\"/>\n<text x=\"95\" y=\"78\" fill=\"#c47070\" font-size=\"8.3\" text-anchor=\"middle\" font-weight=\"600\">rootで実行</text>\n<text x=\"95\" y=\"92\" fill=\"#e8eaf0\" font-size=\"7.3\" text-anchor=\"middle\">侵害されると</text>\n<text x=\"95\" y=\"103\" fill=\"#e8eaf0\" font-size=\"7.3\" text-anchor=\"middle\">広い範囲まで</text>\n<text x=\"95\" y=\"114\" fill=\"#e8eaf0\" font-size=\"7.3\" text-anchor=\"middle\">操作されうる</text>\n<circle cx=\"248\" cy=\"92\" r=\"34\" fill=\"#2a2f3f\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/>\n<text x=\"248\" y=\"82\" fill=\"#6ab08d\" font-size=\"8.3\" text-anchor=\"middle\" font-weight=\"600\">一般ユーザー</text>\n<text x=\"248\" y=\"96\" fill=\"#e8eaf0\" font-size=\"7.3\" text-anchor=\"middle\">できる操作を</text>\n<text x=\"248\" y=\"107\" fill=\"#e8eaf0\" font-size=\"7.3\" text-anchor=\"middle\">狭く抑えられる</text>\n<text x=\"170\" y=\"146\" fill=\"#8892a4\" font-size=\"7.8\" text-anchor=\"middle\">同じ侵害が起きても、権限を絞るほど攻撃者にできることは狭くなる</text>\n</svg>"}'),
  ('ap-core-q179', 'セキュリティ実装技術',
   'SQLインジェクション、クロスサイトスクリプティング、OSコマンドインジェクションなど、性質の異なる複数の脆弱性に共通する根本的な原因として、最も適切なものはどれか。',
   NULL::text,
   '["外部から渡された入力値を、検証や適切な処理をしないまま、SQL文やHTML、OSコマンドなど別の言語の一部として組み込んでしまうこと", "いずれの脆弱性も、通信経路が暗号化されていないことそのものが直接の原因であるため、通信をHTTPS化することで根本的に解消されていく", "いずれの脆弱性も、サーバーのCPU性能がそもそも不足していることが根本の原因であり、性能を強化することで発生しなくなっていく", "いずれの脆弱性も、利用者のパスワードの強度がもともと低いことが根本の原因であり、パスワードポリシーを強化すれば防ぐことができる"]',
   0,
   '[0]',
   'single',
   '{"asked": "性質の異なる複数の脆弱性(SQLインジェクション・XSS・OSコマンドインジェクション)に共通する根本原因を問う設問。", "point": "『外部からの入力を、検証しないまま別の言語(SQL・HTML・OSコマンド)の一部として組み込んでしまう』という構造が共通の根本原因。", "kid": "どれも『利用者が入力した文字』を、そのまま『コンピュータへの命令の一部』として扱ってしまうところが問題。", "eg": "どれも同じ形の落とし穴にたとえられる。伝言メモに書かれた内容を、そのまま『指示』として読み上げてしまう受付係のようなもの。メモには本来ただの伝言(データ)が書いてあるだけのはずなのに、受付係(プログラム)がそれを命令だと思い込んで実行してしまうと、メモを書いた人の思うままに操られてしまう。SQL文、HTML、OSコマンド、それぞれ『命令として読み上げる先』が違うだけで、落とし穴の形は同じ。", "terms": [["OSコマンドインジェクション", "入力値を通じてOSのコマンドを不正に実行させる攻撃"], ["信頼境界", "自分の管理が及ぶ範囲(信頼できる領域)と、外部から来た制御できないデータの境目"]], "think": "なぜこれらの脆弱性に共通の原因があるといえるのかがカギ。SQLインジェクションは入力値がSQL文の一部として、クロスサイトスクリプティングは入力値がHTMLやJavaScriptの一部として、OSコマンドインジェクションは入力値がOSへの命令の一部として、それぞれ解釈されてしまうことで起きる。攻撃対象になる『言語』は違っても、共通しているのは、外部から来た制御できない入力値(データ)を、検証や無害化の処理をしないまま、何らかの命令や構文の一部としてそのまま組み込んでしまっているという構造である。プログラムが『これは信頼できないデータだ』という前提に立ち、命令を組み立てる場所へ渡す前に必ず検証・分離・無害化を行っていれば、入力値がどんな内容であっても命令として実行される余地はない。だから、これらの脆弱性を防ぐ出発点は『外部からの入力は信用しない』という原則に行き着く。", "why_asked": "個別の脆弱性の対策(バインド変数、出力エスケープなど)を覚える前に、その根っこにある共通原則を理解しているかを問う。", "vs": "通信の暗号化やサーバー性能、パスワード強度は、これらの脆弱性が起きるかどうかを直接左右する要因ではない。原因は入力値の扱い方にある。", "opt": ["正解。外部からの入力値を検証しないまま別の言語(SQL・HTML・OSコマンドなど)の一部として組み込んでしまう構造が、これらの脆弱性に共通する根本原因である。", "通信の暗号化はデータが盗聴・改ざんされることを防ぐものであり、入力値が命令として誤解釈されること自体は防がない。HTTPS化だけでは解決しない。", "サーバーの性能不足はこれらの脆弱性の原因ではない。性能を強化しても入力値の扱い方が変わらなければ脆弱性は残る。", "パスワードの強度は認証を突破されるリスクに関わるものであり、入力値が命令として誤解釈されるこれらの脆弱性とは別の問題である。"]}'),
  ('ap-core-q180', 'セキュリティ実装技術',
   '利用者が入力した文字列をWebページ上に表示する機能において、クロスサイトスクリプティング(XSS)を防ぐための実装として、最も適切なものはどれか。',
   NULL::text,
   '["HTMLとして出力する直前に、「<」や「>」などHTML上で特別な意味を持つ文字を、表示用の別の記号(エンティティ)に変換してから出力する", "入力欄にあらかじめ文字数制限を設けておき、一定の文字数を超える入力を拒否することで、悪意あるスクリプトの入力自体を防ぐようにする", "入力値をデータベースに保存する際に必ずバインド変数を使うようにし、その値がSQL文の一部として解釈されないようにしておく", "利用者が入力した文字列を、ページを表示するたびごとにサーバー側であらかじめ暗号化しておき、その暗号化された状態のまま画面に埋め込むようにする"]',
   0,
   '[0]',
   'single',
   '{"asked": "クロスサイトスクリプティング(XSS)を防ぐための実装として、何をすべきかを問う設問。", "point": "HTMLへ出力する直前に、特別な意味を持つ文字を無害な表示用の記号に変換する『出力時のエスケープ(エンコード)』が決め手。SQLインジェクション対策(バインド変数)とは対策の場所も方法も違う。", "kid": "画面に表示する直前に、『<』のような特別な意味を持つ記号を、ただの見た目の記号に変換してから表示する。", "eg": "演劇の台本にたとえられる。台詞に『(拍手)』という指示が紛れ込んでいても、それをそのまま『拍手をせよ』という演出指示として実行してしまうと台本が乗っ取られる。『(拍手)』という文字列を、演出指示ではなく『そのまま読み上げるだけの台詞』として扱うように変換しておけば、指示のふりをした文字列に台本を操られることはない。", "terms": [["クロスサイトスクリプティング(XSS)", "利用者の入力などを通じて悪意あるスクリプトをWebページに埋め込み、他の利用者のブラウザ上で実行させる攻撃"], ["エスケープ(エンコード)", "HTML上で特別な意味を持つ文字を、その意味を持たない別の表示用の記号に変換すること"]], "think": "なぜ『出力する直前』にエスケープすることが正しい対策なのかがカギ。XSSは、利用者が入力した文字列がHTMLとしてブラウザに渡されたときに、ブラウザがその文字列の一部を『タグ』や『スクリプト』という命令として解釈してしまうことで起きる。入力を受け取った時点で拒否したり短くしたりしても、危険な記号そのものを許可された文字数の中に収めることは難しくなく、入力の制限だけでは防ぎきれない。一方、HTMLとして画面に書き出す直前に、『<』『>』のようにHTML上で意味を持つ文字を、その意味を持たない表示用の記号に変換しておけば、ブラウザはそれを命令ではなく、ただの文字として画面に表示する。入力された内容がどんなものであっても、出力の瞬間に無害な形に変換されるため、命令として実行される余地がなくなる。だから対策の要は入力の制限ではなく、出力時のエスケープにある。", "why_asked": "SQLインジェクション対策(バインド変数)とXSS対策(出力エスケープ)を混同していないか、対策を打つべき場所を取り違えていないかを問う。", "vs": "バインド変数はSQL文への組み込み時点の対策であり、HTMLへの出力時点で効くXSS対策とは対策する場所も仕組みも異なる。", "opt": ["正解。HTMLとして出力する直前に特別な意味を持つ文字を表示用の記号に変換しておけば、入力内容がどんなものでも命令として実行されることはない。", "文字数制限は入力できる文字の量を制限するだけであり、短い危険な記号の入力までは防げない。XSS対策として十分ではない。", "バインド変数はSQL文への組み込み時に効くSQLインジェクション対策であり、HTMLへの出力時に起きるXSSへの対策にはならない。", "文字列を暗号化して埋め込むと、画面にはそのまま元の文字列として表示できなくなる。暗号化はHTML上の特殊文字を無害化する仕組みではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
